window.HT = window.HT || {}; HT.CDF = HT.CDF || {};
HT.CDF["G10"] = {"bang":[{"i":0,"tieu_de_bang":"Thái Lan – Thầu Chín","tieu_de":"Ông Thầu Chín bên dòng Mê Kông: hơn một năm Nguyễn Ái Quốc sống giữa kiều bào đất Xiêm","sapo":"Mùa hè năm 1928, các xóm Việt kiều ở Xiêm có thêm một người đàn ông đội nón, đi dép, được bà con gọi thân mật là Thầu Chín. Ông cày ruộng, đào giếng, tối đến lại ngồi dạy chữ bên ngọn đèn dầu. Ít ai trong xóm biết rằng người mà mật thám Pháp đang ráo riết truy tìm khắp châu Á đang sống ngay giữa họ. Gian trưng bày này đưa bạn trở lại hơn một năm lặng lẽ mà quyết định ấy.","bia":{"src":"textures/bai/G10_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Người đàn ông đội nón, đi dép","text":"Hãy hình dung một xóm nhỏ của người Việt ở vùng đông bắc Xiêm cuối những năm 1920: những nếp nhà gỗ mái lá, giếng nước giữa sân, ruộng lúa trải ra phía ngoài, giọng nói quê nhà lẫn với tiếng Xiêm. Mùa hè năm 1928, xóm có thêm một người mới. Ông đội nón, đi dép, ăn mặc như mọi người lao động, ra đồng cùng bà con, xắn tay đào giếng, góp sức dựng nhà. Bà con gọi ông là Thầu Chín, một cách gọi thân mật và kính trọng.\n\nNgười đàn ông ấy chính là Nguyễn Ái Quốc, người sáng lập Hội Việt Nam Cách mạng Thanh niên, cán bộ của Quốc tế Cộng sản, người mà mật thám Pháp đã theo dõi suốt từ Paris tới Quảng Châu. Từ tháng 7/1928 đến tháng 11/1929, ông Thầu Chín đi qua nhiều tỉnh của nước Xiêm, sống lẫn trong các cộng đồng kiều bào và gây dựng ở đó những cơ sở cách mạng nối với quê nhà. Đây là một trong những quãng đời ít được kể nhất, nhưng cũng gần gũi nhất, trong hành trình ba mươi năm tìm đường cứu nước của Người, từ năm 1911 đến năm 1941.","doc":1},{"loai":"doan","tieu_de":"Năm 1927: con đường về gần bị cắt đứt","text":"Để hiểu vì sao Người có mặt ở Xiêm, phải lùi lại một năm. Từ cuối năm 1924, Nguyễn Ái Quốc làm việc ở Quảng Châu. Tại đây, Người mở các lớp huấn luyện cho thanh niên yêu nước từ trong nước sang, lập ra Hội Việt Nam Cách mạng Thanh niên vào tháng 6/1925 và ra tờ báo Thanh Niên. Những bài giảng của Người ở đây được in thành cuốn Đường Kách mệnh năm 1927. Quảng Châu khi ấy là trung tâm của cách mạng Trung Quốc, cũng là nơi gần Tổ quốc nhất mà Người có thể đặt chân.\n\nTháng 4/1927, mọi thứ đảo lộn. Ngày 12/4, Tưởng Giới Thạch làm chính biến ở Thượng Hải; chỉ ba ngày sau, cuộc khủng bố lan tới Quảng Châu, nhiều người cộng sản bị bắt, bị giết. Tháng 5/1927, Nguyễn Ái Quốc buộc phải rời Quảng Châu và trở lại Mátxcơva. Các học trò của Người vẫn duy trì Hội Thanh niên, còn Người thì bị đẩy ra xa phương Đông, xa những người mà Người đã dày công đào tạo. Từ đó, điều Người canh cánh nhất là làm sao trở lại gần Tổ quốc càng sớm càng tốt.","doc":2},{"loai":"anh","src":"textures/bang_w/G10_0_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Thái Lan – Thầu Chín”, nhìn từ xa."},{"loai":"doan","tieu_de":"Vòng qua châu Âu để về châu Á","text":"Ở Mátxcơva, Người tiếp tục làm việc trong bộ máy của Quốc tế Cộng sản, nhưng lòng vẫn hướng về phương Đông. Cuối năm 1927, Người rời Liên Xô sang châu Âu. Tháng 12/1927, Người có mặt ở Brúcxen, thủ đô nước Bỉ, dự một hội nghị của Liên đoàn chống đế quốc, tổ chức tập hợp đại biểu nhân dân nhiều nước thuộc địa. Những tháng sau đó, Người đi qua Pháp, Đức, Thụy Sĩ, Ý, trong điều kiện luôn bị cảnh sát các nước để mắt.\n\nGiữa năm 1928, Người lên tàu trở lại châu Á. Con đường thẳng về Việt Nam lúc này không thể đi: Đông Dương là thuộc địa Pháp, còn Hương Cảng, Thượng Hải đều có mật thám theo dõi gắt gao. Người chọn một cánh cửa khác, kín đáo hơn, là vương quốc Xiêm. Tháng 7/1928, Người đặt chân tới Bangkok. Từ thủ đô Xiêm, Người không ở lại thành phố mà tìm ngay tới những nơi có đông đồng bào mình sinh sống: các xóm Việt kiều ở miền bắc và đông bắc đất nước này.","doc":3},{"loai":"doan","tieu_de":"Xiêm, khoảng trống trên bản đồ thuộc địa","text":"Cuối những năm 1920, gần như cả Đông Nam Á đã bị các cường quốc phương Tây chia nhau: Miến Điện và Mã Lai thuộc Anh, quần đảo Đông Ấn thuộc Hà Lan, Philippines thuộc Mỹ, còn Việt Nam, Lào, Campuchia nằm trong Liên bang Đông Dương của Pháp. Xiêm là vương quốc duy nhất trong khu vực giữ được độc lập. Để giữ được nền độc lập ấy, triều đình Xiêm đã phải nhượng nhiều vùng đất. Theo hiệp ước năm 1893, vùng tả ngạn sông Mê Kông về tay Pháp, và dòng sông trở thành biên giới giữa Xiêm với xứ Lào thuộc Pháp.\n\nNăm 1928, Xiêm vẫn là nước quân chủ chuyên chế dưới triều vua Prajadhipok, tức vua Rama VII. Pháp có cơ quan ngoại giao ở Bangkok và có tai mắt trong các cộng đồng người Việt, nhưng cảnh sát Pháp không thể tự do bắt người trên đất Xiêm như ở Đông Dương. Với một người bị truy nã, đó là lợi thế lớn. Lợi thế thứ hai là vị trí: từ các tỉnh đông bắc Xiêm, chỉ cần vượt sông sang Lào, băng qua dãy Trường Sơn là tới Nghệ An, Hà Tĩnh, Quảng Bình. Lợi thế thứ ba, quan trọng nhất, là con người: ở đó có đông đảo kiều bào Việt Nam.","doc":4},{"loai":"ban_co_biet","text":"“Thầu Chín” thường được giải thích là “ông già Chín”, một cách gọi thân mật dành cho người lớn tuổi. Thật ra, năm 1928 Nguyễn Ái Quốc mới 38 tuổi.","nguon_ten":"Bảo tàng Hồ Chí Minh; Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","doc":5},{"loai":"doan","tieu_de":"Những xóm Việt ở xứ Isan","text":"Người Việt đã có mặt ở Xiêm từ nhiều thế kỷ trước, nhưng các xóm Việt ở vùng đông bắc, tức xứ Isan, phần lớn hình thành từ cuối thế kỷ XIX, đầu thế kỷ XX. Sau khi phong trào Cần Vương bị dập tắt, nhiều nghĩa sĩ cùng gia đình họ tìm đường qua Lào, vượt sông Mê Kông sang Xiêm lánh nạn. Tiếp đó là những người của phong trào Đông Du và Duy Tân. Khoảng năm 1910, chính cụ Phan Bội Châu cũng sang Xiêm, cùng các đồng chí khai phá đất làm “trại cày” để nuôi dưỡng thanh niên yêu nước chờ thời.\n\nHọ dựng xóm ở Phichit, Udon Thani, Sakon Nakhon, Nakhon Phanom, Nong Khai, sống bằng nghề làm ruộng, trồng rau, làm thợ. Họ giữ tiếng nói, giữ nếp nhà, giữ ngày giỗ, ngày Tết của quê hương. Phần đông nghèo và ít học, nhưng những mất mát của thế hệ cha anh khiến lòng hướng về Tổ quốc của họ chưa bao giờ nguội. Trước khi Người đến, Hội Việt Nam Cách mạng Thanh niên đã cử cán bộ sang gây dựng cơ sở trong các xóm này. Khi ông Thầu Chín tới, mảnh đất đã được vỡ, chỉ còn chờ người biết gieo hạt.","doc":6},{"loai":"anh","src":"textures/ht/ht_anh_house_hochiminh_stayed_nakhonphanom.jpg","chu_thich":"Ngôi nhà gỗ mái lá Người từng ở tại Nakhon Phanom, được kiều bào phục dựng theo dáng nhà xưa. Ảnh: BacLuong, CC BY 4.0, Wikimedia Commons.","credit":"Ảnh: BacLuong at Vietnamese Wikipedia · CC BY 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Từ Bangkok đến Bản Đông","text":"Từ Bangkok, Người đi lên phía bắc, tìm đến Bản Đông, một xóm Việt kiều thuộc tỉnh Phichit, vùng đồng bằng ven sông Nan. Đó là chặng dừng chân đầu tiên, và cũng từ chặng này cái tên Thầu Chín bắt đầu gắn với Người. Theo báo Nhân Dân, Người ở Bản Đông khoảng mười lăm ngày, đủ để gặp gỡ những người cốt cán, tìm hiểu đời sống và tâm tư của kiều bào. Rồi từ Phichit, Người đi tiếp lên cao nguyên Khorat ở đông bắc, nơi có những cộng đồng người Việt đông hơn cả.\n\nChặng đường ấy phần lớn đi bộ, băng qua rừng núi, có khi phải ngủ lại giữa rừng (xem chuyên đề “Những chặng đường đi bộ”). Ở Udon Thani, Người sống và hoạt động trong các xóm Việt kiều ở vùng Nong Bua và bản Nong On. Từ Udon, Người còn tới Sakon Nakhon, Nong Khai, rồi xuôi về Nakhon Phanom bên bờ Mê Kông, nơi Người dừng chân lâu nhất. Ở mỗi nơi, Người sống lẫn giữa bà con, không có chỗ ở tách biệt, không nhận sự phục dịch riêng, tự làm lấy mọi việc như một người lao động. Trong những lời kể của kiều bào về sau, cái tên Thầu Chín vì thế luôn gắn với những việc rất cụ thể của đời thường.","doc":7},{"loai":"doan","tieu_de":"Một ngày của ông Thầu Chín","text":"Ở đâu, ông Thầu Chín cũng sống như người trong xóm. Sáng ra đồng hoặc làm vườn, trồng rau, trồng chuối; khi xóm cần giếng thì cùng bà con đào giếng; khi có nhà cần dựng thì góp tay dựng nhà. Ăn uống đạm bạc, chỗ nằm là giường tre hay tấm phản gỗ. Chính lối sống ấy khiến bà con tin cậy, và cũng là lớp áo che mắt mật thám tốt nhất (xem chuyên đề “Ngôi nhà của Thầu Chín”).\n\nBuổi tối là thời gian của những công việc khác. Người mở lớp dạy chữ quốc ngữ cho trẻ em và người lớn, dịch sách, viết bài cho tờ báo của kiều bào (xem chuyên đề “Lớp học đèn dầu và tờ báo Thân Ái”). Người đề nghị xây dựng những hội quần chúng hợp với nếp sống của bà con: Hội Thân ái để tập hợp kiều bào, Hội Hợp tác để giúp nhau làm ruộng, làm thợ. Trong các hội ấy, những người hăng hái nhất được chọn lọc, bồi dưỡng dần để trở thành cốt cán của Hội Việt Nam Cách mạng Thanh niên. Người cũng khuyên kiều bào sống hòa thuận với người Xiêm, tôn trọng phong tục và luật lệ của nơi mình đang sống.","doc":8},{"loai":"anh","src":"textures/bang_w/G10_0_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Thái Lan – Thầu Chín”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Bản Mạy, chặng dừng lâu nhất","text":"Theo Bảo tàng Hồ Chí Minh, Người hoạt động ở Nakhon Phanom từ khoảng cuối tháng 7 đến cuối tháng 10/1929. Làng Nachok, mà kiều bào quen gọi là bản Mạy, tức “làng mới”, là nơi Người ở lâu nhất trên đất Xiêm. Người đã gây dựng phong trào kiều bào ở đây, biến bản Mạy thành một trong những địa điểm quan trọng của Hội Việt Nam Cách mạng Thanh niên. Bảo tàng Hồ Chí Minh cho biết nơi này còn lưu giữ những dấu tích của Người, trong đó có những gốc cây do chính tay Người trồng.\n\nVị trí của bản Mạy giải thích vì sao nơi này quan trọng. Nakhon Phanom nằm ngay bờ Mê Kông; bên kia sông là Thà Khẹt của xứ Lào thuộc Pháp. Theo con đường qua sông, qua Lào, vượt Trường Sơn, người và tài liệu có thể đi về các tỉnh miền Trung (xem chuyên đề “Sông Mê Kông”). Những tin tức từ quê nhà cũng theo đường ấy mà sang. Và chính trong những tháng ở bản Mạy, những tin tức ấy đã khiến ông Thầu Chín quyết định lên đường.","doc":9},{"loai":"ban_co_biet","text":"Ở Xiêm, ngoài tên Thầu Chín, Người còn được một số kiều bào biết đến với tên gọi ông Thọ.","nguon_ten":"Báo Nhân Dân, “Hình bóng Bác mãi in đậm ở Thái Lan”, 19/5/2016","doc":10},{"loai":"doan","tieu_de":"Rời đất Xiêm","text":"Năm 1929, tin từ trong nước cho biết phong trào cộng sản ở quê nhà đã hình thành ba tổ chức riêng rẽ, mỗi nơi một ngả, có lúc còn công kích lẫn nhau. Ngày 27/10/1929, Quốc tế Cộng sản gửi thư yêu cầu những người cộng sản Đông Dương lập một đảng duy nhất. Tháng 11/1929, ông Thầu Chín từ biệt bà con, rời Xiêm. Theo báo cáo Người gửi Quốc tế Cộng sản ngày 18/2/1930, Người đến Hương Cảng ngày 23/12/1929. Từ ngày 6/1 đến 7/2/1930, Người chủ trì hội nghị hợp nhất tại Cửu Long, thành lập Đảng Cộng sản Việt Nam (xem chuyên đề “Tin từ quê nhà và chuyến đi cuối năm 1929”).\n\nHơn một năm ở Xiêm vì thế không phải là một chặng nghỉ chân. Đó là những tháng Người trực tiếp làm công tác quần chúng ở cơ sở: sống cùng, làm cùng, học cùng những người lao động nghèo, gây dựng tổ chức từ những việc nhỏ nhất như đào một cái giếng, lập một hội tương trợ. Kinh nghiệm ấy theo Người về tới Pác Bó năm 1941, và còn vang lên trong những lời Người căn dặn cán bộ nhiều năm sau về cách gần gũi, lắng nghe và học hỏi nhân dân.","doc":11},{"loai":"anh","src":"textures/ht/ht_anh_ho_chi_minh_nakhonphanom_coco.jpg","chu_thich":"Hàng dừa trong khuôn viên khu lưu niệm Hồ Chí Minh ở Nakhon Phanom, ảnh chụp năm 2010. Ảnh: BacLuong, CC BY-SA 4.0, Wikimedia Commons.","credit":"Ảnh: BacLuong · CC BY-SA 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Gần một thế kỷ đã qua, những nơi ông Thầu Chín từng đặt chân vẫn được kiều bào và bạn bè Thái Lan gìn giữ. Ở bản Nong On, tỉnh Udon Thani, khu di tích có ngôi nhà phục dựng theo dáng nơi Người ở năm xưa, được hoàn thành năm 2002. Ở Bản Đông, tỉnh Phichit, một ngôi nhà sàn gỗ được dựng lại cùng tượng bán thân của Người. Ở bản Mạy, Nakhon Phanom, khu tưởng niệm rộng khoảng 1,2 héc-ta được khánh thành ngày 19/5/2016, đúng dịp kỷ niệm 126 năm ngày sinh của Người (xem chuyên đề “Nhà lưu niệm Hồ Chí Minh ở bản Mạy, Nakhon Phanom”).\n\nGian trưng bày này dựng lại một xóm Việt kiều bên sông Mê Kông những năm 1928 – 1929. Khách tham quan có thể bước vào ngôi nhà gỗ mái lá, nhìn chiếc phản, bàn viết, ngọn đèn dầu và tập giấy ghi chép; ra sân xem chiếc giếng, thùng gỗ, chum nước, chiếc mai đào đất; rồi phóng tầm mắt về phía dãy núi đá vôi bên bờ Lào. Tất cả đều là đồ vật minh họa, nhưng mỗi thứ gắn với một việc có thật về cách sống giản dị mà Nguyễn Ái Quốc đã chọn, giữa những con người mà Người gọi là đồng bào.","doc":12},{"loai":"anh","src":"textures/bang_w/G10_0_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Thái Lan – Thầu Chín”, nhìn từ trên cao."}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","Trần Dân Tiên, Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch","Bảo tàng Hồ Chí Minh – Khu tưởng niệm Chủ tịch Hồ Chí Minh tại làng Nachok (bản Mạy), tỉnh Nakhon Phanom, Thái Lan (2019): https://baotanghochiminh.vn/khu-tuong-niem-chu-tich-ho-chi-minh-tai-lang-nachok-ban-may-tinh-nakhon-phanom-thai-lan.htm","Báo Nhân Dân – Hình bóng Bác mãi in đậm ở Thái Lan (19/5/2016): https://nhandan.vn/hinh-bong-bac-mai-in-dam-o-thai-lan-post263450.html","GS.TS Đàm Đức Vượng, Về trường hợp “Thầu Chín” ở Xiêm (2026): https://ivanlevanlan.wordpress.com/2026/03/20/ve-truong-hop-thau-chin-o-xiem/"],"doc":[{"t":"Ông Thầu Chín bên dòng Mê Kông: hơn một năm Nguyễn Ái Quốc sống giữa kiều bào đất Xiêm. Mùa hè năm 1928, các xóm Việt kiều ở Xiêm có thêm một người đàn ông đội nón, đi dép, được bà con gọi thân mật là Thầu Chín. Ông cày ruộng, đào giếng, tối đến lại ngồi dạy chữ bên ngọn đèn dầu. Ít ai trong xóm biết rằng người mà mật thám Pháp đang ráo riết truy tìm khắp châu Á đang sống ngay giữa họ. Gian trưng bày này đưa bạn trở lại hơn một năm lặng lẽ mà quyết định ấy."},{"t":"Người đàn ông đội nón, đi dép. Hãy hình dung một xóm nhỏ của người Việt ở vùng đông bắc Xiêm cuối những năm 1920: những nếp nhà gỗ mái lá, giếng nước giữa sân, ruộng lúa trải ra phía ngoài, giọng nói quê nhà lẫn với tiếng Xiêm. Mùa hè năm 1928, xóm có thêm một người mới. Ông đội nón, đi dép, ăn mặc như mọi người lao động, ra đồng cùng bà con, xắn tay đào giếng, góp sức dựng nhà. Bà con gọi ông là Thầu Chín, một cách gọi thân mật và kính trọng. Người đàn ông ấy chính là Nguyễn Ái Quốc, người sáng lập Hội Việt Nam Cách mạng Thanh niên, cán bộ của Quốc tế Cộng sản, người mà mật thám Pháp đã theo dõi suốt từ Paris tới Quảng Châu. Từ tháng 7/1928 đến tháng 11/1929, ông Thầu Chín đi qua nhiều tỉnh của nước Xiêm, sống lẫn trong các cộng đồng kiều bào và gây dựng ở đó những cơ sở cách mạng nối với quê nhà. Đây là một trong những quãng đời ít được kể nhất, nhưng cũng gần gũi nhất, trong hành trình ba mươi năm tìm đường cứu nước của Người, từ năm 1911 đến năm 1941."},{"t":"Năm 1927: con đường về gần bị cắt đứt. Để hiểu vì sao Người có mặt ở Xiêm, phải lùi lại một năm. Từ cuối năm 1924, Nguyễn Ái Quốc làm việc ở Quảng Châu. Tại đây, Người mở các lớp huấn luyện cho thanh niên yêu nước từ trong nước sang, lập ra Hội Việt Nam Cách mạng Thanh niên vào tháng 6/1925 và ra tờ báo Thanh Niên. Những bài giảng của Người ở đây được in thành cuốn Đường Kách mệnh năm 1927. Quảng Châu khi ấy là trung tâm của cách mạng Trung Quốc, cũng là nơi gần Tổ quốc nhất mà Người có thể đặt chân. Tháng 4/1927, mọi thứ đảo lộn. Ngày 12/4, Tưởng Giới Thạch làm chính biến ở Thượng Hải; chỉ ba ngày sau, cuộc khủng bố lan tới Quảng Châu, nhiều người cộng sản bị bắt, bị giết. Tháng 5/1927, Nguyễn Ái Quốc buộc phải rời Quảng Châu và trở lại Mátxcơva. Các học trò của Người vẫn duy trì Hội Thanh niên, còn Người thì bị đẩy ra xa phương Đông, xa những người mà Người đã dày công đào tạo. Từ đó, điều Người canh cánh nhất là làm sao trở lại gần Tổ quốc càng sớm càng tốt."},{"t":"Vòng qua châu Âu để về châu Á. Ở Mátxcơva, Người tiếp tục làm việc trong bộ máy của Quốc tế Cộng sản, nhưng lòng vẫn hướng về phương Đông. Cuối năm 1927, Người rời Liên Xô sang châu Âu. Tháng 12/1927, Người có mặt ở Brúcxen, thủ đô nước Bỉ, dự một hội nghị của Liên đoàn chống đế quốc, tổ chức tập hợp đại biểu nhân dân nhiều nước thuộc địa. Những tháng sau đó, Người đi qua Pháp, Đức, Thụy Sĩ, Ý, trong điều kiện luôn bị cảnh sát các nước để mắt. Giữa năm 1928, Người lên tàu trở lại châu Á. Con đường thẳng về Việt Nam lúc này không thể đi: Đông Dương là thuộc địa Pháp, còn Hương Cảng, Thượng Hải đều có mật thám theo dõi gắt gao. Người chọn một cánh cửa khác, kín đáo hơn, là vương quốc Xiêm. Tháng 7/1928, Người đặt chân tới Bangkok. Từ thủ đô Xiêm, Người không ở lại thành phố mà tìm ngay tới những nơi có đông đồng bào mình sinh sống: các xóm Việt kiều ở miền bắc và đông bắc đất nước này."},{"t":"Xiêm, khoảng trống trên bản đồ thuộc địa. Cuối những năm 1920, gần như cả Đông Nam Á đã bị các cường quốc phương Tây chia nhau: Miến Điện và Mã Lai thuộc Anh, quần đảo Đông Ấn thuộc Hà Lan, Philippines thuộc Mỹ, còn Việt Nam, Lào, Campuchia nằm trong Liên bang Đông Dương của Pháp. Xiêm là vương quốc duy nhất trong khu vực giữ được độc lập. Để giữ được nền độc lập ấy, triều đình Xiêm đã phải nhượng nhiều vùng đất. Theo hiệp ước năm 1893, vùng tả ngạn sông Mê Kông về tay Pháp, và dòng sông trở thành biên giới giữa Xiêm với xứ Lào thuộc Pháp. Năm 1928, Xiêm vẫn là nước quân chủ chuyên chế dưới triều vua Prajadhipok, tức vua Rama VII. Pháp có cơ quan ngoại giao ở Bangkok và có tai mắt trong các cộng đồng người Việt, nhưng cảnh sát Pháp không thể tự do bắt người trên đất Xiêm như ở Đông Dương. Với một người bị truy nã, đó là lợi thế lớn. Lợi thế thứ hai là vị trí: từ các tỉnh đông bắc Xiêm, chỉ cần vượt sông sang Lào, băng qua dãy Trường Sơn là tới Nghệ An, Hà Tĩnh, Quảng Bình. Lợi thế thứ ba, quan trọng nhất, là con người: ở đó có đông đảo kiều bào Việt Nam."},{"t":"Bạn có biết? “Thầu Chín” thường được giải thích là “ông già Chín”, một cách gọi thân mật dành cho người lớn tuổi. Thật ra, năm 1928 Nguyễn Ái Quốc mới 38 tuổi."},{"t":"Những xóm Việt ở xứ Isan. Người Việt đã có mặt ở Xiêm từ nhiều thế kỷ trước, nhưng các xóm Việt ở vùng đông bắc, tức xứ Isan, phần lớn hình thành từ cuối thế kỷ XIX, đầu thế kỷ XX. Sau khi phong trào Cần Vương bị dập tắt, nhiều nghĩa sĩ cùng gia đình họ tìm đường qua Lào, vượt sông Mê Kông sang Xiêm lánh nạn. Tiếp đó là những người của phong trào Đông Du và Duy Tân. Khoảng năm 1910, chính cụ Phan Bội Châu cũng sang Xiêm, cùng các đồng chí khai phá đất làm “trại cày” để nuôi dưỡng thanh niên yêu nước chờ thời. Họ dựng xóm ở Phichit, Udon Thani, Sakon Nakhon, Nakhon Phanom, Nong Khai, sống bằng nghề làm ruộng, trồng rau, làm thợ. Họ giữ tiếng nói, giữ nếp nhà, giữ ngày giỗ, ngày Tết của quê hương. Phần đông nghèo và ít học, nhưng những mất mát của thế hệ cha anh khiến lòng hướng về Tổ quốc của họ chưa bao giờ nguội. Trước khi Người đến, Hội Việt Nam Cách mạng Thanh niên đã cử cán bộ sang gây dựng cơ sở trong các xóm này. Khi ông Thầu Chín tới, mảnh đất đã được vỡ, chỉ còn chờ người biết gieo hạt."},{"t":"Từ Bangkok đến Bản Đông. Từ Bangkok, Người đi lên phía bắc, tìm đến Bản Đông, một xóm Việt kiều thuộc tỉnh Phichit, vùng đồng bằng ven sông Nan. Đó là chặng dừng chân đầu tiên, và cũng từ chặng này cái tên Thầu Chín bắt đầu gắn với Người. Theo báo Nhân Dân, Người ở Bản Đông khoảng mười lăm ngày, đủ để gặp gỡ những người cốt cán, tìm hiểu đời sống và tâm tư của kiều bào. Rồi từ Phichit, Người đi tiếp lên cao nguyên Khorat ở đông bắc, nơi có những cộng đồng người Việt đông hơn cả. Chặng đường ấy phần lớn đi bộ, băng qua rừng núi, có khi phải ngủ lại giữa rừng (xem chuyên đề “Những chặng đường đi bộ”). Ở Udon Thani, Người sống và hoạt động trong các xóm Việt kiều ở vùng Nong Bua và bản Nong On. Từ Udon, Người còn tới Sakon Nakhon, Nong Khai, rồi xuôi về Nakhon Phanom bên bờ Mê Kông, nơi Người dừng chân lâu nhất. Ở mỗi nơi, Người sống lẫn giữa bà con, không có chỗ ở tách biệt, không nhận sự phục dịch riêng, tự làm lấy mọi việc như một người lao động. Trong những lời kể của kiều bào về sau, cái tên Thầu Chín vì thế luôn gắn với những việc rất cụ thể của đời thường."},{"t":"Một ngày của ông Thầu Chín. Ở đâu, ông Thầu Chín cũng sống như người trong xóm. Sáng ra đồng hoặc làm vườn, trồng rau, trồng chuối; khi xóm cần giếng thì cùng bà con đào giếng; khi có nhà cần dựng thì góp tay dựng nhà. Ăn uống đạm bạc, chỗ nằm là giường tre hay tấm phản gỗ. Chính lối sống ấy khiến bà con tin cậy, và cũng là lớp áo che mắt mật thám tốt nhất (xem chuyên đề “Ngôi nhà của Thầu Chín”). Buổi tối là thời gian của những công việc khác. Người mở lớp dạy chữ quốc ngữ cho trẻ em và người lớn, dịch sách, viết bài cho tờ báo của kiều bào (xem chuyên đề “Lớp học đèn dầu và tờ báo Thân Ái”). Người đề nghị xây dựng những hội quần chúng hợp với nếp sống của bà con: Hội Thân ái để tập hợp kiều bào, Hội Hợp tác để giúp nhau làm ruộng, làm thợ. Trong các hội ấy, những người hăng hái nhất được chọn lọc, bồi dưỡng dần để trở thành cốt cán của Hội Việt Nam Cách mạng Thanh niên. Người cũng khuyên kiều bào sống hòa thuận với người Xiêm, tôn trọng phong tục và luật lệ của nơi mình đang sống."},{"t":"Bản Mạy, chặng dừng lâu nhất. Theo Bảo tàng Hồ Chí Minh, Người hoạt động ở Nakhon Phanom từ khoảng cuối tháng 7 đến cuối tháng 10/1929. Làng Nachok, mà kiều bào quen gọi là bản Mạy, tức “làng mới”, là nơi Người ở lâu nhất trên đất Xiêm. Người đã gây dựng phong trào kiều bào ở đây, biến bản Mạy thành một trong những địa điểm quan trọng của Hội Việt Nam Cách mạng Thanh niên. Bảo tàng Hồ Chí Minh cho biết nơi này còn lưu giữ những dấu tích của Người, trong đó có những gốc cây do chính tay Người trồng. Vị trí của bản Mạy giải thích vì sao nơi này quan trọng. Nakhon Phanom nằm ngay bờ Mê Kông; bên kia sông là Thà Khẹt của xứ Lào thuộc Pháp. Theo con đường qua sông, qua Lào, vượt Trường Sơn, người và tài liệu có thể đi về các tỉnh miền Trung (xem chuyên đề “Sông Mê Kông”). Những tin tức từ quê nhà cũng theo đường ấy mà sang. Và chính trong những tháng ở bản Mạy, những tin tức ấy đã khiến ông Thầu Chín quyết định lên đường."},{"t":"Bạn có biết? Ở Xiêm, ngoài tên Thầu Chín, Người còn được một số kiều bào biết đến với tên gọi ông Thọ."},{"t":"Rời đất Xiêm. Năm 1929, tin từ trong nước cho biết phong trào cộng sản ở quê nhà đã hình thành ba tổ chức riêng rẽ, mỗi nơi một ngả, có lúc còn công kích lẫn nhau. Ngày 27/10/1929, Quốc tế Cộng sản gửi thư yêu cầu những người cộng sản Đông Dương lập một đảng duy nhất. Tháng 11/1929, ông Thầu Chín từ biệt bà con, rời Xiêm. Theo báo cáo Người gửi Quốc tế Cộng sản ngày 18/2/1930, Người đến Hương Cảng ngày 23/12/1929. Từ ngày 6/1 đến 7/2/1930, Người chủ trì hội nghị hợp nhất tại Cửu Long, thành lập Đảng Cộng sản Việt Nam (xem chuyên đề “Tin từ quê nhà và chuyến đi cuối năm 1929”). Hơn một năm ở Xiêm vì thế không phải là một chặng nghỉ chân. Đó là những tháng Người trực tiếp làm công tác quần chúng ở cơ sở: sống cùng, làm cùng, học cùng những người lao động nghèo, gây dựng tổ chức từ những việc nhỏ nhất như đào một cái giếng, lập một hội tương trợ. Kinh nghiệm ấy theo Người về tới Pác Bó năm 1941, và còn vang lên trong những lời Người căn dặn cán bộ nhiều năm sau về cách gần gũi, lắng nghe và học hỏi nhân dân."},{"t":"Dấu tích hôm nay. Gần một thế kỷ đã qua, những nơi ông Thầu Chín từng đặt chân vẫn được kiều bào và bạn bè Thái Lan gìn giữ. Ở bản Nong On, tỉnh Udon Thani, khu di tích có ngôi nhà phục dựng theo dáng nơi Người ở năm xưa, được hoàn thành năm 2002. Ở Bản Đông, tỉnh Phichit, một ngôi nhà sàn gỗ được dựng lại cùng tượng bán thân của Người. Ở bản Mạy, Nakhon Phanom, khu tưởng niệm rộng khoảng 1,2 héc-ta được khánh thành ngày 19/5/2016, đúng dịp kỷ niệm 126 năm ngày sinh của Người (xem chuyên đề “Nhà lưu niệm Hồ Chí Minh ở bản Mạy, Nakhon Phanom”). Gian trưng bày này dựng lại một xóm Việt kiều bên sông Mê Kông những năm 1928 – 1929. Khách tham quan có thể bước vào ngôi nhà gỗ mái lá, nhìn chiếc phản, bàn viết, ngọn đèn dầu và tập giấy ghi chép; ra sân xem chiếc giếng, thùng gỗ, chum nước, chiếc mai đào đất; rồi phóng tầm mắt về phía dãy núi đá vôi bên bờ Lào. Tất cả đều là đồ vật minh họa, nhưng mỗi thứ gắn với một việc có thật về cách sống giản dị mà Nguyễn Ái Quốc đã chọn, giữa những con người mà Người gọi là đồng bào."}],"so_chu":2221},{"i":1,"tieu_de_bang":"Lớp học đèn dầu và tờ báo Thân Ái","tieu_de":"Lớp học dưới ngọn đèn dầu: ông Thầu Chín dạy chữ, dịch sách, làm báo cho kiều bào","sapo":"Ban ngày, ông Thầu Chín ra đồng như mọi người trong xóm. Khi trời tối, một ngọn đèn dầu lại được thắp lên, trẻ con và người lớn ngồi quanh tập đánh vần từng chữ quốc ngữ. Cũng dưới ngọn đèn ấy, những trang báo Thân Ái được viết ra để đi tới các xóm xa. Vì sao một nhà cách mạng lại bắt đầu từ những con chữ?","bia":{"src":"textures/bai/G10_v2.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Khi xóm nhỏ lên đèn","text":"Các xóm Việt kiều ở đông bắc Xiêm cuối những năm 1920 chưa có điện. Khi mặt trời lặn sau những rặng dừa, mọi sinh hoạt thu về quanh ngọn đèn dầu. Ở những xóm có ông Thầu Chín, giờ ấy lại là giờ lên lớp. Học trò có trẻ nhỏ, có cả những người lớn vừa đi làm đồng về. Có thể hình dung một gian nhà gỗ, mấy chiếc bàn mộc, ngọn đèn đặt ở giữa để ai cũng nhìn rõ mặt chữ.\n\nGóc trưng bày này dựng lại không khí ấy bằng những đồ vật minh họa: chiếc bàn học, ngọn đèn dầu, tập giấy ghi chép đặt bên bàn viết. Không hiện vật nào ở đây là đồ dùng thật của Người, nhưng mỗi thứ đều gắn với một việc có thật mà các tài liệu về thời kỳ này ghi nhận. Người mở lớp dạy chữ quốc ngữ cho trẻ em và người lớn, dịch sách ra tiếng Việt, viết bài cho tờ báo của kiều bào. Ba công việc ấy thực chất là một: giúp những người Việt xa xứ hiểu quê hương mình đang ra sao, và mình có thể làm gì cho quê hương.","doc":1},{"loai":"doan","tieu_de":"Những đứa trẻ lớn lên nơi đất khách","text":"Phần đông kiều bào ở đông bắc Xiêm khi ấy là nông dân, thợ thủ công nghèo. Thế hệ cha ông vượt sông sang đây phần nhiều là những người lánh nạn sau phong trào Cần Vương, hoặc những người phải trốn tránh sự truy bắt của thực dân. Nhiều người không biết đọc, biết viết. Con cháu họ sinh ra trên đất Xiêm, lớn lên giữa láng giềng người Xiêm, nói tiếng Xiêm ngoài ngõ. Nếu không ai dạy, chỉ một hai thế hệ nữa, tiếng Việt có thể chỉ còn là thứ tiếng dùng trong bữa cơm gia đình, còn chữ Việt thì hầu như không ai biết.\n\nVới ông Thầu Chín, đó không chỉ là chuyện văn hóa. Muốn vận động bà con thì bà con phải đọc được những điều mình muốn nói. Muốn bà con hiểu tình hình quê nhà thì phải có báo, có sách bằng tiếng Việt, và phải có người đọc được. Vì thế, cùng với việc gây dựng các hội quần chúng trong kiều bào, Người đặt việc dạy chữ lên hàng đầu. Lớp học mở cho cả trẻ nhỏ lẫn người lớn, học vào buổi tối sau một ngày lao động, để không ai phải bỏ việc đồng áng mà đi học.","doc":2},{"loai":"anh","src":"textures/bang_w/G10_1_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lớp học đèn dầu và tờ báo Thân Ái”, nhìn từ xa."},{"loai":"doan","tieu_de":"Chữ quốc ngữ, thứ chữ để mọi người cùng biết","text":"Đầu thế kỷ XX, chữ quốc ngữ vẫn là thứ chữ mới với phần đông người Việt. Thứ chữ viết bằng mẫu tự La-tinh này hình thành từ thế kỷ XVII; cuốn từ điển Việt – Bồ – La của giáo sĩ Alexandre de Rhodes in ở Rôma năm 1651 là một dấu mốc. Nhưng phải đến đầu thế kỷ XX, các nhà nho yêu nước mới coi nó là công cụ để khai trí cho dân. Năm 1907, trường Đông Kinh Nghĩa Thục ở Hà Nội cổ động học chữ quốc ngữ và bị thực dân đóng cửa ngay trong năm. Năm 1919, khoa thi Hội cuối cùng của Nho học khép lại, chữ Hán mất dần vị trí.\n\nChữ quốc ngữ dễ học hơn chữ Hán rất nhiều: chỉ vài chục chữ cái và năm dấu thanh, người chăm chỉ có thể đọc được sau vài tháng. Đó là lý do nó trở thành thứ chữ của những ai muốn đưa hiểu biết tới đông đảo quần chúng. Ở Quảng Châu, Nguyễn Ái Quốc đã ra báo Thanh Niên và in cuốn Đường Kách mệnh bằng chữ quốc ngữ, với những câu ngắn, dễ hiểu. Ở Xiêm, Người đi thêm một bước: không chỉ viết cho người đã biết chữ, mà dạy người chưa biết chữ đọc được những điều mình viết.","doc":3},{"loai":"ban_co_biet","text":"Mười năm sau những lớp học buổi tối ở các xóm Việt kiều đất Xiêm, năm 1938, Hội Truyền bá quốc ngữ được thành lập ở Hà Nội, đưa phong trào học chữ quốc ngữ lan rộng trong nước.","nguon_ten":"Lịch sử Việt Nam, NXB Khoa học xã hội","doc":4},{"loai":"doan","tieu_de":"Từ Đồng Thanh đến Thân Ái","text":"Kiều bào sống rải rác ở nhiều tỉnh, cách nhau hàng trăm cây số, đường đi lại khó khăn. Để nối các xóm với nhau, hội kiều bào đã có sẵn một tờ báo nhỏ tên là Đồng Thanh. Khi đến với bà con, ông Thầu Chín chủ trương đổi tên báo thành Thân Ái, cùng với việc xây dựng Hội Thân ái để tập hợp kiều bào. Tên mới không phải chuyện chữ nghĩa đơn thuần. “Đồng thanh” là cùng chung một tiếng nói; “thân ái” là thương yêu, gắn bó với nhau. Với những người xa quê sống giữa đất người, điều cần trước hết là tình đoàn kết, đùm bọc nhau lúc ốm đau hoạn nạn.\n\nTờ báo đưa tin về tình hình trong nước và thế giới, cổ vũ tinh thần đoàn kết, tương trợ, nhắc nhở bà con hướng về Tổ quốc. Qua những trang báo ấy, người ở Udon Thani biết chuyện của người ở Sakon Nakhon, người ở Phichit biết chuyện của người ở Nakhon Phanom. Một cộng đồng rời rạc dần dần có chung một tiếng nói, đúng như tên gọi của tờ báo cũ, và có chung một tình thân, đúng như tên gọi của tờ báo mới.","doc":5},{"loai":"anh","src":"textures/bai/G10_v2.jpg","chu_thich":"Một góc không gian 3D tái hiện xóm Việt kiều ở bản Mạy (Na Chok), Nakhon Phanom, những năm 1928 – 1929.","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Người làm báo từ Paris đến Quảng Châu","text":"Tờ Thân Ái nhỏ bé ở đất Xiêm là một mắt xích trong con đường làm báo đã kéo dài gần một thập kỷ của Nguyễn Ái Quốc. Ở Paris, năm 1922, Người cùng những người bạn từ các thuộc địa ra tờ Le Paria, tức Người Cùng Khổ. Người vừa lo nội dung, vừa viết bài, vẽ tranh, có khi tự tay đi bán báo. Ở Quảng Châu, ngày 21/6/1925, Người sáng lập báo Thanh Niên, cơ quan của Hội Việt Nam Cách mạng Thanh niên, được bí mật chuyển về trong nước.\n\nMỗi tờ báo là một cách trò chuyện với một kiểu người đọc. Le Paria viết bằng tiếng Pháp cho người dân các thuộc địa đang sống ở Pháp. Thanh Niên viết cho thanh niên, trí thức, công nhân trong nước. Thân Ái viết cho những người nông dân, người thợ Việt kiều, nhiều người mới qua lớp vỡ lòng. Vì thế lời văn phải giản dị, câu ngắn, chữ quen, để người mới biết chữ cũng đọc được và đọc cho người khác nghe được. Nhiều năm sau, khi nói chuyện với những người làm báo, Người vẫn nhắc: trước khi cầm bút phải tự hỏi viết cho ai, viết để làm gì và viết thế nào cho người đọc hiểu.","doc":6},{"loai":"ban_co_biet","text":"Ngày 21/6/1925, số đầu tiên của báo Thanh Niên do Nguyễn Ái Quốc sáng lập ra đời ở Quảng Châu; về sau ngày này được chọn làm Ngày Báo chí cách mạng Việt Nam.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia; Hội Nhà báo Việt Nam","doc":7},{"loai":"doan","tieu_de":"Dịch sách giữa đất khách","text":"Cùng với lớp học và tờ báo, ông Thầu Chín còn làm một việc thầm lặng hơn: dịch sách ra tiếng Việt. Những thanh niên hăng hái trong kiều bào, những người được chọn để bồi dưỡng thành cốt cán, cần có tài liệu học tập. Trong khi đó, sách lý luận, sách về phong trào cách mạng thế giới bằng tiếng Việt hầu như chưa có. Người biết nhiều thứ tiếng: chữ Hán học từ thuở nhỏ ở quê, tiếng Pháp từ trường học và những năm sống ở Pháp, tiếng Anh từ những năm ở Anh, tiếng Nga từ những năm ở Liên Xô.\n\nVốn liếng ấy giúp Người chuyển những cuốn sách viết cho người đọc châu Âu thành tài liệu mà người Việt kiều có thể hiểu. Công việc được làm vào ban đêm, sau một ngày lao động, trong điều kiện hoạt động bí mật. Sách và tài liệu phải cất giữ kín đáo, bởi mật thám Pháp có tai mắt cả trên đất Xiêm. Những bản dịch ấy trở thành nền cho các buổi sinh hoạt, huấn luyện trong các xóm Việt kiều, nơi những người được chọn lọc dần được chuẩn bị để trở thành hội viên Hội Việt Nam Cách mạng Thanh niên.","doc":8},{"loai":"anh","src":"textures/bang_w/G10_1_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lớp học đèn dầu và tờ báo Thân Ái”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Người thầy cũng là học trò","text":"Muốn sống lâu dài giữa đất người, chính ông Thầu Chín cũng phải đi học. Theo cuốn “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch” của Trần Dân Tiên, ở Xiêm, Người chăm chỉ học tiếng Xiêm để có thể trò chuyện với người dân sở tại. Đó là thói quen Người giữ ở mọi nơi mình đặt chân tới: ở Luân Đôn học tiếng Anh, ở Paris trau dồi tiếng Pháp để viết báo, ở Mátxcơva học tiếng Nga, ở Quảng Châu nói tiếng Trung Quốc với bạn bè.\n\nViệc học tiếng Xiêm còn là một lời nhắn nhủ không cần nói ra với kiều bào. Người khuyên bà con sống hòa thuận với láng giềng người Xiêm, tôn trọng phong tục và pháp luật của nước sở tại. Một cộng đồng biết giữ gốc mà vẫn hòa hợp với nơi mình sống thì mới yên ổn làm ăn lâu dài, và những cơ sở cách mạng trong cộng đồng ấy mới có thể bền vững. Người thầy của lớp học đèn dầu vì thế dạy bằng chính tấm gương của mình: ban ngày học tiếng của bạn láng giềng, buổi tối dạy chữ của dân tộc mình.","doc":9},{"loai":"trich","text":"Những người đã biết chữ hãy dạy cho những người chưa biết chữ… Những người chưa biết chữ hãy gắng sức mà học cho biết đi. Vợ chưa biết thì chồng bảo, em chưa biết thì anh bảo, cha mẹ không biết thì con bảo.","nguoi":"Chủ tịch Hồ Chí Minh, lời kêu gọi “Chống nạn thất học”, tháng 10/1945","nguon_ten":"Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia","doc":10},{"loai":"doan","tieu_de":"Từ ngọn đèn đất Xiêm đến Bình dân học vụ","text":"Mười bảy năm sau những lớp học ở xóm Việt kiều, người thầy của lớp đèn dầu năm nào trở thành Chủ tịch nước Việt Nam Dân chủ Cộng hòa. Chỉ sáu ngày sau khi đọc Tuyên ngôn Độc lập, ngày 8/9/1945, Người ký sắc lệnh lập Nha Bình dân học vụ. Trong lời kêu gọi “Chống nạn thất học” đầu tháng 10/1945, Người chỉ rõ dưới chế độ thực dân, số người Việt Nam thất học chiếm tới 95 phần trăm. Người kêu gọi mọi người Việt Nam phải biết đọc, biết viết chữ quốc ngữ.\n\nNhững lớp học buổi tối lại mọc lên, lần này trên khắp cả nước: trong đình làng, trong nhà dân, ở công xưởng, nhiều lớp học vẫn soi bằng ngọn đèn dầu. Theo các tài liệu về lịch sử giáo dục, chỉ sau khoảng một năm đã có khoảng 2,5 triệu người biết đọc, biết viết. Tinh thần người biết dạy người chưa biết của phong trào ấy chính là tinh thần của những lớp học mà ông Thầu Chín từng mở giữa đất Xiêm, nay được nhân lên thành phong trào của cả một dân tộc.","doc":11},{"loai":"anh","src":"textures/bang_w/G10_1_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lớp học đèn dầu và tờ báo Thân Ái”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Hạt giống còn lại","text":"Ông Thầu Chín chỉ ở Xiêm hơn một năm, nhưng những gì Người gieo lại bền lâu hơn thế nhiều. Nhiều thanh niên Việt kiều từng dự các lớp học, các buổi sinh hoạt ở xóm về sau trở về nước tham gia cách mạng. Trong những năm kháng chiến về sau, cộng đồng người Việt ở Thái Lan vẫn một lòng hướng về Tổ quốc, góp người, góp của cho cuộc đấu tranh giành độc lập, thống nhất đất nước.\n\nỞ đông bắc Thái Lan hôm nay, dù nhiều thế hệ con cháu đã mang quốc tịch Thái, không ít gia đình Việt kiều vẫn giữ tiếng Việt, giữ phong tục, giữ ngày Tết cổ truyền. Khi kể cho con cháu nghe về lai lịch cộng đồng mình, nhiều người vẫn nhắc tới “ông già Chín”, người đã cùng cha ông họ làm ruộng ban ngày và dạy chữ ban đêm. Ngọn đèn dầu trong gian trưng bày này vì thế không chỉ soi một lớp học. Nó soi một mạch nguồn bền bỉ: tình yêu tiếng mẹ đẻ và lòng hướng về cội nguồn của những người con xa xứ.","doc":12}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","Trần Dân Tiên, Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch","Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia (Chống nạn thất học, 10/1945)","GS.TS Đàm Đức Vượng, Về trường hợp “Thầu Chín” ở Xiêm (2026): https://ivanlevanlan.wordpress.com/2026/03/20/ve-truong-hop-thau-chin-o-xiem/","Bảo tàng Hồ Chí Minh"],"doc":[{"t":"Lớp học dưới ngọn đèn dầu: ông Thầu Chín dạy chữ, dịch sách, làm báo cho kiều bào. Ban ngày, ông Thầu Chín ra đồng như mọi người trong xóm. Khi trời tối, một ngọn đèn dầu lại được thắp lên, trẻ con và người lớn ngồi quanh tập đánh vần từng chữ quốc ngữ. Cũng dưới ngọn đèn ấy, những trang báo Thân Ái được viết ra để đi tới các xóm xa. Vì sao một nhà cách mạng lại bắt đầu từ những con chữ?"},{"t":"Khi xóm nhỏ lên đèn. Các xóm Việt kiều ở đông bắc Xiêm cuối những năm 1920 chưa có điện. Khi mặt trời lặn sau những rặng dừa, mọi sinh hoạt thu về quanh ngọn đèn dầu. Ở những xóm có ông Thầu Chín, giờ ấy lại là giờ lên lớp. Học trò có trẻ nhỏ, có cả những người lớn vừa đi làm đồng về. Có thể hình dung một gian nhà gỗ, mấy chiếc bàn mộc, ngọn đèn đặt ở giữa để ai cũng nhìn rõ mặt chữ. Góc trưng bày này dựng lại không khí ấy bằng những đồ vật minh họa: chiếc bàn học, ngọn đèn dầu, tập giấy ghi chép đặt bên bàn viết. Không hiện vật nào ở đây là đồ dùng thật của Người, nhưng mỗi thứ đều gắn với một việc có thật mà các tài liệu về thời kỳ này ghi nhận. Người mở lớp dạy chữ quốc ngữ cho trẻ em và người lớn, dịch sách ra tiếng Việt, viết bài cho tờ báo của kiều bào. Ba công việc ấy thực chất là một: giúp những người Việt xa xứ hiểu quê hương mình đang ra sao, và mình có thể làm gì cho quê hương."},{"t":"Những đứa trẻ lớn lên nơi đất khách. Phần đông kiều bào ở đông bắc Xiêm khi ấy là nông dân, thợ thủ công nghèo. Thế hệ cha ông vượt sông sang đây phần nhiều là những người lánh nạn sau phong trào Cần Vương, hoặc những người phải trốn tránh sự truy bắt của thực dân. Nhiều người không biết đọc, biết viết. Con cháu họ sinh ra trên đất Xiêm, lớn lên giữa láng giềng người Xiêm, nói tiếng Xiêm ngoài ngõ. Nếu không ai dạy, chỉ một hai thế hệ nữa, tiếng Việt có thể chỉ còn là thứ tiếng dùng trong bữa cơm gia đình, còn chữ Việt thì hầu như không ai biết. Với ông Thầu Chín, đó không chỉ là chuyện văn hóa. Muốn vận động bà con thì bà con phải đọc được những điều mình muốn nói. Muốn bà con hiểu tình hình quê nhà thì phải có báo, có sách bằng tiếng Việt, và phải có người đọc được. Vì thế, cùng với việc gây dựng các hội quần chúng trong kiều bào, Người đặt việc dạy chữ lên hàng đầu. Lớp học mở cho cả trẻ nhỏ lẫn người lớn, học vào buổi tối sau một ngày lao động, để không ai phải bỏ việc đồng áng mà đi học."},{"t":"Chữ quốc ngữ, thứ chữ để mọi người cùng biết. Đầu thế kỷ XX, chữ quốc ngữ vẫn là thứ chữ mới với phần đông người Việt. Thứ chữ viết bằng mẫu tự La-tinh này hình thành từ thế kỷ XVII; cuốn từ điển Việt – Bồ – La của giáo sĩ Alexandre de Rhodes in ở Rôma năm 1651 là một dấu mốc. Nhưng phải đến đầu thế kỷ XX, các nhà nho yêu nước mới coi nó là công cụ để khai trí cho dân. Năm 1907, trường Đông Kinh Nghĩa Thục ở Hà Nội cổ động học chữ quốc ngữ và bị thực dân đóng cửa ngay trong năm. Năm 1919, khoa thi Hội cuối cùng của Nho học khép lại, chữ Hán mất dần vị trí. Chữ quốc ngữ dễ học hơn chữ Hán rất nhiều: chỉ vài chục chữ cái và năm dấu thanh, người chăm chỉ có thể đọc được sau vài tháng. Đó là lý do nó trở thành thứ chữ của những ai muốn đưa hiểu biết tới đông đảo quần chúng. Ở Quảng Châu, Nguyễn Ái Quốc đã ra báo Thanh Niên và in cuốn Đường Kách mệnh bằng chữ quốc ngữ, với những câu ngắn, dễ hiểu. Ở Xiêm, Người đi thêm một bước: không chỉ viết cho người đã biết chữ, mà dạy người chưa biết chữ đọc được những điều mình viết."},{"t":"Bạn có biết? Mười năm sau những lớp học buổi tối ở các xóm Việt kiều đất Xiêm, năm 1938, Hội Truyền bá quốc ngữ được thành lập ở Hà Nội, đưa phong trào học chữ quốc ngữ lan rộng trong nước."},{"t":"Từ Đồng Thanh đến Thân Ái. Kiều bào sống rải rác ở nhiều tỉnh, cách nhau hàng trăm cây số, đường đi lại khó khăn. Để nối các xóm với nhau, hội kiều bào đã có sẵn một tờ báo nhỏ tên là Đồng Thanh. Khi đến với bà con, ông Thầu Chín chủ trương đổi tên báo thành Thân Ái, cùng với việc xây dựng Hội Thân ái để tập hợp kiều bào. Tên mới không phải chuyện chữ nghĩa đơn thuần. “Đồng thanh” là cùng chung một tiếng nói; “thân ái” là thương yêu, gắn bó với nhau. Với những người xa quê sống giữa đất người, điều cần trước hết là tình đoàn kết, đùm bọc nhau lúc ốm đau hoạn nạn. Tờ báo đưa tin về tình hình trong nước và thế giới, cổ vũ tinh thần đoàn kết, tương trợ, nhắc nhở bà con hướng về Tổ quốc. Qua những trang báo ấy, người ở Udon Thani biết chuyện của người ở Sakon Nakhon, người ở Phichit biết chuyện của người ở Nakhon Phanom. Một cộng đồng rời rạc dần dần có chung một tiếng nói, đúng như tên gọi của tờ báo cũ, và có chung một tình thân, đúng như tên gọi của tờ báo mới."},{"t":"Người làm báo từ Paris đến Quảng Châu. Tờ Thân Ái nhỏ bé ở đất Xiêm là một mắt xích trong con đường làm báo đã kéo dài gần một thập kỷ của Nguyễn Ái Quốc. Ở Paris, năm 1922, Người cùng những người bạn từ các thuộc địa ra tờ Le Paria, tức Người Cùng Khổ. Người vừa lo nội dung, vừa viết bài, vẽ tranh, có khi tự tay đi bán báo. Ở Quảng Châu, ngày 21/6/1925, Người sáng lập báo Thanh Niên, cơ quan của Hội Việt Nam Cách mạng Thanh niên, được bí mật chuyển về trong nước. Mỗi tờ báo là một cách trò chuyện với một kiểu người đọc. Le Paria viết bằng tiếng Pháp cho người dân các thuộc địa đang sống ở Pháp. Thanh Niên viết cho thanh niên, trí thức, công nhân trong nước. Thân Ái viết cho những người nông dân, người thợ Việt kiều, nhiều người mới qua lớp vỡ lòng. Vì thế lời văn phải giản dị, câu ngắn, chữ quen, để người mới biết chữ cũng đọc được và đọc cho người khác nghe được. Nhiều năm sau, khi nói chuyện với những người làm báo, Người vẫn nhắc: trước khi cầm bút phải tự hỏi viết cho ai, viết để làm gì và viết thế nào cho người đọc hiểu."},{"t":"Bạn có biết? Ngày 21/6/1925, số đầu tiên của báo Thanh Niên do Nguyễn Ái Quốc sáng lập ra đời ở Quảng Châu; về sau ngày này được chọn làm Ngày Báo chí cách mạng Việt Nam."},{"t":"Dịch sách giữa đất khách. Cùng với lớp học và tờ báo, ông Thầu Chín còn làm một việc thầm lặng hơn: dịch sách ra tiếng Việt. Những thanh niên hăng hái trong kiều bào, những người được chọn để bồi dưỡng thành cốt cán, cần có tài liệu học tập. Trong khi đó, sách lý luận, sách về phong trào cách mạng thế giới bằng tiếng Việt hầu như chưa có. Người biết nhiều thứ tiếng: chữ Hán học từ thuở nhỏ ở quê, tiếng Pháp từ trường học và những năm sống ở Pháp, tiếng Anh từ những năm ở Anh, tiếng Nga từ những năm ở Liên Xô. Vốn liếng ấy giúp Người chuyển những cuốn sách viết cho người đọc châu Âu thành tài liệu mà người Việt kiều có thể hiểu. Công việc được làm vào ban đêm, sau một ngày lao động, trong điều kiện hoạt động bí mật. Sách và tài liệu phải cất giữ kín đáo, bởi mật thám Pháp có tai mắt cả trên đất Xiêm. Những bản dịch ấy trở thành nền cho các buổi sinh hoạt, huấn luyện trong các xóm Việt kiều, nơi những người được chọn lọc dần được chuẩn bị để trở thành hội viên Hội Việt Nam Cách mạng Thanh niên."},{"t":"Người thầy cũng là học trò. Muốn sống lâu dài giữa đất người, chính ông Thầu Chín cũng phải đi học. Theo cuốn “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch” của Trần Dân Tiên, ở Xiêm, Người chăm chỉ học tiếng Xiêm để có thể trò chuyện với người dân sở tại. Đó là thói quen Người giữ ở mọi nơi mình đặt chân tới: ở Luân Đôn học tiếng Anh, ở Paris trau dồi tiếng Pháp để viết báo, ở Mátxcơva học tiếng Nga, ở Quảng Châu nói tiếng Trung Quốc với bạn bè. Việc học tiếng Xiêm còn là một lời nhắn nhủ không cần nói ra với kiều bào. Người khuyên bà con sống hòa thuận với láng giềng người Xiêm, tôn trọng phong tục và pháp luật của nước sở tại. Một cộng đồng biết giữ gốc mà vẫn hòa hợp với nơi mình sống thì mới yên ổn làm ăn lâu dài, và những cơ sở cách mạng trong cộng đồng ấy mới có thể bền vững. Người thầy của lớp học đèn dầu vì thế dạy bằng chính tấm gương của mình: ban ngày học tiếng của bạn láng giềng, buổi tối dạy chữ của dân tộc mình."},{"t":"Những người đã biết chữ hãy dạy cho những người chưa biết chữ… Những người chưa biết chữ hãy gắng sức mà học cho biết đi. Vợ chưa biết thì chồng bảo, em chưa biết thì anh bảo, cha mẹ không biết thì con bảo. — Chủ tịch Hồ Chí Minh, lời kêu gọi “Chống nạn thất học”, tháng 10/1945"},{"t":"Từ ngọn đèn đất Xiêm đến Bình dân học vụ. Mười bảy năm sau những lớp học ở xóm Việt kiều, người thầy của lớp đèn dầu năm nào trở thành Chủ tịch nước Việt Nam Dân chủ Cộng hòa. Chỉ sáu ngày sau khi đọc Tuyên ngôn Độc lập, ngày 8/9/1945, Người ký sắc lệnh lập Nha Bình dân học vụ. Trong lời kêu gọi “Chống nạn thất học” đầu tháng 10/1945, Người chỉ rõ dưới chế độ thực dân, số người Việt Nam thất học chiếm tới 95 phần trăm. Người kêu gọi mọi người Việt Nam phải biết đọc, biết viết chữ quốc ngữ. Những lớp học buổi tối lại mọc lên, lần này trên khắp cả nước: trong đình làng, trong nhà dân, ở công xưởng, nhiều lớp học vẫn soi bằng ngọn đèn dầu. Theo các tài liệu về lịch sử giáo dục, chỉ sau khoảng một năm đã có khoảng 2,5 triệu người biết đọc, biết viết. Tinh thần người biết dạy người chưa biết của phong trào ấy chính là tinh thần của những lớp học mà ông Thầu Chín từng mở giữa đất Xiêm, nay được nhân lên thành phong trào của cả một dân tộc."},{"t":"Hạt giống còn lại. Ông Thầu Chín chỉ ở Xiêm hơn một năm, nhưng những gì Người gieo lại bền lâu hơn thế nhiều. Nhiều thanh niên Việt kiều từng dự các lớp học, các buổi sinh hoạt ở xóm về sau trở về nước tham gia cách mạng. Trong những năm kháng chiến về sau, cộng đồng người Việt ở Thái Lan vẫn một lòng hướng về Tổ quốc, góp người, góp của cho cuộc đấu tranh giành độc lập, thống nhất đất nước. Ở đông bắc Thái Lan hôm nay, dù nhiều thế hệ con cháu đã mang quốc tịch Thái, không ít gia đình Việt kiều vẫn giữ tiếng Việt, giữ phong tục, giữ ngày Tết cổ truyền. Khi kể cho con cháu nghe về lai lịch cộng đồng mình, nhiều người vẫn nhắc tới “ông già Chín”, người đã cùng cha ông họ làm ruộng ban ngày và dạy chữ ban đêm. Ngọn đèn dầu trong gian trưng bày này vì thế không chỉ soi một lớp học. Nó soi một mạch nguồn bền bỉ: tình yêu tiếng mẹ đẻ và lòng hướng về cội nguồn của những người con xa xứ."}],"so_chu":2047},{"i":2,"tieu_de_bang":"Tin từ quê nhà và chuyến đi cuối năm 1929","tieu_de":"Ba tổ chức, một đảng: vì sao ông Thầu Chín rời đất Xiêm cuối năm 1929","sapo":"Năm 1929, những tin tức vượt sông Mê Kông tới xóm Việt kiều ở Nakhon Phanom khiến ông Thầu Chín không thể ngồi yên. Ở quê nhà, những người cộng sản đầu tiên đã chia thành ba tổ chức, mỗi nơi một ngả. Cùng năm ấy, một tòa án của chính quyền thuộc địa kết án tử hình Người. Cuối năm, Người lặng lẽ rời Xiêm để làm một việc mà chỉ Người mới đủ uy tín để làm.","bia":{"src":"textures/bai/G10_v5.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Mùa thu ở bản Mạy","text":"Mùa thu năm 1929, ông Thầu Chín đang ở bản Mạy, tức làng Nachok, ngoại ô Nakhon Phanom. Theo Bảo tàng Hồ Chí Minh, Người hoạt động ở đây từ khoảng cuối tháng 7 đến cuối tháng 10 năm ấy, và đây là nơi Người ở lâu nhất trên đất Xiêm. Từ bờ sông nhìn sang là đất Lào; xa hơn nữa, sau dãy Trường Sơn, là Nghệ An, Hà Tĩnh, quê hương mà Người đã xa gần hai mươi năm.\n\nCon đường qua sông ấy không chỉ đưa tài liệu từ Xiêm về nước. Theo chiều ngược lại, nó mang tin tức từ quê nhà sang, cùng những người liên lạc và những thanh niên tìm sang học tập. Qua các đường dây của Hội Việt Nam Cách mạng Thanh niên, Người theo dõi sát tình hình trong nước. Những tin tức của năm 1929 vừa đáng mừng vừa đáng lo. Phong trào đang lớn mạnh hơn bao giờ hết, nhưng cũng đang đứng trước nguy cơ chia rẽ lớn hơn bao giờ hết. Chính những tin tức ấy sẽ quyết định chặng đường tiếp theo của ông Thầu Chín.","doc":1},{"loai":"doan","tieu_de":"Hội Thanh niên và phong trào vô sản hóa","text":"Để hiểu những tin tức ấy, phải nhìn lại con đường của Hội Việt Nam Cách mạng Thanh niên. Hội ra đời ở Quảng Châu tháng 6/1925, do Nguyễn Ái Quốc sáng lập, với hạt nhân là Cộng sản đoàn. Qua các lớp huấn luyện của Người, nhiều lớp thanh niên được đào tạo rồi trở về nước hoạt động. Đến năm 1928 – 1929, Hội đã có cơ sở ở cả ba kỳ, và trong kiều bào ở Xiêm.\n\nCuối năm 1928, Hội phát động phong trào “vô sản hóa”. Các hội viên, phần lớn là trí thức, học sinh, đi vào nhà máy, hầm mỏ, đồn điền, sống và làm việc như công nhân, vừa tự rèn luyện vừa tuyên truyền, tổ chức công nhân. Phong trào công nhân nhờ vậy lên cao. Nhưng chính sự trưởng thành nhanh chóng ấy đặt ra một câu hỏi mới: Hội Thanh niên vốn chỉ là tổ chức quá độ, vậy đã đến lúc lập một đảng cộng sản thật sự hay chưa? Những người trả lời rằng đã đến lúc và những người muốn chờ thêm bắt đầu đi theo những ngả khác nhau.","doc":2},{"loai":"anh","src":"textures/bang_w/G10_2_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Tin từ quê nhà và chuyến đi cuối năm 1929”, nhìn từ xa."},{"loai":"doan","tieu_de":"Căn nhà số 5D phố Hàm Long","text":"Những người nóng lòng nhất là các hội viên Thanh niên ở Bắc Kỳ, nơi phong trào công nhân phát triển mạnh. Cuối tháng 3/1929, tại căn nhà số 5D phố Hàm Long, Hà Nội, một nhóm hội viên tiên tiến họp và lập ra chi bộ cộng sản đầu tiên ở Việt Nam, do Trần Văn Cung làm bí thư. Đó là bước chuẩn bị trực tiếp cho việc thành lập một đảng cộng sản.\n\nTháng 5/1929, Hội Thanh niên họp đại hội lần thứ nhất ở Hương Cảng. Đoàn đại biểu Bắc Kỳ đề nghị giải tán Hội Thanh niên để lập ngay đảng cộng sản. Đề nghị không được chấp nhận, đoàn Bắc Kỳ bỏ đại hội ra về. Ngày 17/6/1929, tại số nhà 312 phố Khâm Thiên, Hà Nội, đại biểu các tổ chức cộng sản ở Bắc Kỳ họp và thành lập Đông Dương Cộng sản Đảng. Hội nghị thông qua Tuyên ngôn, Điều lệ, lấy cờ đỏ búa liềm làm đảng kỳ và ra báo Búa Liềm làm cơ quan ngôn luận. Chỉ trong ba tháng, từ một chi bộ nhỏ đã hình thành một đảng có tổ chức khắp Bắc Kỳ.","doc":3},{"loai":"ban_co_biet","text":"Ngày 10/10/1929, trong khi Nguyễn Ái Quốc đang sống giữa kiều bào ở Xiêm, tòa án ở Vinh (Nghệ An) đã xử vắng mặt và kết án tử hình Người.","nguon_ten":"Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch; Hồ Chí Minh – Biên niên tiểu sử, tập 1","doc":4},{"loai":"doan","tieu_de":"Ba tổ chức cùng mang tên cộng sản","text":"Sự ra đời của Đông Dương Cộng sản Đảng tác động mạnh tới những hội viên Thanh niên còn lại. Tháng 8/1929, những hội viên tiên tiến trong Tổng bộ Thanh niên và Kỳ bộ Nam Kỳ lập ra An Nam Cộng sản Đảng. Tháng 9/1929, những người tiên tiến trong Tân Việt Cách mạng Đảng, một tổ chức yêu nước hoạt động chủ yếu ở Trung Kỳ, tuyên bố thành lập Đông Dương Cộng sản Liên đoàn.\n\nNhư vậy, chỉ trong vòng ba tháng, ở Việt Nam đã có ba tổ chức cùng mang tên cộng sản. Cả ba đều muốn đi theo chủ nghĩa Mác – Lênin, đều muốn lãnh đạo công nhân, nông dân đấu tranh. Nhưng các tổ chức ấy hoạt động riêng rẽ, tranh giành ảnh hưởng trong quần chúng, có lúc còn công kích lẫn nhau. Mỗi bên lại mong được Quốc tế Cộng sản công nhận là đảng chính thức. Với một phong trào còn non trẻ, đang chịu sự đàn áp khốc liệt của mật thám, sự chia rẽ ấy có thể làm hỏng tất cả những gì đã gây dựng suốt mấy năm trời.","doc":5},{"loai":"doan","tieu_de":"Một bản án vắng mặt","text":"Cũng trong những tháng ấy, bộ máy đàn áp của thực dân dồn dập ra tay. Sau vụ ám sát tên trùm mộ phu Bazin ở Hà Nội tháng 2/1929, mật thám mở những đợt khủng bố lớn, bắt bớ hàng loạt người yêu nước. Ngày 10/10/1929, tòa án ở Vinh, Nghệ An, xử vắng mặt và kết án tử hình Nguyễn Ái Quốc. Khi ấy Người đang ở bản Mạy, cách nơi tòa tuyên án chỉ một dòng sông và một dãy núi.\n\nBản án cho thấy chính quyền thực dân coi Người là mối nguy lớn nhất đối với ách cai trị của họ. Nó cũng có nghĩa là Người không thể công khai trở về Tổ quốc: mọi bước đi đều phải bí mật, mọi hành trình đều phải qua những con đường vòng. Trong hoàn cảnh ấy, việc Người vẫn quyết định rời nơi tương đối an toàn giữa kiều bào, để tới một thành phố đầy mật thám như Hương Cảng, càng cho thấy nhiệm vụ phía trước hệ trọng đến mức nào.","doc":6},{"loai":"anh","src":"textures/bai/G10_v5.jpg","chu_thich":"Một góc không gian 3D tái hiện xóm Việt kiều ở bản Mạy (Na Chok), Nakhon Phanom, những năm 1928 – 1929.","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Bức thư ngày 27/10/1929","text":"Ở Mátxcơva, Quốc tế Cộng sản theo dõi tình hình Đông Dương với nhiều lo lắng. Ngày 27/10/1929, Quốc tế Cộng sản gửi thư cho những người cộng sản Đông Dương về việc thành lập một đảng cộng sản ở Đông Dương. Bức thư phê phán sự chia rẽ, chỉ rõ nhiệm vụ quan trọng và cấp bách nhất lúc này là lập một đảng cách mạng của giai cấp vô sản, có tính chất quần chúng, và đảng ấy chỉ có thể có một.\n\nNhưng một bức thư chưa đủ để hợp nhất những người đang nghi ngại nhau. Cần một người vừa hiểu phong trào trong nước, vừa được các bên kính trọng, lại có tư cách đại diện cho Quốc tế Cộng sản. Người đó là Nguyễn Ái Quốc: người sáng lập Hội Thanh niên, tổ chức mà từ đó hai trong ba đảng mới ra đời, người thầy của nhiều cán bộ lãnh đạo hai tổ chức ấy, đồng thời là cán bộ Ban Phương Đông của Quốc tế Cộng sản. Nắm được tình hình, Người chủ động đứng ra gánh vác việc hợp nhất.","doc":7},{"loai":"doan","tieu_de":"Tháng 11/1929: từ biệt đất Xiêm","text":"Tháng 11/1929, ông Thầu Chín từ biệt bà con Việt kiều, rời đất Xiêm. Đó là lúc Người vừa kết thúc khoảng ba tháng hoạt động ở Nakhon Phanom, chặng dừng chân dài nhất trong suốt thời gian ở Xiêm. Trong hoạt động bí mật, hành trình càng ít người biết càng tốt, bởi mật thám Pháp có tai mắt cả trên đất Xiêm. Hành trang quý nhất Người mang theo là kinh nghiệm của hơn một năm sống giữa những người lao động nghèo nơi đất khách: hiểu họ nghĩ gì, cần gì, và có thể tập hợp họ lại bằng cách nào.\n\nNhững gì Người để lại thì rõ ràng hơn. Hội Thân ái, Hội Hợp tác đã được củng cố; một lớp cốt cán trong kiều bào đã được bồi dưỡng; đường dây liên lạc qua Lào về trong nước vẫn tiếp tục hoạt động. Những cơ sở ấy về sau còn là chỗ dựa cho nhiều cán bộ cách mạng Việt Nam phải lánh sang Xiêm trong những năm 1930. Theo báo cáo Người gửi Quốc tế Cộng sản ngày 18/2/1930, Người đến Hương Cảng ngày 23/12/1929. Ngay sau đó, Người bắt tay vào việc triệu tập đại biểu các tổ chức cộng sản trong nước.","doc":8},{"loai":"anh","src":"textures/bang_w/G10_2_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Tin từ quê nhà và chuyến đi cuối năm 1929”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Hội nghị ở Cửu Long","text":"Hội nghị hợp nhất họp từ ngày 6/1 đến ngày 7/2/1930 tại Cửu Long, Hương Cảng, trong điều kiện hết sức bí mật. Nguyễn Ái Quốc chủ trì với tư cách phái viên của Quốc tế Cộng sản. Dự hội nghị có hai đại biểu của Đông Dương Cộng sản Đảng là Trịnh Đình Cửu, Nguyễn Đức Cảnh, và hai đại biểu của An Nam Cộng sản Đảng là Châu Văn Liêm, Nguyễn Thiệu. Đông Dương Cộng sản Liên đoàn không có đại biểu dự.\n\nNgười phê phán những biểu hiện chia rẽ, đề nghị các bên bỏ mọi thành kiến, xung đột cũ, thành thật hợp tác để thống nhất các nhóm cộng sản. Hội nghị nhất trí hợp nhất thành một đảng lấy tên Đảng Cộng sản Việt Nam, thông qua Chính cương vắn tắt, Sách lược vắn tắt, Chương trình tóm tắt và Điều lệ vắn tắt do Người soạn thảo. Nhân dịp này, Người viết Lời kêu gọi gửi công nhân, nông dân, binh lính, thanh niên, học sinh và đồng bào bị áp bức. Ngày 24/2/1930, Đông Dương Cộng sản Liên đoàn được chấp nhận gia nhập, hoàn tất việc thống nhất.","doc":9},{"loai":"ban_co_biet","text":"Hội nghị hợp nhất kéo dài từ ngày 6/1 đến ngày 7/2/1930. Năm 1960, Đại hội đại biểu toàn quốc lần thứ III của Đảng quyết định lấy ngày 3/2 hằng năm làm ngày kỷ niệm thành lập Đảng.","nguon_ten":"Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia","doc":10},{"loai":"doan","tieu_de":"Bài học mang từ đất Xiêm","text":"Nhìn lại, hơn một năm làm ông Thầu Chín không phải là một chặng nghỉ chân giữa hai nhiệm vụ lớn. Ở Xiêm, Người trực tiếp làm công tác quần chúng: sống cùng dân, lao động cùng dân, dạy dân biết chữ, gây dựng tổ chức từ những việc nhỏ nhất như đào một cái giếng, lập một hội tương trợ. Người hiểu sâu hơn tâm tư của những người lao động Việt Nam, những nông dân mất đất, những người thợ nghèo phải bỏ quê mà đi.\n\nNhững văn kiện đầu tiên của Đảng soạn ở Cửu Long mang dấu ấn ấy. Chính cương vắn tắt chủ trương làm tư sản dân quyền cách mạng và thổ địa cách mạng để đi tới xã hội cộng sản. Sách lược vắn tắt nêu rõ Đảng phải thu phục đại bộ phận công nhân và dân cày, đồng thời liên lạc với tiểu tư sản, trí thức, trung nông. Đó là một đường lối đặt độc lập dân tộc và quyền lợi của người lao động vào trung tâm. Từ xóm Việt kiều bên sông Mê Kông đến căn phòng họp bí mật ở Cửu Long, sợi chỉ xuyên suốt vẫn là niềm tin vào sức mạnh của quần chúng.","doc":11},{"loai":"anh","src":"textures/bang_w/G10_2_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Tin từ quê nhà và chuyến đi cuối năm 1929”, nhìn từ trên cao."}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia","Đảng Cộng sản Việt Nam, Văn kiện Đảng Toàn tập, tập 1 – 2, NXB Chính trị quốc gia","Bảo tàng Hồ Chí Minh – Khu tưởng niệm Chủ tịch Hồ Chí Minh tại làng Nachok (bản Mạy), tỉnh Nakhon Phanom, Thái Lan (2019): https://baotanghochiminh.vn/khu-tuong-niem-chu-tich-ho-chi-minh-tai-lang-nachok-ban-may-tinh-nakhon-phanom-thai-lan.htm","GS.TS Đàm Đức Vượng, Về trường hợp “Thầu Chín” ở Xiêm (2026), dẫn báo cáo của Nguyễn Ái Quốc gửi Quốc tế Cộng sản ngày 18/2/1930: https://ivanlevanlan.wordpress.com/2026/03/20/ve-truong-hop-thau-chin-o-xiem/","Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch"],"doc":[{"t":"Ba tổ chức, một đảng: vì sao ông Thầu Chín rời đất Xiêm cuối năm 1929. Năm 1929, những tin tức vượt sông Mê Kông tới xóm Việt kiều ở Nakhon Phanom khiến ông Thầu Chín không thể ngồi yên. Ở quê nhà, những người cộng sản đầu tiên đã chia thành ba tổ chức, mỗi nơi một ngả. Cùng năm ấy, một tòa án của chính quyền thuộc địa kết án tử hình Người. Cuối năm, Người lặng lẽ rời Xiêm để làm một việc mà chỉ Người mới đủ uy tín để làm."},{"t":"Mùa thu ở bản Mạy. Mùa thu năm 1929, ông Thầu Chín đang ở bản Mạy, tức làng Nachok, ngoại ô Nakhon Phanom. Theo Bảo tàng Hồ Chí Minh, Người hoạt động ở đây từ khoảng cuối tháng 7 đến cuối tháng 10 năm ấy, và đây là nơi Người ở lâu nhất trên đất Xiêm. Từ bờ sông nhìn sang là đất Lào; xa hơn nữa, sau dãy Trường Sơn, là Nghệ An, Hà Tĩnh, quê hương mà Người đã xa gần hai mươi năm. Con đường qua sông ấy không chỉ đưa tài liệu từ Xiêm về nước. Theo chiều ngược lại, nó mang tin tức từ quê nhà sang, cùng những người liên lạc và những thanh niên tìm sang học tập. Qua các đường dây của Hội Việt Nam Cách mạng Thanh niên, Người theo dõi sát tình hình trong nước. Những tin tức của năm 1929 vừa đáng mừng vừa đáng lo. Phong trào đang lớn mạnh hơn bao giờ hết, nhưng cũng đang đứng trước nguy cơ chia rẽ lớn hơn bao giờ hết. Chính những tin tức ấy sẽ quyết định chặng đường tiếp theo của ông Thầu Chín."},{"t":"Hội Thanh niên và phong trào vô sản hóa. Để hiểu những tin tức ấy, phải nhìn lại con đường của Hội Việt Nam Cách mạng Thanh niên. Hội ra đời ở Quảng Châu tháng 6/1925, do Nguyễn Ái Quốc sáng lập, với hạt nhân là Cộng sản đoàn. Qua các lớp huấn luyện của Người, nhiều lớp thanh niên được đào tạo rồi trở về nước hoạt động. Đến năm 1928 – 1929, Hội đã có cơ sở ở cả ba kỳ, và trong kiều bào ở Xiêm. Cuối năm 1928, Hội phát động phong trào “vô sản hóa”. Các hội viên, phần lớn là trí thức, học sinh, đi vào nhà máy, hầm mỏ, đồn điền, sống và làm việc như công nhân, vừa tự rèn luyện vừa tuyên truyền, tổ chức công nhân. Phong trào công nhân nhờ vậy lên cao. Nhưng chính sự trưởng thành nhanh chóng ấy đặt ra một câu hỏi mới: Hội Thanh niên vốn chỉ là tổ chức quá độ, vậy đã đến lúc lập một đảng cộng sản thật sự hay chưa? Những người trả lời rằng đã đến lúc và những người muốn chờ thêm bắt đầu đi theo những ngả khác nhau."},{"t":"Căn nhà số 5D phố Hàm Long. Những người nóng lòng nhất là các hội viên Thanh niên ở Bắc Kỳ, nơi phong trào công nhân phát triển mạnh. Cuối tháng 3/1929, tại căn nhà số 5D phố Hàm Long, Hà Nội, một nhóm hội viên tiên tiến họp và lập ra chi bộ cộng sản đầu tiên ở Việt Nam, do Trần Văn Cung làm bí thư. Đó là bước chuẩn bị trực tiếp cho việc thành lập một đảng cộng sản. Tháng 5/1929, Hội Thanh niên họp đại hội lần thứ nhất ở Hương Cảng. Đoàn đại biểu Bắc Kỳ đề nghị giải tán Hội Thanh niên để lập ngay đảng cộng sản. Đề nghị không được chấp nhận, đoàn Bắc Kỳ bỏ đại hội ra về. Ngày 17/6/1929, tại số nhà 312 phố Khâm Thiên, Hà Nội, đại biểu các tổ chức cộng sản ở Bắc Kỳ họp và thành lập Đông Dương Cộng sản Đảng. Hội nghị thông qua Tuyên ngôn, Điều lệ, lấy cờ đỏ búa liềm làm đảng kỳ và ra báo Búa Liềm làm cơ quan ngôn luận. Chỉ trong ba tháng, từ một chi bộ nhỏ đã hình thành một đảng có tổ chức khắp Bắc Kỳ."},{"t":"Bạn có biết? Ngày 10/10/1929, trong khi Nguyễn Ái Quốc đang sống giữa kiều bào ở Xiêm, tòa án ở Vinh (Nghệ An) đã xử vắng mặt và kết án tử hình Người."},{"t":"Ba tổ chức cùng mang tên cộng sản. Sự ra đời của Đông Dương Cộng sản Đảng tác động mạnh tới những hội viên Thanh niên còn lại. Tháng 8/1929, những hội viên tiên tiến trong Tổng bộ Thanh niên và Kỳ bộ Nam Kỳ lập ra An Nam Cộng sản Đảng. Tháng 9/1929, những người tiên tiến trong Tân Việt Cách mạng Đảng, một tổ chức yêu nước hoạt động chủ yếu ở Trung Kỳ, tuyên bố thành lập Đông Dương Cộng sản Liên đoàn. Như vậy, chỉ trong vòng ba tháng, ở Việt Nam đã có ba tổ chức cùng mang tên cộng sản. Cả ba đều muốn đi theo chủ nghĩa Mác – Lênin, đều muốn lãnh đạo công nhân, nông dân đấu tranh. Nhưng các tổ chức ấy hoạt động riêng rẽ, tranh giành ảnh hưởng trong quần chúng, có lúc còn công kích lẫn nhau. Mỗi bên lại mong được Quốc tế Cộng sản công nhận là đảng chính thức. Với một phong trào còn non trẻ, đang chịu sự đàn áp khốc liệt của mật thám, sự chia rẽ ấy có thể làm hỏng tất cả những gì đã gây dựng suốt mấy năm trời."},{"t":"Một bản án vắng mặt. Cũng trong những tháng ấy, bộ máy đàn áp của thực dân dồn dập ra tay. Sau vụ ám sát tên trùm mộ phu Bazin ở Hà Nội tháng 2/1929, mật thám mở những đợt khủng bố lớn, bắt bớ hàng loạt người yêu nước. Ngày 10/10/1929, tòa án ở Vinh, Nghệ An, xử vắng mặt và kết án tử hình Nguyễn Ái Quốc. Khi ấy Người đang ở bản Mạy, cách nơi tòa tuyên án chỉ một dòng sông và một dãy núi. Bản án cho thấy chính quyền thực dân coi Người là mối nguy lớn nhất đối với ách cai trị của họ. Nó cũng có nghĩa là Người không thể công khai trở về Tổ quốc: mọi bước đi đều phải bí mật, mọi hành trình đều phải qua những con đường vòng. Trong hoàn cảnh ấy, việc Người vẫn quyết định rời nơi tương đối an toàn giữa kiều bào, để tới một thành phố đầy mật thám như Hương Cảng, càng cho thấy nhiệm vụ phía trước hệ trọng đến mức nào."},{"t":"Bức thư ngày 27/10/1929. Ở Mátxcơva, Quốc tế Cộng sản theo dõi tình hình Đông Dương với nhiều lo lắng. Ngày 27/10/1929, Quốc tế Cộng sản gửi thư cho những người cộng sản Đông Dương về việc thành lập một đảng cộng sản ở Đông Dương. Bức thư phê phán sự chia rẽ, chỉ rõ nhiệm vụ quan trọng và cấp bách nhất lúc này là lập một đảng cách mạng của giai cấp vô sản, có tính chất quần chúng, và đảng ấy chỉ có thể có một. Nhưng một bức thư chưa đủ để hợp nhất những người đang nghi ngại nhau. Cần một người vừa hiểu phong trào trong nước, vừa được các bên kính trọng, lại có tư cách đại diện cho Quốc tế Cộng sản. Người đó là Nguyễn Ái Quốc: người sáng lập Hội Thanh niên, tổ chức mà từ đó hai trong ba đảng mới ra đời, người thầy của nhiều cán bộ lãnh đạo hai tổ chức ấy, đồng thời là cán bộ Ban Phương Đông của Quốc tế Cộng sản. Nắm được tình hình, Người chủ động đứng ra gánh vác việc hợp nhất."},{"t":"Tháng 11/1929: từ biệt đất Xiêm. Tháng 11/1929, ông Thầu Chín từ biệt bà con Việt kiều, rời đất Xiêm. Đó là lúc Người vừa kết thúc khoảng ba tháng hoạt động ở Nakhon Phanom, chặng dừng chân dài nhất trong suốt thời gian ở Xiêm. Trong hoạt động bí mật, hành trình càng ít người biết càng tốt, bởi mật thám Pháp có tai mắt cả trên đất Xiêm. Hành trang quý nhất Người mang theo là kinh nghiệm của hơn một năm sống giữa những người lao động nghèo nơi đất khách: hiểu họ nghĩ gì, cần gì, và có thể tập hợp họ lại bằng cách nào. Những gì Người để lại thì rõ ràng hơn. Hội Thân ái, Hội Hợp tác đã được củng cố; một lớp cốt cán trong kiều bào đã được bồi dưỡng; đường dây liên lạc qua Lào về trong nước vẫn tiếp tục hoạt động. Những cơ sở ấy về sau còn là chỗ dựa cho nhiều cán bộ cách mạng Việt Nam phải lánh sang Xiêm trong những năm 1930. Theo báo cáo Người gửi Quốc tế Cộng sản ngày 18/2/1930, Người đến Hương Cảng ngày 23/12/1929. Ngay sau đó, Người bắt tay vào việc triệu tập đại biểu các tổ chức cộng sản trong nước."},{"t":"Hội nghị ở Cửu Long. Hội nghị hợp nhất họp từ ngày 6/1 đến ngày 7/2/1930 tại Cửu Long, Hương Cảng, trong điều kiện hết sức bí mật. Nguyễn Ái Quốc chủ trì với tư cách phái viên của Quốc tế Cộng sản. Dự hội nghị có hai đại biểu của Đông Dương Cộng sản Đảng là Trịnh Đình Cửu, Nguyễn Đức Cảnh, và hai đại biểu của An Nam Cộng sản Đảng là Châu Văn Liêm, Nguyễn Thiệu. Đông Dương Cộng sản Liên đoàn không có đại biểu dự. Người phê phán những biểu hiện chia rẽ, đề nghị các bên bỏ mọi thành kiến, xung đột cũ, thành thật hợp tác để thống nhất các nhóm cộng sản. Hội nghị nhất trí hợp nhất thành một đảng lấy tên Đảng Cộng sản Việt Nam, thông qua Chính cương vắn tắt, Sách lược vắn tắt, Chương trình tóm tắt và Điều lệ vắn tắt do Người soạn thảo. Nhân dịp này, Người viết Lời kêu gọi gửi công nhân, nông dân, binh lính, thanh niên, học sinh và đồng bào bị áp bức. Ngày 24/2/1930, Đông Dương Cộng sản Liên đoàn được chấp nhận gia nhập, hoàn tất việc thống nhất."},{"t":"Bạn có biết? Hội nghị hợp nhất kéo dài từ ngày 6/1 đến ngày 7/2/1930. Năm 1960, Đại hội đại biểu toàn quốc lần thứ III của Đảng quyết định lấy ngày 3/2 hằng năm làm ngày kỷ niệm thành lập Đảng."},{"t":"Bài học mang từ đất Xiêm. Nhìn lại, hơn một năm làm ông Thầu Chín không phải là một chặng nghỉ chân giữa hai nhiệm vụ lớn. Ở Xiêm, Người trực tiếp làm công tác quần chúng: sống cùng dân, lao động cùng dân, dạy dân biết chữ, gây dựng tổ chức từ những việc nhỏ nhất như đào một cái giếng, lập một hội tương trợ. Người hiểu sâu hơn tâm tư của những người lao động Việt Nam, những nông dân mất đất, những người thợ nghèo phải bỏ quê mà đi. Những văn kiện đầu tiên của Đảng soạn ở Cửu Long mang dấu ấn ấy. Chính cương vắn tắt chủ trương làm tư sản dân quyền cách mạng và thổ địa cách mạng để đi tới xã hội cộng sản. Sách lược vắn tắt nêu rõ Đảng phải thu phục đại bộ phận công nhân và dân cày, đồng thời liên lạc với tiểu tư sản, trí thức, trung nông. Đó là một đường lối đặt độc lập dân tộc và quyền lợi của người lao động vào trung tâm. Từ xóm Việt kiều bên sông Mê Kông đến căn phòng họp bí mật ở Cửu Long, sợi chỉ xuyên suốt vẫn là niềm tin vào sức mạnh của quần chúng."}],"so_chu":1907},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Từ Quảng Châu đến Cửu Long qua đất Xiêm: dòng thời gian 1927 – 1930","sapo":"Hơn một năm của ông Thầu Chín ở Xiêm nằm giữa hai bước ngoặt lớn: sự tan vỡ của cách mạng Trung Quốc năm 1927 và sự ra đời của Đảng Cộng sản Việt Nam đầu năm 1930. Đặt những mốc nhỏ ở các xóm Việt kiều bên cạnh những biến cố ở Hà Nội, Hương Cảng, Mátxcơva, ta mới thấy hết vì sao quãng thời gian tưởng như lặng lẽ ấy lại quan trọng đến vậy.","bia":{"src":"textures/bai/G10_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Đọc dòng thời gian này thế nào","text":"Dòng thời gian dưới đây chạy song song trên hai tuyến. Tuyến thứ nhất là hành trình của Nguyễn Ái Quốc: rời Quảng Châu năm 1927, vòng qua Liên Xô và châu Âu, tới Xiêm giữa năm 1928, sống và hoạt động trong kiều bào tới tháng 11/1929, rồi sang Hương Cảng. Tuyến thứ hai là những biến chuyển của phong trào cách mạng trong nước, nơi các hội viên Thanh niên từng được Người đào tạo đang lớn lên, rồi chia thành ba tổ chức cộng sản.\n\nHai tuyến ấy gặp nhau ở hội nghị hợp nhất đầu năm 1930. Đọc riêng từng tuyến, ta chỉ thấy một người đi đường xa và một phong trào đang sôi sục. Đọc song song, ta thấy rõ hơn: trong lúc phong trào trong nước tìm đường tới một đảng cộng sản, người có thể thống nhất phong trào ấy đang ở rất gần. Người chỉ cách quê nhà một dòng sông và một dãy núi, sống giữa những người nông dân Việt kiều với cái tên Thầu Chín.","doc":1},{"loai":"doan","tieu_de":"Chặng thứ nhất: con đường vòng (1927 – 1928)","text":"Chính biến tháng 4/1927 ở Trung Quốc buộc Nguyễn Ái Quốc phải rời Quảng Châu, nơi Người đã gắn bó hơn hai năm và đào tạo nhiều lớp cán bộ cho Hội Thanh niên. Con đường từ đó tới Xiêm kéo dài hơn một năm: trở lại Mátxcơva, sang các nước châu Âu, rồi theo đường biển trở lại châu Á.\n\nĐó là quãng thời gian Người phải chờ đợi và tìm cách. Tổ quốc ở gần mà không về được; Quảng Châu, Hương Cảng, Thượng Hải đều đã trở thành nơi nguy hiểm. Xiêm, vương quốc độc lập duy nhất ở Đông Nam Á, có đông kiều bào Việt Nam và chỉ cách Đông Dương một dòng sông, là lựa chọn hợp lý nhất. Khi đặt chân tới Bangkok tháng 7/1928, Người đã ba mươi tám tuổi, đã sống và làm việc ở ba châu lục, và vẫn chưa một lần được trở về quê hương kể từ ngày ra đi năm 1911.","doc":2},{"loai":"anh","src":"textures/bang_w/G10_3_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn từ xa."},{"loai":"moc","items":[["6/1925","Nguyễn Ái Quốc sáng lập Hội Việt Nam Cách mạng Thanh niên ở Quảng Châu; ngày 21/6 ra số đầu tiên báo Thanh Niên"],["1927","Những bài giảng của Người ở các lớp huấn luyện tại Quảng Châu được in thành cuốn Đường Kách mệnh"],["12/4/1927","Tưởng Giới Thạch làm chính biến ở Thượng Hải; ba ngày sau cuộc khủng bố lan tới Quảng Châu"],["5/1927","Nguyễn Ái Quốc buộc phải rời Quảng Châu, sau đó trở lại Mátxcơva"],["12/1927","Có mặt ở Brúcxen (Bỉ), dự một hội nghị của Liên đoàn chống đế quốc"],["đầu – giữa 1928","Hoạt động ở một số nước châu Âu như Pháp, Đức, Thụy Sĩ, Ý, rồi lên tàu trở lại châu Á"],["7/1928","Đến Bangkok, thủ đô vương quốc Xiêm; bắt đầu quãng đời mang tên Thầu Chín"],["1928","Ở Bản Đông, tỉnh Phichit, khoảng mười lăm ngày, gặp gỡ cốt cán và tìm hiểu đời sống kiều bào"],["1928","Lên Udon Thani, hoạt động trong các xóm Việt kiều ở vùng Nong Bua và bản Nong On"],["cuối 1928","Hội Thanh niên phát động phong trào vô sản hóa: hội viên vào nhà máy, hầm mỏ, đồn điền làm việc cùng công nhân"],["1928 – 1929","Cùng kiều bào xây dựng Hội Thân ái, Hội Hợp tác; đổi báo Đồng Thanh thành Thân Ái; mở lớp dạy chữ quốc ngữ, dịch sách"],["1928 – 1929","Đi qua nhiều tỉnh đông bắc Xiêm như Sakon Nakhon, Nong Khai để gây dựng và củng cố cơ sở trong kiều bào"],["cuối 3/1929","Chi bộ cộng sản đầu tiên ra đời tại số nhà 5D phố Hàm Long, Hà Nội"],["5/1929","Đại hội lần thứ nhất Hội Thanh niên ở Hương Cảng; đoàn Bắc Kỳ đề nghị lập ngay đảng cộng sản, không được chấp nhận, bỏ về"],["17/6/1929","Đông Dương Cộng sản Đảng thành lập tại số nhà 312 phố Khâm Thiên, Hà Nội"],["cuối 7 – cuối 10/1929","Hoạt động ở Nakhon Phanom, lâu nhất ở làng Nachok (bản Mạy); cùng bà con làm ruộng, đào giếng, dựng nhà"],["8/1929","Hội viên tiên tiến trong Tổng bộ Thanh niên và Kỳ bộ Nam Kỳ lập An Nam Cộng sản Đảng"],["9/1929","Những người tiên tiến trong Tân Việt Cách mạng Đảng lập Đông Dương Cộng sản Liên đoàn"],["10/10/1929","Tòa án ở Vinh (Nghệ An) xử vắng mặt, kết án tử hình Nguyễn Ái Quốc"],["27/10/1929","Quốc tế Cộng sản gửi thư yêu cầu những người cộng sản Đông Dương thành lập một đảng duy nhất"],["11/1929","Ông Thầu Chín từ biệt kiều bào, rời Xiêm sang Trung Quốc"],["23/12/1929","Đến Hương Cảng, triệu tập đại biểu Đông Dương Cộng sản Đảng và An Nam Cộng sản Đảng"],["6/1 – 7/2/1930","Chủ trì hội nghị hợp nhất tại Cửu Long (Hương Cảng), thành lập Đảng Cộng sản Việt Nam"],["18/2/1930","Viết báo cáo gửi Quốc tế Cộng sản về việc hợp nhất các tổ chức cộng sản"],["24/2/1930","Đông Dương Cộng sản Liên đoàn được chấp nhận gia nhập Đảng Cộng sản Việt Nam"],["1939","Nước Xiêm chính thức đổi tên thành Thái Lan"],["1960","Đại hội III của Đảng quyết định lấy ngày 3/2 hằng năm làm ngày kỷ niệm thành lập Đảng"],["2002","Hoàn thành khu di tích Chủ tịch Hồ Chí Minh ở Udon Thani, có ngôi nhà phục dựng"],["19/5/2016","Khánh thành khu tưởng niệm Chủ tịch Hồ Chí Minh tại làng Nachok (bản Mạy), Nakhon Phanom"]],"doc":3},{"loai":"doan","tieu_de":"Chặng thứ hai: hơn một năm giữa kiều bào (7/1928 – 11/1929)","text":"Những mốc trên đất Xiêm phần lớn không có ngày cụ thể. Đó là đặc điểm của hoạt động bí mật: ít để lại giấy tờ, những gì còn lại chủ yếu đến từ báo cáo của chính Người, từ hồi ký của những người từng hoạt động cùng Người như Lê Mạnh Trinh, và từ lời kể của kiều bào. Vì thế, nhiều mốc chỉ có thể ghi theo tháng, theo mùa hoặc theo năm.\n\nDẫu vậy, đường đi của Người khá rõ. Từ Bangkok, Người lên Bản Đông ở Phichit, ở đó khoảng mười lăm ngày. Từ Phichit, Người lên Udon Thani, hoạt động ở vùng Nong Bua và bản Nong On, rồi tới Sakon Nakhon, Nong Khai và Nakhon Phanom. Theo Bảo tàng Hồ Chí Minh, Người ở Nakhon Phanom từ khoảng cuối tháng 7 đến cuối tháng 10/1929, lâu nhất ở làng Nachok, tức bản Mạy. Suốt chặng ấy, Người cùng kiều bào xây dựng Hội Thân ái, Hội Hợp tác, đổi báo Đồng Thanh thành Thân Ái, mở lớp dạy chữ và dịch sách.","doc":4},{"loai":"ban_co_biet","text":"Tên nước Xiêm chính thức được đổi thành Thái Lan vào năm 1939, tức mười năm sau khi ông Thầu Chín rời đi. Vì thế, sách báo tiếng Việt thời ấy gọi nơi này là Xiêm hoặc Xiêm La.","nguon_ten":"Bách khoa toàn thư Britannica, mục Thailand","doc":5},{"loai":"doan","tieu_de":"Chặng thứ ba: năm 1929 sôi động ở quê nhà","text":"Trong khi ông Thầu Chín đi giữa các xóm Việt kiều, năm 1929 ở trong nước dồn dập những biến cố. Cuối tháng 3, chi bộ cộng sản đầu tiên ra đời ở số nhà 5D phố Hàm Long, Hà Nội. Tháng 5, tại đại hội lần thứ nhất của Hội Thanh niên ở Hương Cảng, đoàn Bắc Kỳ đề nghị lập ngay đảng cộng sản nhưng không được chấp nhận, bèn bỏ về. Từ tháng 6 đến tháng 9, lần lượt ra đời Đông Dương Cộng sản Đảng, An Nam Cộng sản Đảng và Đông Dương Cộng sản Liên đoàn.\n\nCùng lúc, bộ máy thực dân siết chặt đàn áp. Ngày 10/10/1929, tòa án ở Vinh kết án tử hình vắng mặt Nguyễn Ái Quốc. Ngày 27/10/1929, Quốc tế Cộng sản gửi thư yêu cầu những người cộng sản Đông Dương lập một đảng duy nhất. Hãy đặt các mốc này cạnh mốc Người rời Nakhon Phanom cuối tháng 10 và rời Xiêm tháng 11/1929. Khi đó ta thấy quyết định lên đường của Người diễn ra đúng vào lúc phong trào cần Người nhất (xem chuyên đề “Tin từ quê nhà và chuyến đi cuối năm 1929”).","doc":6},{"loai":"anh","src":"textures/bai/G10_v1.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện xóm Việt kiều ở bản Mạy (Na Chok), Nakhon Phanom, những năm 1928 – 1929, nhìn từ trên cao.","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Chặng thứ tư: Hương Cảng, mùa xuân năm 1930","text":"Ngày 23/12/1929, Người đến Hương Cảng và triệu tập đại biểu các tổ chức cộng sản. Hội nghị hợp nhất họp từ ngày 6/1 đến 7/2/1930 tại Cửu Long, thành lập Đảng Cộng sản Việt Nam, thông qua những văn kiện đầu tiên do Người soạn thảo. Ngày 18/2/1930, Người viết báo cáo gửi Quốc tế Cộng sản về hội nghị. Ngày 24/2/1930, Đông Dương Cộng sản Liên đoàn được chấp nhận gia nhập Đảng, hoàn tất việc thống nhất.\n\nMốc khép lại dòng thời gian này không nằm ở năm 1930. Ba mươi năm sau, Đại hội đại biểu toàn quốc lần thứ III của Đảng năm 1960 quyết định lấy ngày 3/2 hằng năm làm ngày kỷ niệm thành lập Đảng. Nhìn từ đó, hành trình từ Quảng Châu qua đất Xiêm tới Cửu Long là chương mở đầu của lịch sử Đảng. Và hơn một năm làm ông Thầu Chín giữa kiều bào là trang chuẩn bị lặng lẽ nhưng không thể thiếu của chương ấy.","doc":7},{"loai":"ban_co_biet","text":"Căn nhà số 5D phố Hàm Long, Hà Nội, nơi ra đời chi bộ cộng sản đầu tiên cuối tháng 3/1929, nay là di tích lịch sử, mở cửa đón khách tham quan.","nguon_ten":"Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia","doc":8},{"loai":"doan","tieu_de":"Sau năm 1930: những mốc của ký ức","text":"Sau khi Người rời đi, các xóm Việt kiều ở đông bắc Xiêm tiếp tục là cơ sở của phong trào, là nơi nương náu của nhiều cán bộ cách mạng trong những năm khó khăn. Năm 1939, nước Xiêm đổi tên thành Thái Lan. Cộng đồng người Việt ở đây còn trải qua nhiều biến động, từ những đợt người Việt ở Lào lánh sang năm 1946 đến những chuyến tàu hồi hương đầu những năm 1960. Qua tất cả những biến động ấy, câu chuyện về ông Thầu Chín vẫn được các gia đình truyền lại cho con cháu.\n\nKý ức ấy dần được tạc thành di tích. Ở Udon Thani, khu di tích với ngôi nhà phục dựng được hoàn thành năm 2002. Ở Bản Đông, tỉnh Phichit, một ngôi nhà sàn gỗ và tượng bán thân của Người đã được dựng lên. Ở Nakhon Phanom, khu tưởng niệm tại làng Nachok, bản Mạy, được khánh thành ngày 19/5/2016, đúng dịp kỷ niệm 126 năm ngày sinh của Người (xem chuyên đề “Nhà lưu niệm Hồ Chí Minh ở bản Mạy, Nakhon Phanom”).","doc":9},{"loai":"anh","src":"textures/bang_w/G10_3_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Tên đất, tên người và những con số cần đọc kỹ","text":"Khi đọc tư liệu về giai đoạn này, người xem nên lưu ý mấy điều. Trước hết là tên đất. Sách báo tiếng Việt thường phiên âm tên các tỉnh Thái theo nhiều cách: Udon Thani có khi viết là U Đon, Sakon Nakhon là Sa Côn, Phichit là Phi Chịt. Làng Nachok được kiều bào gọi là bản Mạy, còn tên “Thầu Chín” thường được giải thích là “ông già Chín”, dù khi ấy Người mới ba mươi tám tuổi.\n\nThứ hai là những con số. Các tư liệu đôi khi ghi khác nhau về một sự kiện. Chẳng hạn, về khu tưởng niệm ở Nakhon Phanom, Bảo tàng Hồ Chí Minh ghi công trình khởi công tháng 6/2013, trong khi một bài báo năm 2016 ghi thời điểm khởi công là tháng 3/2014. Dòng thời gian của bảo tàng này ưu tiên các mốc có trong Hồ Chí Minh – Biên niên tiểu sử và các nguồn chính thống; mốc nào chưa có ngày chính xác thì chỉ ghi tháng hoặc năm, thay vì đoán định.","doc":10},{"loai":"anh","src":"textures/bang_w/G10_3_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn từ trên cao."}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia","Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch","Bảo tàng Hồ Chí Minh – Khu tưởng niệm Chủ tịch Hồ Chí Minh tại làng Nachok (bản Mạy), tỉnh Nakhon Phanom, Thái Lan (2019): https://baotanghochiminh.vn/khu-tuong-niem-chu-tich-ho-chi-minh-tai-lang-nachok-ban-may-tinh-nakhon-phanom-thai-lan.htm","Báo Nhân Dân – Hình bóng Bác mãi in đậm ở Thái Lan (19/5/2016): https://nhandan.vn/hinh-bong-bac-mai-in-dam-o-thai-lan-post263450.html","GS.TS Đàm Đức Vượng, Về trường hợp “Thầu Chín” ở Xiêm (2026): https://ivanlevanlan.wordpress.com/2026/03/20/ve-truong-hop-thau-chin-o-xiem/"],"doc":[{"t":"Từ Quảng Châu đến Cửu Long qua đất Xiêm: dòng thời gian 1927 – 1930. Hơn một năm của ông Thầu Chín ở Xiêm nằm giữa hai bước ngoặt lớn: sự tan vỡ của cách mạng Trung Quốc năm 1927 và sự ra đời của Đảng Cộng sản Việt Nam đầu năm 1930. Đặt những mốc nhỏ ở các xóm Việt kiều bên cạnh những biến cố ở Hà Nội, Hương Cảng, Mátxcơva, ta mới thấy hết vì sao quãng thời gian tưởng như lặng lẽ ấy lại quan trọng đến vậy."},{"t":"Đọc dòng thời gian này thế nào. Dòng thời gian dưới đây chạy song song trên hai tuyến. Tuyến thứ nhất là hành trình của Nguyễn Ái Quốc: rời Quảng Châu năm 1927, vòng qua Liên Xô và châu Âu, tới Xiêm giữa năm 1928, sống và hoạt động trong kiều bào tới tháng 11/1929, rồi sang Hương Cảng. Tuyến thứ hai là những biến chuyển của phong trào cách mạng trong nước, nơi các hội viên Thanh niên từng được Người đào tạo đang lớn lên, rồi chia thành ba tổ chức cộng sản. Hai tuyến ấy gặp nhau ở hội nghị hợp nhất đầu năm 1930. Đọc riêng từng tuyến, ta chỉ thấy một người đi đường xa và một phong trào đang sôi sục. Đọc song song, ta thấy rõ hơn: trong lúc phong trào trong nước tìm đường tới một đảng cộng sản, người có thể thống nhất phong trào ấy đang ở rất gần. Người chỉ cách quê nhà một dòng sông và một dãy núi, sống giữa những người nông dân Việt kiều với cái tên Thầu Chín."},{"t":"Chặng thứ nhất: con đường vòng (1927 – 1928). Chính biến tháng 4/1927 ở Trung Quốc buộc Nguyễn Ái Quốc phải rời Quảng Châu, nơi Người đã gắn bó hơn hai năm và đào tạo nhiều lớp cán bộ cho Hội Thanh niên. Con đường từ đó tới Xiêm kéo dài hơn một năm: trở lại Mátxcơva, sang các nước châu Âu, rồi theo đường biển trở lại châu Á. Đó là quãng thời gian Người phải chờ đợi và tìm cách. Tổ quốc ở gần mà không về được; Quảng Châu, Hương Cảng, Thượng Hải đều đã trở thành nơi nguy hiểm. Xiêm, vương quốc độc lập duy nhất ở Đông Nam Á, có đông kiều bào Việt Nam và chỉ cách Đông Dương một dòng sông, là lựa chọn hợp lý nhất. Khi đặt chân tới Bangkok tháng 7/1928, Người đã ba mươi tám tuổi, đã sống và làm việc ở ba châu lục, và vẫn chưa một lần được trở về quê hương kể từ ngày ra đi năm 1911."},{"t":"Các mốc thời gian. 6/1925: Nguyễn Ái Quốc sáng lập Hội Việt Nam Cách mạng Thanh niên ở Quảng Châu; ngày 21/6 ra số đầu tiên báo Thanh Niên. 1927: Những bài giảng của Người ở các lớp huấn luyện tại Quảng Châu được in thành cuốn Đường Kách mệnh. 12/4/1927: Tưởng Giới Thạch làm chính biến ở Thượng Hải; ba ngày sau cuộc khủng bố lan tới Quảng Châu. 5/1927: Nguyễn Ái Quốc buộc phải rời Quảng Châu, sau đó trở lại Mátxcơva. 12/1927: Có mặt ở Brúcxen (Bỉ), dự một hội nghị của Liên đoàn chống đế quốc. đầu – giữa 1928: Hoạt động ở một số nước châu Âu như Pháp, Đức, Thụy Sĩ, Ý, rồi lên tàu trở lại châu Á. 7/1928: Đến Bangkok, thủ đô vương quốc Xiêm; bắt đầu quãng đời mang tên Thầu Chín. 1928: Ở Bản Đông, tỉnh Phichit, khoảng mười lăm ngày, gặp gỡ cốt cán và tìm hiểu đời sống kiều bào. 1928: Lên Udon Thani, hoạt động trong các xóm Việt kiều ở vùng Nong Bua và bản Nong On. cuối 1928: Hội Thanh niên phát động phong trào vô sản hóa: hội viên vào nhà máy, hầm mỏ, đồn điền làm việc cùng công nhân. 1928 – 1929: Cùng kiều bào xây dựng Hội Thân ái, Hội Hợp tác; đổi báo Đồng Thanh thành Thân Ái; mở lớp dạy chữ quốc ngữ, dịch sách. 1928 – 1929: Đi qua nhiều tỉnh đông bắc Xiêm như Sakon Nakhon, Nong Khai để gây dựng và củng cố cơ sở trong kiều bào. cuối 3/1929: Chi bộ cộng sản đầu tiên ra đời tại số nhà 5D phố Hàm Long, Hà Nội. 5/1929: Đại hội lần thứ nhất Hội Thanh niên ở Hương Cảng; đoàn Bắc Kỳ đề nghị lập ngay đảng cộng sản, không được chấp nhận, bỏ về. 17/6/1929: Đông Dương Cộng sản Đảng thành lập tại số nhà 312 phố Khâm Thiên, Hà Nội. cuối 7 – cuối 10/1929: Hoạt động ở Nakhon Phanom, lâu nhất ở làng Nachok (bản Mạy); cùng bà con làm ruộng, đào giếng, dựng nhà. 8/1929: Hội viên tiên tiến trong Tổng bộ Thanh niên và Kỳ bộ Nam Kỳ lập An Nam Cộng sản Đảng. 9/1929: Những người tiên tiến trong Tân Việt Cách mạng Đảng lập Đông Dương Cộng sản Liên đoàn. 10/10/1929: Tòa án ở Vinh (Nghệ An) xử vắng mặt, kết án tử hình Nguyễn Ái Quốc. 27/10/1929: Quốc tế Cộng sản gửi thư yêu cầu những người cộng sản Đông Dương thành lập một đảng duy nhất. 11/1929: Ông Thầu Chín từ biệt kiều bào, rời Xiêm sang Trung Quốc. 23/12/1929: Đến Hương Cảng, triệu tập đại biểu Đông Dương Cộng sản Đảng và An Nam Cộng sản Đảng. 6/1 – 7/2/1930: Chủ trì hội nghị hợp nhất tại Cửu Long (Hương Cảng), thành lập Đảng Cộng sản Việt Nam. 18/2/1930: Viết báo cáo gửi Quốc tế Cộng sản về việc hợp nhất các tổ chức cộng sản. 24/2/1930: Đông Dương Cộng sản Liên đoàn được chấp nhận gia nhập Đảng Cộng sản Việt Nam. 1939: Nước Xiêm chính thức đổi tên thành Thái Lan. 1960: Đại hội III của Đảng quyết định lấy ngày 3/2 hằng năm làm ngày kỷ niệm thành lập Đảng. 2002: Hoàn thành khu di tích Chủ tịch Hồ Chí Minh ở Udon Thani, có ngôi nhà phục dựng. 19/5/2016: Khánh thành khu tưởng niệm Chủ tịch Hồ Chí Minh tại làng Nachok (bản Mạy), Nakhon Phanom."},{"t":"Chặng thứ hai: hơn một năm giữa kiều bào (7/1928 – 11/1929). Những mốc trên đất Xiêm phần lớn không có ngày cụ thể. Đó là đặc điểm của hoạt động bí mật: ít để lại giấy tờ, những gì còn lại chủ yếu đến từ báo cáo của chính Người, từ hồi ký của những người từng hoạt động cùng Người như Lê Mạnh Trinh, và từ lời kể của kiều bào. Vì thế, nhiều mốc chỉ có thể ghi theo tháng, theo mùa hoặc theo năm. Dẫu vậy, đường đi của Người khá rõ. Từ Bangkok, Người lên Bản Đông ở Phichit, ở đó khoảng mười lăm ngày. Từ Phichit, Người lên Udon Thani, hoạt động ở vùng Nong Bua và bản Nong On, rồi tới Sakon Nakhon, Nong Khai và Nakhon Phanom. Theo Bảo tàng Hồ Chí Minh, Người ở Nakhon Phanom từ khoảng cuối tháng 7 đến cuối tháng 10/1929, lâu nhất ở làng Nachok, tức bản Mạy. Suốt chặng ấy, Người cùng kiều bào xây dựng Hội Thân ái, Hội Hợp tác, đổi báo Đồng Thanh thành Thân Ái, mở lớp dạy chữ và dịch sách."},{"t":"Bạn có biết? Tên nước Xiêm chính thức được đổi thành Thái Lan vào năm 1939, tức mười năm sau khi ông Thầu Chín rời đi. Vì thế, sách báo tiếng Việt thời ấy gọi nơi này là Xiêm hoặc Xiêm La."},{"t":"Chặng thứ ba: năm 1929 sôi động ở quê nhà. Trong khi ông Thầu Chín đi giữa các xóm Việt kiều, năm 1929 ở trong nước dồn dập những biến cố. Cuối tháng 3, chi bộ cộng sản đầu tiên ra đời ở số nhà 5D phố Hàm Long, Hà Nội. Tháng 5, tại đại hội lần thứ nhất của Hội Thanh niên ở Hương Cảng, đoàn Bắc Kỳ đề nghị lập ngay đảng cộng sản nhưng không được chấp nhận, bèn bỏ về. Từ tháng 6 đến tháng 9, lần lượt ra đời Đông Dương Cộng sản Đảng, An Nam Cộng sản Đảng và Đông Dương Cộng sản Liên đoàn. Cùng lúc, bộ máy thực dân siết chặt đàn áp. Ngày 10/10/1929, tòa án ở Vinh kết án tử hình vắng mặt Nguyễn Ái Quốc. Ngày 27/10/1929, Quốc tế Cộng sản gửi thư yêu cầu những người cộng sản Đông Dương lập một đảng duy nhất. Hãy đặt các mốc này cạnh mốc Người rời Nakhon Phanom cuối tháng 10 và rời Xiêm tháng 11/1929. Khi đó ta thấy quyết định lên đường của Người diễn ra đúng vào lúc phong trào cần Người nhất (xem chuyên đề “Tin từ quê nhà và chuyến đi cuối năm 1929”)."},{"t":"Chặng thứ tư: Hương Cảng, mùa xuân năm 1930. Ngày 23/12/1929, Người đến Hương Cảng và triệu tập đại biểu các tổ chức cộng sản. Hội nghị hợp nhất họp từ ngày 6/1 đến 7/2/1930 tại Cửu Long, thành lập Đảng Cộng sản Việt Nam, thông qua những văn kiện đầu tiên do Người soạn thảo. Ngày 18/2/1930, Người viết báo cáo gửi Quốc tế Cộng sản về hội nghị. Ngày 24/2/1930, Đông Dương Cộng sản Liên đoàn được chấp nhận gia nhập Đảng, hoàn tất việc thống nhất. Mốc khép lại dòng thời gian này không nằm ở năm 1930. Ba mươi năm sau, Đại hội đại biểu toàn quốc lần thứ III của Đảng năm 1960 quyết định lấy ngày 3/2 hằng năm làm ngày kỷ niệm thành lập Đảng. Nhìn từ đó, hành trình từ Quảng Châu qua đất Xiêm tới Cửu Long là chương mở đầu của lịch sử Đảng. Và hơn một năm làm ông Thầu Chín giữa kiều bào là trang chuẩn bị lặng lẽ nhưng không thể thiếu của chương ấy."},{"t":"Bạn có biết? Căn nhà số 5D phố Hàm Long, Hà Nội, nơi ra đời chi bộ cộng sản đầu tiên cuối tháng 3/1929, nay là di tích lịch sử, mở cửa đón khách tham quan."},{"t":"Sau năm 1930: những mốc của ký ức. Sau khi Người rời đi, các xóm Việt kiều ở đông bắc Xiêm tiếp tục là cơ sở của phong trào, là nơi nương náu của nhiều cán bộ cách mạng trong những năm khó khăn. Năm 1939, nước Xiêm đổi tên thành Thái Lan. Cộng đồng người Việt ở đây còn trải qua nhiều biến động, từ những đợt người Việt ở Lào lánh sang năm 1946 đến những chuyến tàu hồi hương đầu những năm 1960. Qua tất cả những biến động ấy, câu chuyện về ông Thầu Chín vẫn được các gia đình truyền lại cho con cháu. Ký ức ấy dần được tạc thành di tích. Ở Udon Thani, khu di tích với ngôi nhà phục dựng được hoàn thành năm 2002. Ở Bản Đông, tỉnh Phichit, một ngôi nhà sàn gỗ và tượng bán thân của Người đã được dựng lên. Ở Nakhon Phanom, khu tưởng niệm tại làng Nachok, bản Mạy, được khánh thành ngày 19/5/2016, đúng dịp kỷ niệm 126 năm ngày sinh của Người (xem chuyên đề “Nhà lưu niệm Hồ Chí Minh ở bản Mạy, Nakhon Phanom”)."},{"t":"Tên đất, tên người và những con số cần đọc kỹ. Khi đọc tư liệu về giai đoạn này, người xem nên lưu ý mấy điều. Trước hết là tên đất. Sách báo tiếng Việt thường phiên âm tên các tỉnh Thái theo nhiều cách: Udon Thani có khi viết là U Đon, Sakon Nakhon là Sa Côn, Phichit là Phi Chịt. Làng Nachok được kiều bào gọi là bản Mạy, còn tên “Thầu Chín” thường được giải thích là “ông già Chín”, dù khi ấy Người mới ba mươi tám tuổi. Thứ hai là những con số. Các tư liệu đôi khi ghi khác nhau về một sự kiện. Chẳng hạn, về khu tưởng niệm ở Nakhon Phanom, Bảo tàng Hồ Chí Minh ghi công trình khởi công tháng 6/2013, trong khi một bài báo năm 2016 ghi thời điểm khởi công là tháng 3/2014. Dòng thời gian của bảo tàng này ưu tiên các mốc có trong Hồ Chí Minh – Biên niên tiểu sử và các nguồn chính thống; mốc nào chưa có ngày chính xác thì chỉ ghi tháng hoặc năm, thay vì đoán định."}],"so_chu":1401},{"i":4,"tieu_de_bang":"Nhà lưu niệm Hồ Chí Minh ở bản Mạy, Nakhon Phanom","tieu_de":"Nhà lưu niệm ở bản Mạy: nơi ký ức về ông Thầu Chín được giữ bằng tình người","sapo":"Ở làng Nachok, mà người Việt quen gọi là bản Mạy, ngoại ô thành phố Nakhon Phanom, có một ngôi nhà gỗ nhỏ mà người Việt đến Thái Lan thường tìm về. Tấm ảnh này ghi lại mặt trước ngôi nhà ấy vào đầu tháng 3/2010. Đằng sau khung hình giản dị là gần một thế kỷ kiều bào và bạn bè Thái Lan chung tay giữ lại ký ức về những năm 1928 – 1929.","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_nakhonphanom_front.jpg","credit":"Ảnh: BacLuong · CC BY-SA 4.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Tấm ảnh và người chụp","text":"Theo thông tin lưu trên Wikimedia Commons, tấm ảnh được một người dùng có tên BacLuong chụp ngày 1/3/2010, và được chia sẻ theo giấy phép Creative Commons CC BY-SA 4.0, cho phép mọi người dùng lại khi ghi rõ nguồn. Khung hình ghi lại mặt trước nhà lưu niệm Hồ Chí Minh ở bản Mạy, làng Nachok, ngoại ô thành phố Nakhon Phanom, miền đông bắc Thái Lan. Cùng ngày, người chụp còn ghi lại hàng dừa trong khuôn viên khu lưu niệm, tấm ảnh được giới thiệu ở một chuyên đề khác trong gian này.\n\nGiá trị của tấm ảnh nằm ở thời điểm nó được chụp. Năm 2010, khu tưởng niệm rộng lớn hiện nay chưa được xây dựng. Nơi tưởng nhớ ông Thầu Chín khi ấy chỉ là một ngôi nhà nhỏ giữa khu vườn, do kiều bào địa phương chăm nom. Tấm ảnh vì thế là một chứng từ về chặng đường gìn giữ di tích: từ một ngôi nhà được dựng lại bằng tấm lòng của cộng đồng, trước khi nơi này trở thành một quần thể tưởng niệm có sự chung tay của cả hai nước.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_ho_chi_minh_nakhonphanom_front.jpg","chu_thich":"Mặt trước nhà lưu niệm Hồ Chí Minh ở bản Mạy (làng Nachok), Nakhon Phanom, Thái Lan, ảnh chụp ngày 1/3/2010. Ngôi nhà được dựng lại trên nền ngôi nhà ông Thầu Chín từng ở những năm 1928 – 1929. Ảnh: BacLuong, CC BY-SA 4.0, Wikimedia Commons.","credit":"Ảnh: BacLuong · CC BY-SA 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Bản Mạy, làng Nachok","text":"Nakhon Phanom là một tỉnh ở miền đông bắc Thái Lan, nằm bên bờ phải sông Mê Kông. Bên kia sông là thị xã Thà Khẹt thuộc tỉnh Khăm Muộn của nước Lào. Làng Nachok nằm ở ngoại ô thành phố tỉnh lỵ, và từ lâu đã là nơi sinh sống của nhiều gia đình người Việt. Kiều bào quen gọi nơi này là bản Mạy, nghĩa là “làng mới”.\n\nNăm 1929, từ khoảng cuối tháng 7 đến cuối tháng 10, Nguyễn Ái Quốc với tên gọi Thầu Chín hoạt động ở Nakhon Phanom. Theo Bảo tàng Hồ Chí Minh, bản Mạy là nơi Người ở lâu nhất trên đất Xiêm. Tại đây, Người gây dựng phong trào kiều bào, biến bản Mạy thành một trong những địa điểm quan trọng của Hội Việt Nam Cách mạng Thanh niên. Bảo tàng Hồ Chí Minh cũng cho biết bản Mạy còn lưu giữ những hiện vật, dấu tích của Người, trong đó có những gốc cây do chính tay Người trồng. Ngôi nhà trong tấm ảnh được dựng lại trên nền ngôi nhà ông Thầu Chín từng ở những năm ấy.","doc":2},{"loai":"doan","tieu_de":"Những tháng Người ở bản Mạy","text":"Ở bản Mạy, ông Thầu Chín sống như ở mọi xóm Việt kiều khác mà Người đã đi qua. Người cùng bà con làm ruộng, đào giếng, dựng nhà, trồng rau; tối đến dạy chữ quốc ngữ cho trẻ em và người lớn, viết bài cho báo Thân Ái, củng cố Hội Thân ái và Hội Hợp tác của kiều bào (xem chuyên đề “Lớp học đèn dầu và tờ báo Thân Ái”). Nhờ nếp sống giản dị ấy, Người được bà con tin cậy, còn mật thám thì khó lòng chú ý.\n\nVị trí của bản Mạy khiến nơi đây có ý nghĩa đặc biệt. Chỉ cần qua sông là tới đất Lào, rồi vượt Trường Sơn là về các tỉnh miền Trung Việt Nam. Theo con đường ấy, tài liệu được chuyển về nước và tin tức từ quê nhà được đưa sang. Cũng chính ở đây, những tin tức về sự chia rẽ của các tổ chức cộng sản trong nước đã khiến Người quyết định lên đường. Cuối tháng 10/1929 Người rời Nakhon Phanom, và tháng 11 năm ấy thì rời hẳn đất Xiêm (xem chuyên đề “Tin từ quê nhà và chuyến đi cuối năm 1929”).","doc":3},{"loai":"anh","src":"textures/bang_w/G10_4_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nhà lưu niệm Hồ Chí Minh ở bản Mạy, Nakhon Phanom”, nhìn từ xa."},{"loai":"doan","tieu_de":"Ai đã giữ ký ức này?","text":"Ký ức về ông Thầu Chín trước hết được giữ trong chính cộng đồng người Việt ở Nakhon Phanom. Những gia đình từng sống ở đây qua nhiều thế hệ đã truyền cho con cháu câu chuyện về “ông già Chín” năm nào: người cùng đi làm đồng, cùng đào giếng, tối đến dạy chữ cho trẻ con trong xóm. Dần dần, câu chuyện ấy trở thành một phần lai lịch của cả cộng đồng, được kể lại như người ta kể về ông bà tổ tiên.\n\nCộng đồng ấy lớn lên qua những biến động của thế kỷ XX. Tháng 3/1946, khi quân Pháp đánh chiếm Thà Khẹt ở bên kia sông, hàng nghìn người Việt ở Lào đã vượt Mê Kông sang Nakhon Phanom lánh nạn, làm cộng đồng người Việt ở đây đông thêm. Những thế hệ sau dần mang quốc tịch Thái, hòa nhập vào đời sống địa phương. Nhưng nhiều gia đình vẫn giữ tiếng Việt, giữ ngày giỗ, ngày Tết, và cùng nhau chăm nom ngôi nhà nhỏ ở bản Mạy như chăm nom một nơi thờ tự của chính mình.","doc":4},{"loai":"ban_co_biet","text":"Từ năm 1960 đến năm 1964, theo thỏa thuận giữa Hội Chữ thập đỏ hai nước, hàng vạn Việt kiều ở Thái Lan đã về nước theo các chuyến tàu hồi hương. Nhiều gia đình khác ở lại, tiếp tục gìn giữ những di tích gắn với Bác ở Nakhon Phanom và Udon Thani.","nguon_ten":"Bảo tàng Hồ Chí Minh; Ủy ban Nhà nước về người Việt Nam ở nước ngoài","doc":5},{"loai":"doan","tieu_de":"Ngôi nhà nhỏ trước khi có khu tưởng niệm","text":"Năm 2010, khi tấm ảnh được chụp, nhà lưu niệm vẫn là một công trình khiêm tốn. Ngôi nhà gỗ đơn sơ ngày trước đã được dựng lại trên nền cũ theo dáng nhà xưa, cùng khu vườn và giếng nước xung quanh. Không có quảng trường, không có những hạng mục lớn, chỉ có ngôi nhà, khu vườn và sự chăm sóc của kiều bào. Về kiến trúc và đồ đạc bên trong ngôi nhà, xin xem chuyên đề “Ngôi nhà Người từng ở tại Nakhon Phanom, phục dựng”.\n\nSự khiêm tốn ấy lại rất hợp với người từng sống ở đây. Ông Thầu Chín đến bản Mạy không phải với tư cách một lãnh tụ, mà như một người lao động giữa những người lao động. Một ngôi nhà nhỏ giữa vườn cây, được giữ gìn bằng công sức của những người dân bình thường, là cách tưởng nhớ rất gần với tinh thần của Người. Từ trước khi có khu tưởng niệm mới, nơi đây đã là địa chỉ quen thuộc của nhiều đoàn khách từ Việt Nam và của chính người dân Thái trong vùng.","doc":6},{"loai":"doan","tieu_de":"Khu tưởng niệm năm 2016","text":"Những năm 2010, nhu cầu mở rộng nơi tưởng niệm ngày càng rõ. Theo Bảo tàng Hồ Chí Minh, khu tưởng niệm Chủ tịch Hồ Chí Minh tại làng Nachok được khởi công vào tháng 6/2013, với sự quan tâm, hỗ trợ của Tổng Bí thư Nguyễn Phú Trọng. Phía Thái Lan dành khoảng 1,2 héc-ta đất cho công trình. Ngày 19/5/2016, nhân kỷ niệm 126 năm ngày sinh của Người, khu tưởng niệm được khánh thành.\n\nTheo báo Nhân Dân, khu tưởng niệm gồm khoảng mười hai hạng mục trên diện tích khoảng 12.000 mét vuông. Bảo tàng Hồ Chí Minh cho biết trong khu có điện thờ Chủ tịch Hồ Chí Minh và ngôi nhà di tích mô phỏng, được kết nối với Làng hữu nghị Thái – Việt ở bên cạnh. Từ một ngôi nhà nhỏ như trong tấm ảnh năm 2010, nơi tưởng nhớ ông Thầu Chín đã trở thành một quần thể lớn, đủ sức đón những đoàn khách đông người của cả hai nước. Nhưng hạt nhân của nó vẫn là câu chuyện giản dị về một người đã sống, lao động và dạy chữ giữa bà con.","doc":7},{"loai":"ban_co_biet","text":"Nakhon Phanom không phải nơi duy nhất ở Thái Lan tưởng niệm Người. Khu di tích ở Udon Thani, với ngôi nhà phục dựng, được hoàn thành năm 2002. Ở Phichit, một ngôi nhà sàn gỗ và tượng bán thân của Người đã được dựng lên; khu này được quy hoạch rộng khoảng 4.000 mét vuông, kinh phí dự kiến khoảng 14 triệu baht.","nguon_ten":"Báo Nhân Dân, “Hình bóng Bác mãi in đậm ở Thái Lan”, 19/5/2016","doc":8},{"loai":"doan","tieu_de":"Một biểu tượng của tình hữu nghị","text":"Với người Việt, nhà lưu niệm ở bản Mạy nhắc lại những năm tháng Nguyễn Ái Quốc bôn ba tìm đường cứu nước, sống bằng lao động của chính mình giữa đồng bào nghèo nơi đất khách. Với người Thái, đây là chứng tích của một quá khứ chung. Vùng đông bắc Thái Lan từng che chở những người Việt yêu nước, và cộng đồng người Việt ở đây đã trở thành một phần của đời sống địa phương.\n\nVì thế, việc phía Thái Lan dành đất, cùng kiều bào và phía Việt Nam xây dựng khu tưởng niệm, được xem như một biểu tượng của tình hữu nghị giữa hai dân tộc. Làng hữu nghị Thái – Việt đặt cạnh khu tưởng niệm cũng mang ý nghĩa ấy. Các đoàn khách của hai nước khi tới Nakhon Phanom thường tìm đến nơi này. Một ngôi nhà gỗ nhỏ, từng là chỗ ở của một người Việt yêu nước sống lẫn giữa bà con nghèo, nay trở thành điểm hẹn của hai dân tộc láng giềng bên dòng Mê Kông.","doc":9},{"loai":"anh","src":"textures/bang_w/G10_4_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nhà lưu niệm Hồ Chí Minh ở bản Mạy, Nakhon Phanom”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, khách đến bản Mạy có thể thăm ngôi nhà gỗ phục dựng theo dáng nhà ông Thầu Chín từng ở. Trong khu tưởng niệm còn có điện thờ Chủ tịch Hồ Chí Minh, và khu vườn với hàng dừa, cây ăn trái. Trong khuôn viên còn một chiếc giếng nhỏ, tương truyền do ông Thầu Chín cùng bà con đào để lấy nước sinh hoạt; giếng được giữ nguyên vị trí như một phần của di tích. Những gốc cây mà theo Bảo tàng Hồ Chí Minh do chính tay Người trồng cũng là một điểm dừng chân của khách.\n\nNối những điểm tưởng niệm ở Phichit, Udon Thani và Nakhon Phanom lại, người ta có thể đi lại con đường mà ông Thầu Chín từng đi bộ gần một thế kỷ trước. Chỉ khác là nay người ta đi bằng ô tô trên những con đường nhựa. Trong gian trưng bày này, tấm ảnh năm 2010 là cầu nối giữa hai thời điểm: một bên là nếp nhà năm 1929 được dựng lại trong không gian 3D, một bên là nơi ký ức ấy vẫn đang được gìn giữ ở bản Mạy hôm nay.","doc":10},{"loai":"anh","src":"textures/bang_w/G10_4_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nhà lưu niệm Hồ Chí Minh ở bản Mạy, Nakhon Phanom”, nhìn từ trên cao."}],"nguon":["Bảo tàng Hồ Chí Minh – Khu tưởng niệm Chủ tịch Hồ Chí Minh tại làng Nachok (bản Mạy), tỉnh Nakhon Phanom, Thái Lan (2019): https://baotanghochiminh.vn/khu-tuong-niem-chu-tich-ho-chi-minh-tai-lang-nachok-ban-may-tinh-nakhon-phanom-thai-lan.htm","Báo Nhân Dân – Hình bóng Bác mãi in đậm ở Thái Lan (19/5/2016): https://nhandan.vn/hinh-bong-bac-mai-in-dam-o-thai-lan-post263450.html","Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","Ủy ban Nhà nước về người Việt Nam ở nước ngoài","Wikimedia Commons – ảnh nhà lưu niệm Hồ Chí Minh ở Nakhon Phanom của BacLuong (1/3/2010), giấy phép CC BY-SA 4.0"],"doc":[{"t":"Nhà lưu niệm ở bản Mạy: nơi ký ức về ông Thầu Chín được giữ bằng tình người. Ở làng Nachok, mà người Việt quen gọi là bản Mạy, ngoại ô thành phố Nakhon Phanom, có một ngôi nhà gỗ nhỏ mà người Việt đến Thái Lan thường tìm về. Tấm ảnh này ghi lại mặt trước ngôi nhà ấy vào đầu tháng 3/2010. Đằng sau khung hình giản dị là gần một thế kỷ kiều bào và bạn bè Thái Lan chung tay giữ lại ký ức về những năm 1928 – 1929."},{"t":"Tấm ảnh và người chụp. Theo thông tin lưu trên Wikimedia Commons, tấm ảnh được một người dùng có tên BacLuong chụp ngày 1/3/2010, và được chia sẻ theo giấy phép Creative Commons CC BY-SA 4.0, cho phép mọi người dùng lại khi ghi rõ nguồn. Khung hình ghi lại mặt trước nhà lưu niệm Hồ Chí Minh ở bản Mạy, làng Nachok, ngoại ô thành phố Nakhon Phanom, miền đông bắc Thái Lan. Cùng ngày, người chụp còn ghi lại hàng dừa trong khuôn viên khu lưu niệm, tấm ảnh được giới thiệu ở một chuyên đề khác trong gian này. Giá trị của tấm ảnh nằm ở thời điểm nó được chụp. Năm 2010, khu tưởng niệm rộng lớn hiện nay chưa được xây dựng. Nơi tưởng nhớ ông Thầu Chín khi ấy chỉ là một ngôi nhà nhỏ giữa khu vườn, do kiều bào địa phương chăm nom. Tấm ảnh vì thế là một chứng từ về chặng đường gìn giữ di tích: từ một ngôi nhà được dựng lại bằng tấm lòng của cộng đồng, trước khi nơi này trở thành một quần thể tưởng niệm có sự chung tay của cả hai nước."},{"t":"Bản Mạy, làng Nachok. Nakhon Phanom là một tỉnh ở miền đông bắc Thái Lan, nằm bên bờ phải sông Mê Kông. Bên kia sông là thị xã Thà Khẹt thuộc tỉnh Khăm Muộn của nước Lào. Làng Nachok nằm ở ngoại ô thành phố tỉnh lỵ, và từ lâu đã là nơi sinh sống của nhiều gia đình người Việt. Kiều bào quen gọi nơi này là bản Mạy, nghĩa là “làng mới”. Năm 1929, từ khoảng cuối tháng 7 đến cuối tháng 10, Nguyễn Ái Quốc với tên gọi Thầu Chín hoạt động ở Nakhon Phanom. Theo Bảo tàng Hồ Chí Minh, bản Mạy là nơi Người ở lâu nhất trên đất Xiêm. Tại đây, Người gây dựng phong trào kiều bào, biến bản Mạy thành một trong những địa điểm quan trọng của Hội Việt Nam Cách mạng Thanh niên. Bảo tàng Hồ Chí Minh cũng cho biết bản Mạy còn lưu giữ những hiện vật, dấu tích của Người, trong đó có những gốc cây do chính tay Người trồng. Ngôi nhà trong tấm ảnh được dựng lại trên nền ngôi nhà ông Thầu Chín từng ở những năm ấy."},{"t":"Những tháng Người ở bản Mạy. Ở bản Mạy, ông Thầu Chín sống như ở mọi xóm Việt kiều khác mà Người đã đi qua. Người cùng bà con làm ruộng, đào giếng, dựng nhà, trồng rau; tối đến dạy chữ quốc ngữ cho trẻ em và người lớn, viết bài cho báo Thân Ái, củng cố Hội Thân ái và Hội Hợp tác của kiều bào (xem chuyên đề “Lớp học đèn dầu và tờ báo Thân Ái”). Nhờ nếp sống giản dị ấy, Người được bà con tin cậy, còn mật thám thì khó lòng chú ý. Vị trí của bản Mạy khiến nơi đây có ý nghĩa đặc biệt. Chỉ cần qua sông là tới đất Lào, rồi vượt Trường Sơn là về các tỉnh miền Trung Việt Nam. Theo con đường ấy, tài liệu được chuyển về nước và tin tức từ quê nhà được đưa sang. Cũng chính ở đây, những tin tức về sự chia rẽ của các tổ chức cộng sản trong nước đã khiến Người quyết định lên đường. Cuối tháng 10/1929 Người rời Nakhon Phanom, và tháng 11 năm ấy thì rời hẳn đất Xiêm (xem chuyên đề “Tin từ quê nhà và chuyến đi cuối năm 1929”)."},{"t":"Ai đã giữ ký ức này?. Ký ức về ông Thầu Chín trước hết được giữ trong chính cộng đồng người Việt ở Nakhon Phanom. Những gia đình từng sống ở đây qua nhiều thế hệ đã truyền cho con cháu câu chuyện về “ông già Chín” năm nào: người cùng đi làm đồng, cùng đào giếng, tối đến dạy chữ cho trẻ con trong xóm. Dần dần, câu chuyện ấy trở thành một phần lai lịch của cả cộng đồng, được kể lại như người ta kể về ông bà tổ tiên. Cộng đồng ấy lớn lên qua những biến động của thế kỷ XX. Tháng 3/1946, khi quân Pháp đánh chiếm Thà Khẹt ở bên kia sông, hàng nghìn người Việt ở Lào đã vượt Mê Kông sang Nakhon Phanom lánh nạn, làm cộng đồng người Việt ở đây đông thêm. Những thế hệ sau dần mang quốc tịch Thái, hòa nhập vào đời sống địa phương. Nhưng nhiều gia đình vẫn giữ tiếng Việt, giữ ngày giỗ, ngày Tết, và cùng nhau chăm nom ngôi nhà nhỏ ở bản Mạy như chăm nom một nơi thờ tự của chính mình."},{"t":"Bạn có biết? Từ năm 1960 đến năm 1964, theo thỏa thuận giữa Hội Chữ thập đỏ hai nước, hàng vạn Việt kiều ở Thái Lan đã về nước theo các chuyến tàu hồi hương. Nhiều gia đình khác ở lại, tiếp tục gìn giữ những di tích gắn với Bác ở Nakhon Phanom và Udon Thani."},{"t":"Ngôi nhà nhỏ trước khi có khu tưởng niệm. Năm 2010, khi tấm ảnh được chụp, nhà lưu niệm vẫn là một công trình khiêm tốn. Ngôi nhà gỗ đơn sơ ngày trước đã được dựng lại trên nền cũ theo dáng nhà xưa, cùng khu vườn và giếng nước xung quanh. Không có quảng trường, không có những hạng mục lớn, chỉ có ngôi nhà, khu vườn và sự chăm sóc của kiều bào. Về kiến trúc và đồ đạc bên trong ngôi nhà, xin xem chuyên đề “Ngôi nhà Người từng ở tại Nakhon Phanom, phục dựng”. Sự khiêm tốn ấy lại rất hợp với người từng sống ở đây. Ông Thầu Chín đến bản Mạy không phải với tư cách một lãnh tụ, mà như một người lao động giữa những người lao động. Một ngôi nhà nhỏ giữa vườn cây, được giữ gìn bằng công sức của những người dân bình thường, là cách tưởng nhớ rất gần với tinh thần của Người. Từ trước khi có khu tưởng niệm mới, nơi đây đã là địa chỉ quen thuộc của nhiều đoàn khách từ Việt Nam và của chính người dân Thái trong vùng."},{"t":"Khu tưởng niệm năm 2016. Những năm 2010, nhu cầu mở rộng nơi tưởng niệm ngày càng rõ. Theo Bảo tàng Hồ Chí Minh, khu tưởng niệm Chủ tịch Hồ Chí Minh tại làng Nachok được khởi công vào tháng 6/2013, với sự quan tâm, hỗ trợ của Tổng Bí thư Nguyễn Phú Trọng. Phía Thái Lan dành khoảng 1,2 héc-ta đất cho công trình. Ngày 19/5/2016, nhân kỷ niệm 126 năm ngày sinh của Người, khu tưởng niệm được khánh thành. Theo báo Nhân Dân, khu tưởng niệm gồm khoảng mười hai hạng mục trên diện tích khoảng 12.000 mét vuông. Bảo tàng Hồ Chí Minh cho biết trong khu có điện thờ Chủ tịch Hồ Chí Minh và ngôi nhà di tích mô phỏng, được kết nối với Làng hữu nghị Thái – Việt ở bên cạnh. Từ một ngôi nhà nhỏ như trong tấm ảnh năm 2010, nơi tưởng nhớ ông Thầu Chín đã trở thành một quần thể lớn, đủ sức đón những đoàn khách đông người của cả hai nước. Nhưng hạt nhân của nó vẫn là câu chuyện giản dị về một người đã sống, lao động và dạy chữ giữa bà con."},{"t":"Bạn có biết? Nakhon Phanom không phải nơi duy nhất ở Thái Lan tưởng niệm Người. Khu di tích ở Udon Thani, với ngôi nhà phục dựng, được hoàn thành năm 2002. Ở Phichit, một ngôi nhà sàn gỗ và tượng bán thân của Người đã được dựng lên; khu này được quy hoạch rộng khoảng 4.000 mét vuông, kinh phí dự kiến khoảng 14 triệu baht."},{"t":"Một biểu tượng của tình hữu nghị. Với người Việt, nhà lưu niệm ở bản Mạy nhắc lại những năm tháng Nguyễn Ái Quốc bôn ba tìm đường cứu nước, sống bằng lao động của chính mình giữa đồng bào nghèo nơi đất khách. Với người Thái, đây là chứng tích của một quá khứ chung. Vùng đông bắc Thái Lan từng che chở những người Việt yêu nước, và cộng đồng người Việt ở đây đã trở thành một phần của đời sống địa phương. Vì thế, việc phía Thái Lan dành đất, cùng kiều bào và phía Việt Nam xây dựng khu tưởng niệm, được xem như một biểu tượng của tình hữu nghị giữa hai dân tộc. Làng hữu nghị Thái – Việt đặt cạnh khu tưởng niệm cũng mang ý nghĩa ấy. Các đoàn khách của hai nước khi tới Nakhon Phanom thường tìm đến nơi này. Một ngôi nhà gỗ nhỏ, từng là chỗ ở của một người Việt yêu nước sống lẫn giữa bà con nghèo, nay trở thành điểm hẹn của hai dân tộc láng giềng bên dòng Mê Kông."},{"t":"Dấu tích hôm nay. Ngày nay, khách đến bản Mạy có thể thăm ngôi nhà gỗ phục dựng theo dáng nhà ông Thầu Chín từng ở. Trong khu tưởng niệm còn có điện thờ Chủ tịch Hồ Chí Minh, và khu vườn với hàng dừa, cây ăn trái. Trong khuôn viên còn một chiếc giếng nhỏ, tương truyền do ông Thầu Chín cùng bà con đào để lấy nước sinh hoạt; giếng được giữ nguyên vị trí như một phần của di tích. Những gốc cây mà theo Bảo tàng Hồ Chí Minh do chính tay Người trồng cũng là một điểm dừng chân của khách. Nối những điểm tưởng niệm ở Phichit, Udon Thani và Nakhon Phanom lại, người ta có thể đi lại con đường mà ông Thầu Chín từng đi bộ gần một thế kỷ trước. Chỉ khác là nay người ta đi bằng ô tô trên những con đường nhựa. Trong gian trưng bày này, tấm ảnh năm 2010 là cầu nối giữa hai thời điểm: một bên là nếp nhà năm 1929 được dựng lại trong không gian 3D, một bên là nơi ký ức ấy vẫn đang được gìn giữ ở bản Mạy hôm nay."}],"so_chu":1725},{"i":5,"tieu_de_bang":"Ngôi nhà Người từng ở tại Nakhon Phanom, phục dựng","tieu_de":"Ngôi nhà ba gian ở bản Mạy: dáng nhà miền Trung bên bờ Mê Kông","sapo":"Giữa vùng đất của những nếp nhà sàn Isan, có một ngôi nhà gỗ trông như vừa được mang sang từ một làng quê xứ Nghệ: ba gian, hai hồi, vách thưng ván, trước hiên buông tấm rèm tre đan. Đó là ngôi nhà ở bản Mạy, ngoại ô Nakhon Phanom, nơi ông Thầu Chín từng sống. Ngôi nhà hôm nay đã được dựng lại, và chính việc dựng lại ấy cũng là một câu chuyện đáng kể.","bia":{"src":"textures/ht/ht_anh_house_hochiminh_stayed_nakhonphanom.jpg","credit":"Ảnh: BacLuong at Vietnamese Wikipedia · CC BY 4.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Một ngôi nhà không giống láng giềng","text":"Người đến bản Mạy lần đầu thường ngạc nhiên vì một điều rất giản dị. Chung quanh là đồng lúa và những nếp nhà sàn gỗ quen thuộc của xứ Isan, sàn cao, gầm rộng. Vậy mà giữa khu vườn nhỏ lại có một ngôi nhà mang dáng dấp rất Việt: ba gian, hai hồi, vách thưng ván, cửa gỗ, mặt bằng gần vuông, mái lợp ngói. Phía trước hiên buông một tấm rèm đan bằng tre, đúng kiểu nhà ở miền Trung Việt Nam. Đây là ngôi nhà ông Thầu Chín từng ở, nay đã được phục dựng.\n\nBản Mạy là cách gọi quen thuộc của kiều bào; trên bản đồ Thái Lan, nơi này là bản Na Chok, cách trung tâm thành phố Nakhon Phanom chừng năm cây số. Theo Báo Thanh Niên, khuôn viên khu nhà rộng khoảng 1.500 mét vuông, có vườn cây và giếng nước bao quanh. Tấm ảnh tư liệu trong gian này, do tác giả BacLuong đưa lên Wikipedia tiếng Việt, ghi lại chính ngôi nhà ấy sau khi được dựng lại theo dáng xưa.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_house_hochiminh_stayed_nakhonphanom.jpg","chu_thich":"Ngôi nhà ông Thầu Chín từng ở tại bản Mạy (Na Chok), ngoại ô Nakhon Phanom, sau khi được phục dựng theo dáng nhà xưa. Ảnh: BacLuong, Wikipedia tiếng Việt, giấy phép CC BY 4.0.","credit":"Ảnh: BacLuong at Vietnamese Wikipedia · CC BY 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Người xứ Nghệ mang nếp nhà sang đất Xiêm","text":"Vì sao một ngôi nhà ở đông bắc Thái Lan lại giống nhà ở Nghệ An, Hà Tĩnh đến thế? Câu trả lời nằm trong lịch sử của chính cộng đồng người Việt nơi đây. Từ cuối thế kỷ XIX, nhiều lớp người Việt đã rời quê sang Xiêm. Có người lánh nạn sau khi phong trào Cần Vương thất bại, có người theo phong trào Đông Du của Phan Bội Châu, có người chỉ vì nghèo đói mà tha hương. Không ít người trong số họ quê ở các tỉnh miền Trung.\n\nGia đình họ Võ, những người đã che chở ông Thầu Chín ở bản Mạy và đến nay vẫn trông nom ngôi nhà, có gốc gác ở vùng Hưng Nguyên, tỉnh Nghệ An. Sang đất người, họ dựng nhà theo cách cha ông vẫn dựng: chia gian, làm hồi, thưng ván, treo rèm tre như ở làng cũ. Ngôi nhà ba gian vì thế vừa là chỗ ở, vừa là một cách giữ quê hương. Đứng trước nó, người xứ Nghệ xa nhà có thể nhớ về mái nhà nơi mình sinh ra.","doc":2},{"loai":"ban_co_biet","text":"Tấm rèm tre trước hiên là vật quen thuộc của nhà ở Nghệ An, Hà Tĩnh, dùng để che nắng và che những đợt gió tây nam khô nóng mà người miền Trung gọi là gió Lào. Luồng gió ấy vượt dãy Trường Sơn từ phía đất Lào, tức là từ phía dòng Mê Kông chảy qua Nakhon Phanom.","nguon_ten":"Báo Hà Tĩnh (mô tả rèm tre kiểu nhà Trung Bộ); Địa lí 12, NXB Giáo dục Việt Nam (gió phơn tây nam)","doc":3},{"loai":"doan","tieu_de":"Ba gian, hai hồi: đọc một nếp nhà","text":"Nhà ba gian hai hồi là kiểu nhà phổ biến của nông dân miền Trung và miền Bắc thời trước. Gian giữa thường đặt bàn thờ tổ tiên và là nơi tiếp khách. Hai gian bên là chỗ ngủ, chỗ cất thóc lúa, nông cụ. Hai đầu hồi khép kín, giữ cho nhà đỡ lạnh khi gió mùa và đỡ nóng khi nắng gắt. Mái thấp, hiên nông, cửa gỗ đóng mở cả mảng, hợp với khí hậu nhiều nắng gió.\n\nSo với nhà sàn Isan cao ráo, gầm thoáng, nếp nhà của người Việt thấp và kín đáo hơn, quay mặt ra sân, ra vườn. Một ngôi nhà như thế không đòi hỏi vật liệu đắt tiền: gỗ, tre, lá lợp đều có thể kiếm quanh vùng. Bà con nghèo có thể góp công giúp nhau dựng nhà, nay nhà này, mai nhà khác. Ông Thầu Chín cũng từng cùng kiều bào dựng nhà như vậy. Bởi thế, ngôi nhà ở bản Mạy không phải một công trình riêng dành cho một nhân vật đặc biệt, mà là một mái nhà bình thường giữa những mái nhà bình thường của xóm.","doc":4},{"loai":"anh","src":"textures/bang_w/G10_5_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Ngôi nhà Người từng ở tại Nakhon Phanom, phục dựng”, nhìn từ xa."},{"loai":"doan","tieu_de":"Mối mọt, mưa nắng và việc dựng lại","text":"Gỗ và tre là vật liệu gần gũi, nhưng không bền trước khí hậu nhiệt đới. Mùa mưa ẩm ướt, mùa khô nắng gắt, và nhất là mối mọt, đã dần làm hư hại ngôi nhà cũ. Theo Báo Thanh Niên, ngôi nhà hiện nay được dựng lại vì nhà xưa đã bị mối mọt và thời gian tàn phá, nhưng vẫn giữ kiểu dáng ban đầu.\n\nPhục dựng một di tích như vậy luôn là bài toán khó. Ngôi nhà phải đứng vững trước mưa nắng, mà vẫn không được mất đi vẻ mộc mạc của một mái nhà nông dân. Ngôi nhà được dựng lại vẫn giữ đúng quy mô ba gian, giữ vách ván, cửa gỗ và tấm rèm tre, không biến thành một công trình bề thế. Chính sự khiêm nhường ấy làm nên giá trị của nó. Giá trị của ngôi nhà không nằm ở gỗ quý hay chạm trổ, mà ở chỗ nó đúng là kiểu nhà của những người lao động mà ông Thầu Chín đã chọn sống cùng. Câu chuyện về những người bền bỉ gìn giữ khu lưu niệm được kể kỹ hơn ở chuyên đề về nhà lưu niệm ở bản Mạy.","doc":5},{"loai":"doan","tieu_de":"Bên trong ba gian nhà","text":"Bước qua tấm rèm tre, khách gặp một không gian mộc mạc. Theo Báo Hà Tĩnh, trong nhà bày bộ bàn ghế được giới thiệu là nơi Bác ngồi làm việc, cùng những nông cụ và đồ dùng quen thuộc: mũ, dao, rựa, cuốc, cào, chum vại đựng nước. Trên vách treo nhiều tranh ảnh về Bác qua các thời kỳ.\n\nNên hiểu rằng phần lớn đồ vật ở đây là đồ dùng thường ngày của một gia đình nông dân Việt kiều, được bày để gợi lại nếp sinh hoạt năm xưa, chứ không nhất thiết là vật Người đã trực tiếp dùng. Dù vậy, chính sự bình thường của chúng lại nói lên nhiều điều. Một chiếc rựa để phát cỏ, một chiếc cuốc để vỡ đất, một vại nước đầy bên cửa. Đó là những thứ gắn với công việc hằng ngày mà ông Thầu Chín đã làm cùng bà con: làm ruộng, đào giếng, dựng nhà, trồng rau. Trong gian trưng bày của bảo tàng, những đồ vật tương tự cũng được đặt quanh ngôi nhà gỗ, và mỗi món đều mang một câu chuyện riêng để khách bấm vào tìm hiểu.","doc":6},{"loai":"anh","src":"textures/bang_w/G10_5_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Ngôi nhà Người từng ở tại Nakhon Phanom, phục dựng”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Bản Mạy trong hành trình của ông Thầu Chín","text":"Bản Mạy không phải chặng dừng chân đầu tiên của ông Thầu Chín trên đất Xiêm. Người đã qua Phichit, Udon Thani, Sakon Nakhon, rồi mới tới vùng ven sông ở Nakhon Phanom. Nhưng đây là nơi có vị trí đặc biệt. Chỉ cách một dòng Mê Kông là đất Lào, và qua Lào là đường về các tỉnh miền Trung Việt Nam.\n\nỞ một nơi như thế, ngôi nhà nhỏ giữa vườn vừa là chỗ ăn, chỗ ngủ, vừa là nơi gặp gỡ bà con, nơi tin tức từ quê nhà truyền đến. Theo lời kể mà gia đình họ Võ lưu giữ, được báo chí ghi lại, ông Thầu Chín sống trong xóm như một người nông dân thực thụ. Không ai trong xóm lạ gì hình ảnh ông già đội nón, đi dép, cặm cụi với mảnh vườn. Chính vẻ bình thường ấy giúp Người tránh được con mắt dò xét của mật thám Pháp, vốn có tai mắt cả trên đất Xiêm. Về nếp sống hằng ngày dưới mái nhà này, xem thêm chuyên đề Ngôi nhà của Thầu Chín.","doc":7},{"loai":"ban_co_biet","text":"Theo Báo Hà Tĩnh, người trông coi ngôi nhà hiện nay là ông Võ Trọng Minh, cháu nội cụ Võ Trọng Đại, người Việt kiều đã che chở ông Thầu Chín ở bản Mạy. Việc gìn giữ di tích vì thế đã được truyền qua nhiều thế hệ trong cùng một gia đình.","nguon_ten":"Báo Hà Tĩnh, “Thăm Khu lưu niệm Bác Hồ tại Nakhon Phanom” – https://baohatinh.vn/tham-khu-luu-niem-bac-ho-tai-nakhon-phanom-post133994.html","doc":8},{"loai":"doan","tieu_de":"Từ ngôi nhà ba gian đến nhà sàn Hà Nội","text":"Nhìn lại cả cuộc đời Hồ Chí Minh, ngôi nhà ở bản Mạy nằm trong một chuỗi những nơi ở giản dị đến lạ lùng. Thuở nhỏ là những mái nhà tranh ở quê ngoại Hoàng Trù và quê nội làng Sen. Những năm bôn ba ở Pháp là căn phòng thuê chật hẹp trong ngõ Compoint, Paris, rồi đến mái nhà nông dân Việt kiều ở Xiêm. Năm 1941, trở về Tổ quốc, Người ở hang Cốc Bó, Pác Bó. Tháng 5/1945, Người lên Tân Trào, ở trong lán Nà Lừa dựng bằng tre nứa.\n\nKhi đã là Chủ tịch nước, từ tháng 5/1958, Người sống trong ngôi nhà sàn gỗ nhỏ bên ao cá trong khu Phủ Chủ tịch. Tầng trên nhà sàn chỉ có hai phòng, mỗi phòng rộng khoảng mười mét vuông. Những nơi ở ấy giống nhau đến lạ: đủ để làm việc, nghỉ ngơi, và luôn gần gũi với mọi người. Ngôi nhà ba gian ở bản Mạy là một trong những mắt xích sớm nhất của phong cách sống nhất quán ấy.","doc":9},{"loai":"anh","src":"textures/bang_w/G10_5_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Ngôi nhà Người từng ở tại Nakhon Phanom, phục dựng”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, ngôi nhà ba gian nằm giữa một khu tưởng niệm đã được mở rộng. Theo Báo Hà Tĩnh, bên cạnh ngôi nhà cũ còn có nhà tưởng niệm xây theo kiến trúc Việt, các khu trưng bày, hồ nước trồng sen và núi đá nhân tạo. Dù vậy, ngôi nhà nhỏ vẫn là trái tim của cả khu.\n\nKhách đến thăm có thể bước lên hiên, nhìn qua tấm rèm tre vào ba gian nhà, xem bộ bàn ghế, những nông cụ và tranh ảnh, rồi ra vườn đứng bên giếng nước và hàng dừa. Nơi đây là địa chỉ quen thuộc của các đoàn khách từ Việt Nam, của kiều bào và của chính người dân Thái. Có người đến để tìm lại một trang sử, có người đến để hiểu vì sao một người đàn ông từng sống giữa làng mình gần một thế kỷ trước lại được cả một dân tộc kính yêu. Trong gian trưng bày của bảo tàng, ngôi nhà gỗ được dựng lại theo cùng tinh thần ấy: mộc mạc, gần gũi, để khách hình dung một nếp sống hơn là chiêm ngưỡng một công trình.","doc":10}],"nguon":["Báo Hà Tĩnh, “Thăm Khu lưu niệm Bác Hồ tại Nakhon Phanom” – https://baohatinh.vn/tham-khu-luu-niem-bac-ho-tai-nakhon-phanom-post133994.html","Báo Thanh Niên, “Nhà của Bác Hồ ở Thái Lan – di tích thú vị không phải ai cũng biết” – https://thanhnien.vn/nha-cua-bac-ho-o-thai-lan-di-tich-thu-vi-khong-phai-ai-cung-biet-1851505845.htm","Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","Bảo tàng Hồ Chí Minh","Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch (nhà sàn, từ tháng 5/1958)"],"doc":[{"t":"Ngôi nhà ba gian ở bản Mạy: dáng nhà miền Trung bên bờ Mê Kông. Giữa vùng đất của những nếp nhà sàn Isan, có một ngôi nhà gỗ trông như vừa được mang sang từ một làng quê xứ Nghệ: ba gian, hai hồi, vách thưng ván, trước hiên buông tấm rèm tre đan. Đó là ngôi nhà ở bản Mạy, ngoại ô Nakhon Phanom, nơi ông Thầu Chín từng sống. Ngôi nhà hôm nay đã được dựng lại, và chính việc dựng lại ấy cũng là một câu chuyện đáng kể."},{"t":"Một ngôi nhà không giống láng giềng. Người đến bản Mạy lần đầu thường ngạc nhiên vì một điều rất giản dị. Chung quanh là đồng lúa và những nếp nhà sàn gỗ quen thuộc của xứ Isan, sàn cao, gầm rộng. Vậy mà giữa khu vườn nhỏ lại có một ngôi nhà mang dáng dấp rất Việt: ba gian, hai hồi, vách thưng ván, cửa gỗ, mặt bằng gần vuông, mái lợp ngói. Phía trước hiên buông một tấm rèm đan bằng tre, đúng kiểu nhà ở miền Trung Việt Nam. Đây là ngôi nhà ông Thầu Chín từng ở, nay đã được phục dựng. Bản Mạy là cách gọi quen thuộc của kiều bào; trên bản đồ Thái Lan, nơi này là bản Na Chok, cách trung tâm thành phố Nakhon Phanom chừng năm cây số. Theo Báo Thanh Niên, khuôn viên khu nhà rộng khoảng 1.500 mét vuông, có vườn cây và giếng nước bao quanh. Tấm ảnh tư liệu trong gian này, do tác giả BacLuong đưa lên Wikipedia tiếng Việt, ghi lại chính ngôi nhà ấy sau khi được dựng lại theo dáng xưa."},{"t":"Người xứ Nghệ mang nếp nhà sang đất Xiêm. Vì sao một ngôi nhà ở đông bắc Thái Lan lại giống nhà ở Nghệ An, Hà Tĩnh đến thế? Câu trả lời nằm trong lịch sử của chính cộng đồng người Việt nơi đây. Từ cuối thế kỷ XIX, nhiều lớp người Việt đã rời quê sang Xiêm. Có người lánh nạn sau khi phong trào Cần Vương thất bại, có người theo phong trào Đông Du của Phan Bội Châu, có người chỉ vì nghèo đói mà tha hương. Không ít người trong số họ quê ở các tỉnh miền Trung. Gia đình họ Võ, những người đã che chở ông Thầu Chín ở bản Mạy và đến nay vẫn trông nom ngôi nhà, có gốc gác ở vùng Hưng Nguyên, tỉnh Nghệ An. Sang đất người, họ dựng nhà theo cách cha ông vẫn dựng: chia gian, làm hồi, thưng ván, treo rèm tre như ở làng cũ. Ngôi nhà ba gian vì thế vừa là chỗ ở, vừa là một cách giữ quê hương. Đứng trước nó, người xứ Nghệ xa nhà có thể nhớ về mái nhà nơi mình sinh ra."},{"t":"Bạn có biết? Tấm rèm tre trước hiên là vật quen thuộc của nhà ở Nghệ An, Hà Tĩnh, dùng để che nắng và che những đợt gió tây nam khô nóng mà người miền Trung gọi là gió Lào. Luồng gió ấy vượt dãy Trường Sơn từ phía đất Lào, tức là từ phía dòng Mê Kông chảy qua Nakhon Phanom."},{"t":"Ba gian, hai hồi: đọc một nếp nhà. Nhà ba gian hai hồi là kiểu nhà phổ biến của nông dân miền Trung và miền Bắc thời trước. Gian giữa thường đặt bàn thờ tổ tiên và là nơi tiếp khách. Hai gian bên là chỗ ngủ, chỗ cất thóc lúa, nông cụ. Hai đầu hồi khép kín, giữ cho nhà đỡ lạnh khi gió mùa và đỡ nóng khi nắng gắt. Mái thấp, hiên nông, cửa gỗ đóng mở cả mảng, hợp với khí hậu nhiều nắng gió. So với nhà sàn Isan cao ráo, gầm thoáng, nếp nhà của người Việt thấp và kín đáo hơn, quay mặt ra sân, ra vườn. Một ngôi nhà như thế không đòi hỏi vật liệu đắt tiền: gỗ, tre, lá lợp đều có thể kiếm quanh vùng. Bà con nghèo có thể góp công giúp nhau dựng nhà, nay nhà này, mai nhà khác. Ông Thầu Chín cũng từng cùng kiều bào dựng nhà như vậy. Bởi thế, ngôi nhà ở bản Mạy không phải một công trình riêng dành cho một nhân vật đặc biệt, mà là một mái nhà bình thường giữa những mái nhà bình thường của xóm."},{"t":"Mối mọt, mưa nắng và việc dựng lại. Gỗ và tre là vật liệu gần gũi, nhưng không bền trước khí hậu nhiệt đới. Mùa mưa ẩm ướt, mùa khô nắng gắt, và nhất là mối mọt, đã dần làm hư hại ngôi nhà cũ. Theo Báo Thanh Niên, ngôi nhà hiện nay được dựng lại vì nhà xưa đã bị mối mọt và thời gian tàn phá, nhưng vẫn giữ kiểu dáng ban đầu. Phục dựng một di tích như vậy luôn là bài toán khó. Ngôi nhà phải đứng vững trước mưa nắng, mà vẫn không được mất đi vẻ mộc mạc của một mái nhà nông dân. Ngôi nhà được dựng lại vẫn giữ đúng quy mô ba gian, giữ vách ván, cửa gỗ và tấm rèm tre, không biến thành một công trình bề thế. Chính sự khiêm nhường ấy làm nên giá trị của nó. Giá trị của ngôi nhà không nằm ở gỗ quý hay chạm trổ, mà ở chỗ nó đúng là kiểu nhà của những người lao động mà ông Thầu Chín đã chọn sống cùng. Câu chuyện về những người bền bỉ gìn giữ khu lưu niệm được kể kỹ hơn ở chuyên đề về nhà lưu niệm ở bản Mạy."},{"t":"Bên trong ba gian nhà. Bước qua tấm rèm tre, khách gặp một không gian mộc mạc. Theo Báo Hà Tĩnh, trong nhà bày bộ bàn ghế được giới thiệu là nơi Bác ngồi làm việc, cùng những nông cụ và đồ dùng quen thuộc: mũ, dao, rựa, cuốc, cào, chum vại đựng nước. Trên vách treo nhiều tranh ảnh về Bác qua các thời kỳ. Nên hiểu rằng phần lớn đồ vật ở đây là đồ dùng thường ngày của một gia đình nông dân Việt kiều, được bày để gợi lại nếp sinh hoạt năm xưa, chứ không nhất thiết là vật Người đã trực tiếp dùng. Dù vậy, chính sự bình thường của chúng lại nói lên nhiều điều. Một chiếc rựa để phát cỏ, một chiếc cuốc để vỡ đất, một vại nước đầy bên cửa. Đó là những thứ gắn với công việc hằng ngày mà ông Thầu Chín đã làm cùng bà con: làm ruộng, đào giếng, dựng nhà, trồng rau. Trong gian trưng bày của bảo tàng, những đồ vật tương tự cũng được đặt quanh ngôi nhà gỗ, và mỗi món đều mang một câu chuyện riêng để khách bấm vào tìm hiểu."},{"t":"Bản Mạy trong hành trình của ông Thầu Chín. Bản Mạy không phải chặng dừng chân đầu tiên của ông Thầu Chín trên đất Xiêm. Người đã qua Phichit, Udon Thani, Sakon Nakhon, rồi mới tới vùng ven sông ở Nakhon Phanom. Nhưng đây là nơi có vị trí đặc biệt. Chỉ cách một dòng Mê Kông là đất Lào, và qua Lào là đường về các tỉnh miền Trung Việt Nam. Ở một nơi như thế, ngôi nhà nhỏ giữa vườn vừa là chỗ ăn, chỗ ngủ, vừa là nơi gặp gỡ bà con, nơi tin tức từ quê nhà truyền đến. Theo lời kể mà gia đình họ Võ lưu giữ, được báo chí ghi lại, ông Thầu Chín sống trong xóm như một người nông dân thực thụ. Không ai trong xóm lạ gì hình ảnh ông già đội nón, đi dép, cặm cụi với mảnh vườn. Chính vẻ bình thường ấy giúp Người tránh được con mắt dò xét của mật thám Pháp, vốn có tai mắt cả trên đất Xiêm. Về nếp sống hằng ngày dưới mái nhà này, xem thêm chuyên đề Ngôi nhà của Thầu Chín."},{"t":"Bạn có biết? Theo Báo Hà Tĩnh, người trông coi ngôi nhà hiện nay là ông Võ Trọng Minh, cháu nội cụ Võ Trọng Đại, người Việt kiều đã che chở ông Thầu Chín ở bản Mạy. Việc gìn giữ di tích vì thế đã được truyền qua nhiều thế hệ trong cùng một gia đình."},{"t":"Từ ngôi nhà ba gian đến nhà sàn Hà Nội. Nhìn lại cả cuộc đời Hồ Chí Minh, ngôi nhà ở bản Mạy nằm trong một chuỗi những nơi ở giản dị đến lạ lùng. Thuở nhỏ là những mái nhà tranh ở quê ngoại Hoàng Trù và quê nội làng Sen. Những năm bôn ba ở Pháp là căn phòng thuê chật hẹp trong ngõ Compoint, Paris, rồi đến mái nhà nông dân Việt kiều ở Xiêm. Năm 1941, trở về Tổ quốc, Người ở hang Cốc Bó, Pác Bó. Tháng 5/1945, Người lên Tân Trào, ở trong lán Nà Lừa dựng bằng tre nứa. Khi đã là Chủ tịch nước, từ tháng 5/1958, Người sống trong ngôi nhà sàn gỗ nhỏ bên ao cá trong khu Phủ Chủ tịch. Tầng trên nhà sàn chỉ có hai phòng, mỗi phòng rộng khoảng mười mét vuông. Những nơi ở ấy giống nhau đến lạ: đủ để làm việc, nghỉ ngơi, và luôn gần gũi với mọi người. Ngôi nhà ba gian ở bản Mạy là một trong những mắt xích sớm nhất của phong cách sống nhất quán ấy."},{"t":"Dấu tích hôm nay. Ngày nay, ngôi nhà ba gian nằm giữa một khu tưởng niệm đã được mở rộng. Theo Báo Hà Tĩnh, bên cạnh ngôi nhà cũ còn có nhà tưởng niệm xây theo kiến trúc Việt, các khu trưng bày, hồ nước trồng sen và núi đá nhân tạo. Dù vậy, ngôi nhà nhỏ vẫn là trái tim của cả khu. Khách đến thăm có thể bước lên hiên, nhìn qua tấm rèm tre vào ba gian nhà, xem bộ bàn ghế, những nông cụ và tranh ảnh, rồi ra vườn đứng bên giếng nước và hàng dừa. Nơi đây là địa chỉ quen thuộc của các đoàn khách từ Việt Nam, của kiều bào và của chính người dân Thái. Có người đến để tìm lại một trang sử, có người đến để hiểu vì sao một người đàn ông từng sống giữa làng mình gần một thế kỷ trước lại được cả một dân tộc kính yêu. Trong gian trưng bày của bảo tàng, ngôi nhà gỗ được dựng lại theo cùng tinh thần ấy: mộc mạc, gần gũi, để khách hình dung một nếp sống hơn là chiêm ngưỡng một công trình."}],"so_chu":1705},{"i":6,"tieu_de_bang":"Hàng dừa trong khu lưu niệm Nakhon Phanom","tieu_de":"Hai cây dừa và một cây khế: khu vườn kể chuyện ông Thầu Chín","sapo":"Ở bản Mạy có hai cây dừa đã vươn cao hơn ba mươi mét và một cây khế già quanh năm trĩu quả. Người giữ vườn kể rằng chúng do chính tay ông Thầu Chín trồng. Tấm ảnh hàng dừa chụp năm 2010 mở ra câu chuyện về cách người Việt xa xứ mang cả một khu vườn quê theo mình, và về một người luôn coi việc trồng cây là việc lớn.","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_nakhonphanom_coco.jpg","credit":"Ảnh: BacLuong · CC BY-SA 4.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Những thân dừa trong tấm ảnh năm 2010","text":"Tấm ảnh do tác giả BacLuong chụp ngày 1/3/2010, ghi lại hàng dừa trong khuôn viên khu lưu niệm Hồ Chí Minh ở bản Mạy, tức bản Na Chok, ngoại ô thành phố Nakhon Phanom. Tháng Ba là lúc mùa nắng nóng bắt đầu ở đông bắc Thái Lan. Lúa trên những thửa ruộng nhờ nước trời đã gặt xong từ cuối năm trước, đất đai bắt đầu khô hanh.\n\nKhu vườn quanh ngôi nhà ông Thầu Chín từng ở là một khu vườn như thế. Theo Báo Hà Tĩnh, trong vườn có hai cây dừa được giới thiệu là do Bác trồng từ năm 1928, nay đã cao trên ba mươi mét. Gần đó là một cây khế cổ thụ, cũng được cho là do Người trồng, quanh năm trĩu quả. Đây là lời kể được gia đình trông coi và kiều bào lưu truyền qua nhiều thế hệ, nên cần hiểu như ký ức của một cộng đồng. Nhưng dù thế nào, những thân cây ấy đã trở thành nhân chứng sống, được chăm sóc bền bỉ suốt gần một thế kỷ.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_ho_chi_minh_nakhonphanom_coco.jpg","chu_thich":"Hàng dừa trong khu lưu niệm Hồ Chí Minh ở bản Mạy (Na Chok), Nakhon Phanom, Thái Lan. Ảnh: BacLuong, ngày 1/3/2010, giấy phép CC BY-SA 4.0.","credit":"Ảnh: BacLuong · CC BY-SA 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Vì sao là cây dừa?","text":"Với người Việt, nhất là ở các vùng ven biển miền Trung và miền Nam, cây dừa gần như là một thành viên trong nhà. Nước dừa để uống, cùi dừa để ăn, ép lấy dầu. Tàu lá dừa có thể lợp nhà, đan phên, còn thân dừa già có thể bắc làm cầu. Trồng vài cây dừa quanh nhà là cách người nông dân tính chuyện lâu dài cho gia đình.\n\nDừa cũng là loài cây của sự kiên nhẫn. Giống dừa cao phải mất nhiều năm mới cho trái, rồi có thể sống và ra quả hàng chục năm. Người trồng dừa vì vậy ít khi mong hái quả ngay; họ trồng cho con cháu. Hình ảnh ấy rất hợp với những gì ông Thầu Chín làm ở đất Xiêm. Người ở đây chỉ hơn một năm, nhưng những việc Người gieo lại, từ lớp chữ, tờ báo đến những tổ chức yêu nước trong kiều bào, đều là những việc cần nhiều năm mới đơm hoa kết trái. Hai cây dừa cao vút hôm nay giống như một ẩn dụ tự nhiên cho những hạt giống ấy.","doc":2},{"loai":"ban_co_biet","text":"Ba mươi năm sau những ngày ở đất Xiêm, chính Người phát động phong trào Tết trồng cây ở miền Bắc. Cuối năm 1959, Người viết bài “Tết trồng cây” trên báo Nhân Dân, và từ mùa xuân năm 1960, mỗi dịp đầu năm lại gắn với hai câu thơ quen thuộc: “Mùa xuân là Tết trồng cây, Làm cho đất nước càng ngày càng xuân.”","nguon_ten":"Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia; Bảo tàng Hồ Chí Minh","doc":3},{"loai":"doan","tieu_de":"Mang cả làng quê theo mình","text":"Người Việt sang Xiêm phần nhiều là nông dân rời quê vì nghèo khó hoặc vì bị thực dân truy bắt. Hành trang của họ ít ỏi, nhưng họ mang theo một thứ không ai lấy được: cách sống của làng quê. Đến đất mới, họ lập xóm, dựng nhà ba gian, đào giếng, rồi trồng quanh nhà những loài cây quen thuộc. Có dừa, có khế, có xoài, có chuối, có khóm tre, và những luống rau cho bữa cơm Việt.\n\nNhững khu vườn ấy không chỉ để lấy hoa trái. Chúng là cách người xa xứ giữ cho con cháu biết mình từ đâu đến. Một đứa trẻ sinh ra ở Nakhon Phanom, lớn lên dưới bóng dừa, ăn quả khế chua chấm muối, nghe bà kể chuyện quê, sẽ mang trong mình một mảnh Việt Nam dù chưa từng thấy Việt Nam. Ông Thầu Chín hiểu rất rõ điều đó. Người hòa mình vào nhịp sống ấy, cùng bà con làm ruộng, đào giếng, trồng rau, trồng chuối quanh nhà. Với Người, lao động không chỉ là việc làm hằng ngày, mà còn là cách để gần gũi, thấu hiểu và được bà con tin cậy.","doc":4},{"loai":"anh","src":"textures/bang_w/G10_6_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Hàng dừa trong khu lưu niệm Nakhon Phanom”, nhìn từ xa."},{"loai":"doan","tieu_de":"Ban ngày ngoài vườn","text":"Một nhà cách mạng từng làm việc ở Paris, Mátxcơva, Quảng Châu, nay cầm cuốc, cầm dao phát bờ, xới đất trồng cây. Với bà con Việt kiều, hình ảnh ấy vừa gần gũi, vừa khiến họ nể phục. Theo lời kể của gia đình họ Võ ở bản Mạy, được báo chí ghi lại, ông Thầu Chín sống như một người nông dân trong xóm, ban ngày làm vườn cùng mọi người.\n\nThói quen chăm sóc cây cối theo Người suốt đời. Nhiều năm sau, trong khu Phủ Chủ tịch ở Hà Nội, quanh ngôi nhà sàn là vườn cây ăn quả và ao cá. Những người từng phục vụ Bác còn nhớ hình ảnh Người thường ra ao cho cá ăn và chăm chút vườn cây quanh nhà. Từ khu vườn nhỏ ở bản Mạy đến vườn cây Phủ Chủ tịch, cây xanh luôn gắn với nơi ở của Người. Và trồng cây, với Người, không bao giờ chỉ là chuyện của cây. Năm 1958, nói chuyện với các thầy cô giáo, Người đã gói cả triết lý ấy vào một câu ngắn gọn.","doc":5},{"loai":"trich","text":"Vì lợi ích mười năm thì phải trồng cây, vì lợi ích trăm năm thì phải trồng người.","nguoi":"Hồ Chí Minh, nói chuyện tại lớp học chính trị của giáo viên cấp II, cấp III toàn miền Bắc, ngày 13/9/1958","nguon_ten":"Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia","doc":6},{"loai":"doan","tieu_de":"Cây khế và câu chuyện cổ tích","text":"Nếu cây dừa gợi sự bền bỉ, thì cây khế lại gợi tuổi thơ. Hầu như đứa trẻ Việt Nam nào cũng thuộc truyện cổ tích “Cây khế”. Người em hiền lành chỉ được chia cây khế, nhưng biết giữ lời, may túi ba gang và được chim thần trả vàng. Người anh tham lam may túi mười hai gang, cuối cùng rơi xuống biển. Câu chuyện dạy con người sống ngay thẳng, biết đủ, không tham lam.\n\nMột cây khế trong vườn nhà vì vậy là một mảnh văn hóa Việt. Giữa đất Isan, nó nhắc những đứa trẻ sinh ra nơi đất khách về những câu chuyện của ông bà. Cây khế ở bản Mạy, theo Báo Hà Tĩnh, đã khoảng tám mươi năm tuổi vào thời điểm bài báo được viết, vẫn quanh năm trĩu quả. Ở quê nhà, quả khế chua vẫn được dùng nấu canh cá, chấm muối ớt; ở đất khách, nó giữ lại cái vị quen ấy. Những chùm khế ấy nối người Việt ở Nakhon Phanom với vị quê hương mà nhiều người chưa từng một lần được về.","doc":7},{"loai":"doan","tieu_de":"Giếng nước giữa vườn","text":"Khu vườn nào cũng cần nước, và ở đông bắc Thái Lan, nước là chuyện sống còn. Mùa mưa ở đây tập trung vào vài tháng giữa năm, còn mùa khô kéo dài, đất cát pha giữ nước kém. Một chiếc giếng tốt quyết định cả mảnh vườn lẫn bữa ăn của gia đình.\n\nTrong khuôn viên khu lưu niệm còn một chiếc giếng nhỏ, tương truyền do ông Thầu Chín cùng bà con đào để lấy nước sinh hoạt. Giếng được giữ nguyên vị trí như một phần của di tích. Nhờ nguồn nước ấy mà hàng dừa, cây khế, những bụi chuối quanh nhà có thể xanh tốt qua những mùa khô gắt. Hình ảnh cái giếng giữa vườn cũng được dựng lại trong gian trưng bày của bảo tàng, kèm câu chuyện riêng về công việc đào giếng. Khu vườn và cái giếng vì thế là một cặp không tách rời: một bên là công sức lao động, một bên là thành quả xanh tươi mà công sức ấy để lại.","doc":8},{"loai":"anh","src":"textures/bang_w/G10_6_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Hàng dừa trong khu lưu niệm Nakhon Phanom”, nhìn theo hướng ngược lại."},{"loai":"ban_co_biet","text":"Người Việt ở đông bắc Thái Lan đã góp vào đời sống địa phương nhiều món ăn quê nhà. Nem nướng, giò lụa theo chân kiều bào trở thành món quen thuộc của người Thái, với tên gọi naem nueang và mu yo.","nguon_ten":"Báo Tuổi Trẻ, “Tới Đông Bắc Thái Lan khám phá dấu ấn Việt trong đời sống và ẩm thực”","doc":9},{"loai":"doan","tieu_de":"Cây xanh và lòng người","text":"Gần một thế kỷ đã qua kể từ khi ông Thầu Chín rời bản Mạy. Cộng đồng người Việt ở đông bắc Thái Lan đã trải qua nhiều biến đổi. Những năm 1960 – 1964, hàng vạn kiều bào về nước theo các chuyến tàu hồi hương. Những gia đình ở lại dần hòa nhập sâu vào đời sống địa phương, nhiều thế hệ con cháu mang quốc tịch Thái.\n\nVậy mà khu vườn vẫn được giữ. Nhiều gia đình vẫn nói tiếng Việt trong nhà, vẫn cúng giỗ, vẫn ăn Tết theo lịch âm, vẫn kể cho con cháu nghe về “ông già Chín” năm nào. Hàng dừa trong khu lưu niệm cũng giống như ký ức ấy. Không ai giao nhiệm vụ cho cây phải sống lâu, nhưng có những bàn tay cứ lặng lẽ tưới nước, vun gốc qua năm này tháng khác. Cây xanh được vun trồng bằng nước giếng, còn ký ức được vun trồng bằng lòng người. Cả hai đều cần sự bền bỉ của nhiều thế hệ, đúng như lời Người dặn về chuyện trồng cây và trồng người.","doc":10},{"loai":"anh","src":"textures/bang_w/G10_6_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Hàng dừa trong khu lưu niệm Nakhon Phanom”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, khu vườn nhỏ nằm trong khu tưởng niệm đã được mở rộng ở bản Na Chok. Theo Báo Hà Tĩnh, khu tưởng niệm có nhà tưởng niệm theo kiến trúc Việt, các khu trưng bày, hồ nước trồng sen và núi đá nhân tạo. Hồ sen là một chi tiết đầy ý nghĩa, bởi quê nội của Bác ở Kim Liên, Nam Đàn, vẫn được gọi thân thương là làng Sen.\n\nKhách đến thăm thường dừng chân dưới gốc hai cây dừa, ngước nhìn những tàu lá cao vút, rồi tìm đến cây khế già bên nhà. Có người đứng lặng bên giếng nước, hình dung cảnh ông Thầu Chín cùng bà con kéo gầu nước tưới rau. Trong gian trưng bày của bảo tàng, hàng dừa, giếng nước và ruộng lúa được dựng lại quanh ngôi nhà gỗ. Chúng không chỉ là phông nền, mà là một phần của câu chuyện: câu chuyện về những người Việt mang cả làng quê theo mình, và về một người đã sống, lao động, gieo trồng giữa họ.","doc":11}],"nguon":["Báo Hà Tĩnh, “Thăm Khu lưu niệm Bác Hồ tại Nakhon Phanom” – https://baohatinh.vn/tham-khu-luu-niem-bac-ho-tai-nakhon-phanom-post133994.html","Báo Thanh Niên, “Nhà của Bác Hồ ở Thái Lan – di tích thú vị không phải ai cũng biết” – https://thanhnien.vn/nha-cua-bac-ho-o-thai-lan-di-tich-thu-vi-khong-phai-ai-cung-biet-1851505845.htm","Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia (nói chuyện với giáo viên ngày 13/9/1958; bài “Tết trồng cây”, 1959)","Bảo tàng Hồ Chí Minh"],"doc":[{"t":"Hai cây dừa và một cây khế: khu vườn kể chuyện ông Thầu Chín. Ở bản Mạy có hai cây dừa đã vươn cao hơn ba mươi mét và một cây khế già quanh năm trĩu quả. Người giữ vườn kể rằng chúng do chính tay ông Thầu Chín trồng. Tấm ảnh hàng dừa chụp năm 2010 mở ra câu chuyện về cách người Việt xa xứ mang cả một khu vườn quê theo mình, và về một người luôn coi việc trồng cây là việc lớn."},{"t":"Những thân dừa trong tấm ảnh năm 2010. Tấm ảnh do tác giả BacLuong chụp ngày 1/3/2010, ghi lại hàng dừa trong khuôn viên khu lưu niệm Hồ Chí Minh ở bản Mạy, tức bản Na Chok, ngoại ô thành phố Nakhon Phanom. Tháng Ba là lúc mùa nắng nóng bắt đầu ở đông bắc Thái Lan. Lúa trên những thửa ruộng nhờ nước trời đã gặt xong từ cuối năm trước, đất đai bắt đầu khô hanh. Khu vườn quanh ngôi nhà ông Thầu Chín từng ở là một khu vườn như thế. Theo Báo Hà Tĩnh, trong vườn có hai cây dừa được giới thiệu là do Bác trồng từ năm 1928, nay đã cao trên ba mươi mét. Gần đó là một cây khế cổ thụ, cũng được cho là do Người trồng, quanh năm trĩu quả. Đây là lời kể được gia đình trông coi và kiều bào lưu truyền qua nhiều thế hệ, nên cần hiểu như ký ức của một cộng đồng. Nhưng dù thế nào, những thân cây ấy đã trở thành nhân chứng sống, được chăm sóc bền bỉ suốt gần một thế kỷ."},{"t":"Vì sao là cây dừa?. Với người Việt, nhất là ở các vùng ven biển miền Trung và miền Nam, cây dừa gần như là một thành viên trong nhà. Nước dừa để uống, cùi dừa để ăn, ép lấy dầu. Tàu lá dừa có thể lợp nhà, đan phên, còn thân dừa già có thể bắc làm cầu. Trồng vài cây dừa quanh nhà là cách người nông dân tính chuyện lâu dài cho gia đình. Dừa cũng là loài cây của sự kiên nhẫn. Giống dừa cao phải mất nhiều năm mới cho trái, rồi có thể sống và ra quả hàng chục năm. Người trồng dừa vì vậy ít khi mong hái quả ngay; họ trồng cho con cháu. Hình ảnh ấy rất hợp với những gì ông Thầu Chín làm ở đất Xiêm. Người ở đây chỉ hơn một năm, nhưng những việc Người gieo lại, từ lớp chữ, tờ báo đến những tổ chức yêu nước trong kiều bào, đều là những việc cần nhiều năm mới đơm hoa kết trái. Hai cây dừa cao vút hôm nay giống như một ẩn dụ tự nhiên cho những hạt giống ấy."},{"t":"Bạn có biết? Ba mươi năm sau những ngày ở đất Xiêm, chính Người phát động phong trào Tết trồng cây ở miền Bắc. Cuối năm 1959, Người viết bài “Tết trồng cây” trên báo Nhân Dân, và từ mùa xuân năm 1960, mỗi dịp đầu năm lại gắn với hai câu thơ quen thuộc: “Mùa xuân là Tết trồng cây, Làm cho đất nước càng ngày càng xuân.”"},{"t":"Mang cả làng quê theo mình. Người Việt sang Xiêm phần nhiều là nông dân rời quê vì nghèo khó hoặc vì bị thực dân truy bắt. Hành trang của họ ít ỏi, nhưng họ mang theo một thứ không ai lấy được: cách sống của làng quê. Đến đất mới, họ lập xóm, dựng nhà ba gian, đào giếng, rồi trồng quanh nhà những loài cây quen thuộc. Có dừa, có khế, có xoài, có chuối, có khóm tre, và những luống rau cho bữa cơm Việt. Những khu vườn ấy không chỉ để lấy hoa trái. Chúng là cách người xa xứ giữ cho con cháu biết mình từ đâu đến. Một đứa trẻ sinh ra ở Nakhon Phanom, lớn lên dưới bóng dừa, ăn quả khế chua chấm muối, nghe bà kể chuyện quê, sẽ mang trong mình một mảnh Việt Nam dù chưa từng thấy Việt Nam. Ông Thầu Chín hiểu rất rõ điều đó. Người hòa mình vào nhịp sống ấy, cùng bà con làm ruộng, đào giếng, trồng rau, trồng chuối quanh nhà. Với Người, lao động không chỉ là việc làm hằng ngày, mà còn là cách để gần gũi, thấu hiểu và được bà con tin cậy."},{"t":"Ban ngày ngoài vườn. Một nhà cách mạng từng làm việc ở Paris, Mátxcơva, Quảng Châu, nay cầm cuốc, cầm dao phát bờ, xới đất trồng cây. Với bà con Việt kiều, hình ảnh ấy vừa gần gũi, vừa khiến họ nể phục. Theo lời kể của gia đình họ Võ ở bản Mạy, được báo chí ghi lại, ông Thầu Chín sống như một người nông dân trong xóm, ban ngày làm vườn cùng mọi người. Thói quen chăm sóc cây cối theo Người suốt đời. Nhiều năm sau, trong khu Phủ Chủ tịch ở Hà Nội, quanh ngôi nhà sàn là vườn cây ăn quả và ao cá. Những người từng phục vụ Bác còn nhớ hình ảnh Người thường ra ao cho cá ăn và chăm chút vườn cây quanh nhà. Từ khu vườn nhỏ ở bản Mạy đến vườn cây Phủ Chủ tịch, cây xanh luôn gắn với nơi ở của Người. Và trồng cây, với Người, không bao giờ chỉ là chuyện của cây. Năm 1958, nói chuyện với các thầy cô giáo, Người đã gói cả triết lý ấy vào một câu ngắn gọn."},{"t":"Vì lợi ích mười năm thì phải trồng cây, vì lợi ích trăm năm thì phải trồng người. — Hồ Chí Minh, nói chuyện tại lớp học chính trị của giáo viên cấp II, cấp III toàn miền Bắc, ngày 13/9/1958"},{"t":"Cây khế và câu chuyện cổ tích. Nếu cây dừa gợi sự bền bỉ, thì cây khế lại gợi tuổi thơ. Hầu như đứa trẻ Việt Nam nào cũng thuộc truyện cổ tích “Cây khế”. Người em hiền lành chỉ được chia cây khế, nhưng biết giữ lời, may túi ba gang và được chim thần trả vàng. Người anh tham lam may túi mười hai gang, cuối cùng rơi xuống biển. Câu chuyện dạy con người sống ngay thẳng, biết đủ, không tham lam. Một cây khế trong vườn nhà vì vậy là một mảnh văn hóa Việt. Giữa đất Isan, nó nhắc những đứa trẻ sinh ra nơi đất khách về những câu chuyện của ông bà. Cây khế ở bản Mạy, theo Báo Hà Tĩnh, đã khoảng tám mươi năm tuổi vào thời điểm bài báo được viết, vẫn quanh năm trĩu quả. Ở quê nhà, quả khế chua vẫn được dùng nấu canh cá, chấm muối ớt; ở đất khách, nó giữ lại cái vị quen ấy. Những chùm khế ấy nối người Việt ở Nakhon Phanom với vị quê hương mà nhiều người chưa từng một lần được về."},{"t":"Giếng nước giữa vườn. Khu vườn nào cũng cần nước, và ở đông bắc Thái Lan, nước là chuyện sống còn. Mùa mưa ở đây tập trung vào vài tháng giữa năm, còn mùa khô kéo dài, đất cát pha giữ nước kém. Một chiếc giếng tốt quyết định cả mảnh vườn lẫn bữa ăn của gia đình. Trong khuôn viên khu lưu niệm còn một chiếc giếng nhỏ, tương truyền do ông Thầu Chín cùng bà con đào để lấy nước sinh hoạt. Giếng được giữ nguyên vị trí như một phần của di tích. Nhờ nguồn nước ấy mà hàng dừa, cây khế, những bụi chuối quanh nhà có thể xanh tốt qua những mùa khô gắt. Hình ảnh cái giếng giữa vườn cũng được dựng lại trong gian trưng bày của bảo tàng, kèm câu chuyện riêng về công việc đào giếng. Khu vườn và cái giếng vì thế là một cặp không tách rời: một bên là công sức lao động, một bên là thành quả xanh tươi mà công sức ấy để lại."},{"t":"Bạn có biết? Người Việt ở đông bắc Thái Lan đã góp vào đời sống địa phương nhiều món ăn quê nhà. Nem nướng, giò lụa theo chân kiều bào trở thành món quen thuộc của người Thái, với tên gọi naem nueang và mu yo."},{"t":"Cây xanh và lòng người. Gần một thế kỷ đã qua kể từ khi ông Thầu Chín rời bản Mạy. Cộng đồng người Việt ở đông bắc Thái Lan đã trải qua nhiều biến đổi. Những năm 1960 – 1964, hàng vạn kiều bào về nước theo các chuyến tàu hồi hương. Những gia đình ở lại dần hòa nhập sâu vào đời sống địa phương, nhiều thế hệ con cháu mang quốc tịch Thái. Vậy mà khu vườn vẫn được giữ. Nhiều gia đình vẫn nói tiếng Việt trong nhà, vẫn cúng giỗ, vẫn ăn Tết theo lịch âm, vẫn kể cho con cháu nghe về “ông già Chín” năm nào. Hàng dừa trong khu lưu niệm cũng giống như ký ức ấy. Không ai giao nhiệm vụ cho cây phải sống lâu, nhưng có những bàn tay cứ lặng lẽ tưới nước, vun gốc qua năm này tháng khác. Cây xanh được vun trồng bằng nước giếng, còn ký ức được vun trồng bằng lòng người. Cả hai đều cần sự bền bỉ của nhiều thế hệ, đúng như lời Người dặn về chuyện trồng cây và trồng người."},{"t":"Dấu tích hôm nay. Ngày nay, khu vườn nhỏ nằm trong khu tưởng niệm đã được mở rộng ở bản Na Chok. Theo Báo Hà Tĩnh, khu tưởng niệm có nhà tưởng niệm theo kiến trúc Việt, các khu trưng bày, hồ nước trồng sen và núi đá nhân tạo. Hồ sen là một chi tiết đầy ý nghĩa, bởi quê nội của Bác ở Kim Liên, Nam Đàn, vẫn được gọi thân thương là làng Sen. Khách đến thăm thường dừng chân dưới gốc hai cây dừa, ngước nhìn những tàu lá cao vút, rồi tìm đến cây khế già bên nhà. Có người đứng lặng bên giếng nước, hình dung cảnh ông Thầu Chín cùng bà con kéo gầu nước tưới rau. Trong gian trưng bày của bảo tàng, hàng dừa, giếng nước và ruộng lúa được dựng lại quanh ngôi nhà gỗ. Chúng không chỉ là phông nền, mà là một phần của câu chuyện: câu chuyện về những người Việt mang cả làng quê theo mình, và về một người đã sống, lao động, gieo trồng giữa họ."}],"so_chu":1684},{"i":7,"tieu_de_bang":"Ngôi nhà của “Thầu Chín”","tieu_de":"Dưới mái nhà ông Thầu Chín: sống như dân để hiểu dân","sapo":"Ngôi nhà gỗ trong gian trưng bày không có món đồ nào quý giá: một tấm phản, một bàn viết, ngọn đèn dầu, chum nước bên hiên. Vậy mà dưới những mái nhà như thế, năm 1928 – 1929, một người từng làm việc ở Paris, Mátxcơva, Quảng Châu đã sống như một nông dân nghèo. Vì sao Nguyễn Ái Quốc chọn cách sống ấy, và nó đã để lại cho Người bài học gì?","bia":{"src":"textures/bai/G10_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Bước lên hiên nhà","text":"Khách bước vào gian Thái Lan – Thầu Chín sẽ gặp một ngôi nhà gỗ thấp, vách ván, mái lá, hiên trước có bậc thang gỗ. Bên trong là tấm phản để nằm, chiếc bàn viết với ngọn đèn dầu và tập giấy ghi chép, một chiếc bàn nhỏ cho lớp học buổi tối, một chiếc hòm gỗ. Ngoài hiên có chum nước, thùng gỗ múc nước. Góc sân là cái giếng; trong gian còn có chiếc mai đào đất.\n\nNgôi nhà này là một bản tái hiện, dựng theo những mô tả về ngôi nhà ở bản Mạy, Nakhon Phanom, và nếp nhà của kiều bào vùng đông bắc Xiêm cuối những năm 1920. Các đồ vật trong nhà đều là vật minh họa, không phải hiện vật gốc. Nhưng chúng được chọn lựa để trả lời một câu hỏi: một nhà cách mạng đã sống ra sao khi tự nguyện trở thành “ông Thầu Chín” của một xóm nghèo nơi đất khách? Câu trả lời bắt đầu từ chính sự bình thường của mọi thứ trong ngôi nhà.","doc":1},{"loai":"anh","src":"textures/bang_w/G10_7_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Ngôi nhà của “Thầu Chín””, nhìn từ xa."},{"loai":"doan","tieu_de":"Từ Paris đến một xóm nghèo","text":"Trước khi đến Xiêm, Nguyễn Ái Quốc đã đi qua những trung tâm chính trị lớn của thế giới. Ở Paris, Người viết báo, tham gia thành lập Đảng Cộng sản Pháp. Ở Mátxcơva, Người học tập và làm việc trong Quốc tế Cộng sản. Ở Quảng Châu, Người mở lớp huấn luyện, sáng lập Hội Việt Nam Cách mạng Thanh niên năm 1925. Người quen với những cuộc hội nghị, những bài diễn thuyết, những trang báo in bằng nhiều thứ tiếng.\n\nTháng 7/1928, tất cả những điều ấy được cất kín sau cái tên Thầu Chín. Người đội nón, đi dép, mặc như bà con lao động trong xóm. Người cùng kiều bào làm ruộng, đào giếng, dựng nhà, trồng rau, ăn uống đạm bạc. Không có chỗ ở riêng sang trọng, không có người phục dịch. Người tự làm mọi việc của mình như một người lao động. Sự chuyển đổi ấy không phải một màn hóa trang nhất thời. Suốt hơn một năm, qua Phichit, Udon Thani, Sakon Nakhon đến bản Mạy, ông Thầu Chín đều sống đúng như vậy, giữa những người mà Người gọi là đồng bào.","doc":2},{"loai":"doan","tieu_de":"Mái nhà của gia đình họ Võ","text":"Ở bản Mạy, ký ức về ông Thầu Chín gắn với một gia đình cụ thể. Theo Báo Hà Tĩnh, cụ Võ Trọng Đại là người Việt kiều đã che chở Bác trong thời gian Người sống ở đây. Theo Báo Thanh Niên, gia đình họ Võ có gốc gác ở vùng Hưng Nguyên, Nghệ An, và đến nay con cháu vẫn trông nom ngôi nhà cùng khu lưu niệm. Người đang coi sóc di tích là ông Võ Trọng Minh, cháu nội cụ Võ Trọng Đại.\n\nChe chở một người như Nguyễn Ái Quốc lúc ấy không phải chuyện nhỏ. Mật thám Pháp đang truy lùng Người, và bất cứ gia đình nào cho Người ở nhờ cũng có thể gặp nguy hiểm. Vậy mà những gia đình Việt kiều nghèo vẫn mở cửa đón Người như đón một người thân. Lòng tin ấy không tự nhiên mà có. Nó được vun đắp từ những ngày ông Thầu Chín cùng bà con ra đồng, cùng gánh nước, cùng lo toan những việc thường ngày của một gia đình nông dân.","doc":3},{"loai":"ban_co_biet","text":"Hưng Nguyên, quê gốc của gia đình họ Võ ở bản Mạy, là vùng đất giáp ranh Nam Đàn, quê hương của Nguyễn Ái Quốc. Giữa đất Xiêm, Người đã sống dưới mái nhà của những người gần như đồng hương.","nguon_ten":"Báo Thanh Niên; Báo Hà Tĩnh; bản đồ hành chính tỉnh Nghệ An","doc":4},{"loai":"doan","tieu_de":"Một ngày dưới mái nhà ấy","text":"Một ngày của ông Thầu Chín bắt đầu như ngày của mọi người trong xóm. Sáng sớm ra đồng, ra vườn, làm những việc nhà nông: cuốc đất, trồng rau, trồng chuối, đào giếng, góp sức dựng nhà cho bà con. Trưa về, bữa cơm đạm bạc như bao gia đình nghèo khác.\n\nKhi trời tối, ngôi nhà lại có một đời sống khác. Ngọn đèn dầu được thắp lên, lớp học chữ quốc ngữ cho trẻ em và người lớn bắt đầu. Câu chuyện về lớp học ấy và tờ báo Thân Ái được kể ở chuyên đề Lớp học đèn dầu và tờ báo Thân Ái. Đêm khuya, khi xóm đã ngủ, chiếc bàn viết vẫn sáng: Người dịch sách, soạn tài liệu, viết bài, viết thư liên lạc. Giường nằm chỉ là tấm phản gỗ hay chiếc giường tre. Những đêm đi đường xa, có khi Người phải ngủ lại trong rừng. Nếp sinh hoạt ấy không có gì đặc biệt với một người nông dân. Điều đặc biệt là người sống nếp ấy lại mang trong đầu kế hoạch cho cả một phong trào.","doc":5},{"loai":"anh","src":"textures/ht/ht_anh_house_hochiminh_stayed_nakhonphanom.jpg","chu_thich":"Ngôi nhà ông Thầu Chín từng ở tại bản Mạy (Na Chok), Nakhon Phanom, nay đã được phục dựng. Ảnh: BacLuong, Wikipedia tiếng Việt, giấy phép CC BY 4.0.","credit":"Ảnh: BacLuong at Vietnamese Wikipedia · CC BY 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Mái nhà bình thường, công việc không bình thường","text":"Sự giản dị của ngôi nhà còn là một lớp áo bảo vệ. Xiêm là một vương quốc độc lập, nhưng mật thám Pháp vẫn có tai mắt trên đất Xiêm và luôn tìm cách lần theo dấu vết Nguyễn Ái Quốc. Ở Nakhon Phanom, chỉ cách một dòng sông, bờ bên kia là đất Lào thuộc quyền cai trị của Pháp. Tháng 10/1929, Người còn bị tòa án ở Vinh xử vắng mặt và kết án tử hình (xem chuyên đề Tin từ quê nhà và chuyến đi cuối năm 1929).\n\nTrong hoàn cảnh ấy, một ông Thầu Chín sống lẫn giữa bà con là người khó bị chú ý nhất. Nhà cửa, ăn mặc, công việc chẳng khác ai, lại thường xuyên di chuyển giữa các tỉnh. Chính dưới những mái nhà bình thường ấy, sách báo được dịch, bài được viết, người được liên lạc để nối các xóm Việt kiều với phong trào trong nước qua ngả Lào. Chiếc hòm gỗ trong gian trưng bày gợi lại công việc cất giữ tài liệu cẩn mật ấy.","doc":6},{"loai":"doan","tieu_de":"Vận động từ những việc nhỏ nhất","text":"Sống giữa kiều bào, ông Thầu Chín không đứng trên bà con để giảng giải. Người lao động như họ, nghe họ kể chuyện làm ăn, chuyện quê nhà, rồi từ những việc thiết thực nhất mà vận động. Nhà ai sắp dựng thì cả xóm đến giúp. Xóm thiếu nước thì cùng nhau đào giếng. Ai ốm đau, hoạn nạn thì có hội tương tế đỡ đần. Con em không biết chữ thì mở lớp dạy chữ.\n\nMỗi việc làm chung như thế là một lần bà con thấy rõ sức mạnh của sự đoàn kết. Và từ những việc nhỏ ấy, các tổ chức yêu nước trong kiều bào được củng cố từ gốc, bằng lòng tin chứ không bằng mệnh lệnh. Người cũng khuyên kiều bào sống hòa thuận với người dân sở tại, tôn trọng phong tục của nước Xiêm, để cộng đồng có thể yên ổn làm ăn lâu dài. Cách làm ấy về sau được Người đúc kết thành một phương pháp, mà hơn hai mươi năm sau Người gọi bằng một cái tên giản dị: dân vận.","doc":7},{"loai":"anh","src":"textures/bang_w/G10_7_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Ngôi nhà của “Thầu Chín””, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Hai mươi năm sau: bài báo Dân vận","text":"Ngày 15/10/1949, giữa những năm kháng chiến chống thực dân Pháp, báo Sự thật đăng bài “Dân vận” của Hồ Chí Minh. Bài báo ngắn, lời lẽ mộc mạc, nhưng chứa đựng một quan niệm lớn. Mở đầu bài, Người viết: “Nước ta là nước dân chủ. Bao nhiêu lợi ích đều vì dân. Bao nhiêu quyền hạn đều của dân.”\n\nBài báo giải thích dân vận là vận động tất cả lực lượng của mỗi người dân, không để sót một người nào, góp thành lực lượng toàn dân. Người phê phán lối làm việc quan liêu, chỉ ngồi bàn giấy ra lệnh. Theo Người, cán bộ phải đến tận nơi, sống gần dân, hiểu dân, giúp dân làm những việc thiết thực. Đọc những dòng ấy, khó mà không nghĩ tới ông Thầu Chín năm nào, người đã tự mình cầm cuốc, đào giếng cùng kiều bào trước khi nói với họ về Tổ quốc. Những gì Người viết năm 1949 là điều Người đã sống từ hai mươi năm trước.","doc":8},{"loai":"trich","text":"Những người phụ trách dân vận cần phải óc nghĩ, mắt trông, tai nghe, chân đi, miệng nói, tay làm. Chứ không phải chỉ nói suông, chỉ ngồi viết mệnh lệnh.","nguoi":"Hồ Chí Minh, bài “Dân vận”","nguon_ten":"Báo Sự thật, ngày 15/10/1949; Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia","doc":9},{"loai":"doan","tieu_de":"Học dân trước khi dạy dân","text":"Ở Xiêm, ông Thầu Chín vừa là người dạy, vừa là người học. Người dạy bà con chữ quốc ngữ, nhưng cũng học từ bà con biết bao điều: cách sinh sống nơi đất khách, tâm tư của người nông dân nghèo, những điều khiến họ lo, họ tin, họ hy vọng. Người còn chăm chỉ học tiếng Xiêm để trò chuyện được với người dân sở tại.\n\nTinh thần học hỏi quần chúng ấy trở thành một nguyên tắc trong cách làm việc của Người. Trong tác phẩm “Sửa đổi lối làm việc” viết năm 1947, Người nhắc cán bộ phải học hỏi dân chúng, bởi dân chúng nhiều khi có cách giải quyết giản đơn mà thiết thực hơn những người tự cho mình là giỏi. Khi đã là Chủ tịch nước, trong những chuyến về thăm nông thôn, Người thường vào tận nhà dân, hỏi chuyện mùa màng, xem bữa ăn của bà con. Nhiều nhân chứng còn nhớ những lần Người mở vung nồi để xem nhà nông dân ăn gì. Cử chỉ ấy có gốc rễ từ những ngày sống dưới mái nhà nông dân ở Xiêm.","doc":10},{"loai":"ban_co_biet","text":"Bài “Dân vận” đăng trên báo Sự thật ngày 15/10/1949 được ký bút danh X.Y.Z, một trong rất nhiều bút danh Người dùng khi viết báo. Tác phẩm “Sửa đổi lối làm việc” năm 1947 cũng ký tên X.Y.Z.","nguon_ten":"Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia","doc":11},{"loai":"doan","tieu_de":"Những đồ vật kể chuyện","text":"Trong gian trưng bày, mỗi đồ vật quanh ngôi nhà đều mở ra một câu chuyện riêng. Tấm phản gỗ gợi chỗ nằm giản dị của ông Thầu Chín. Chiếc bàn viết và ngọn đèn dầu gợi những đêm dịch sách, viết báo. Chiếc bàn nhỏ bên cạnh là góc lớp học chữ quốc ngữ buổi tối. Tập giấy ghi chép nhắc chuyện Người học tiếng Xiêm. Chiếc hòm gỗ gợi công việc cất giữ tài liệu cẩn mật.\n\nNgoài hiên, chum nước và thùng gỗ kể về nhịp sinh hoạt thường ngày, khi mỗi gia đình phải múc nước giếng về dùng. Chiếc mai đào đất và cái giếng gợi công việc lao động chung của cả xóm. Tất cả đều là vật minh họa, được đặt đúng vào vị trí mà chúng thường có trong một ngôi nhà Việt kiều thời ấy. Khách có thể bấm vào từng đồ vật để nghe câu chuyện gắn với nó. Ghép lại, chúng tạo thành bức chân dung của một nếp sống: giản dị, tự lực, gần gũi, và luôn hướng về Tổ quốc.","doc":12},{"loai":"anh","src":"textures/bang_w/G10_7_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Ngôi nhà của “Thầu Chín””, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngôi nhà ông Thầu Chín từng ở tại bản Mạy, tức bản Na Chok, cách trung tâm thành phố Nakhon Phanom chừng năm cây số, ngày nay đã được phục dựng và nằm trong một khu tưởng niệm mở rộng. Theo Báo Hà Tĩnh, trong nhà bày bộ bàn ghế được giới thiệu là nơi Bác ngồi làm việc, cùng những nông cụ, chum vại và tranh ảnh về Bác. Chuyện về kiến trúc ngôi nhà và việc dựng lại nó được kể ở chuyên đề Ngôi nhà Người từng ở tại Nakhon Phanom.\n\nỞ Udon Thani và Phichit, những nơi ông Thầu Chín từng qua, cũng có các khu di tích lưu giữ ký ức về Người. Những địa điểm ấy được kiều bào và bạn bè Thái Lan chăm sóc, đón khách từ hai nước. Còn trong bảo tàng này, ngôi nhà gỗ nhỏ là nơi để khách tự mình bước lên hiên, ngồi xuống bên bàn viết và hình dung một buổi tối năm 1929. Ngọn đèn dầu leo lét, tiếng trẻ đánh vần ngoài hiên, và một người đàn ông gầy gò đang lặng lẽ viết cho ngày mai của cả một dân tộc.","doc":13}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia (bài “Dân vận”, 1949; “Sửa đổi lối làm việc”, 1947)","Trần Dân Tiên, Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch","Báo Hà Tĩnh, “Thăm Khu lưu niệm Bác Hồ tại Nakhon Phanom” – https://baohatinh.vn/tham-khu-luu-niem-bac-ho-tai-nakhon-phanom-post133994.html","Báo Thanh Niên, “Nhà của Bác Hồ ở Thái Lan – di tích thú vị không phải ai cũng biết” – https://thanhnien.vn/nha-cua-bac-ho-o-thai-lan-di-tich-thu-vi-khong-phai-ai-cung-biet-1851505845.htm","Bảo tàng Hồ Chí Minh"],"doc":[{"t":"Dưới mái nhà ông Thầu Chín: sống như dân để hiểu dân. Ngôi nhà gỗ trong gian trưng bày không có món đồ nào quý giá: một tấm phản, một bàn viết, ngọn đèn dầu, chum nước bên hiên. Vậy mà dưới những mái nhà như thế, năm 1928 – 1929, một người từng làm việc ở Paris, Mátxcơva, Quảng Châu đã sống như một nông dân nghèo. Vì sao Nguyễn Ái Quốc chọn cách sống ấy, và nó đã để lại cho Người bài học gì?"},{"t":"Bước lên hiên nhà. Khách bước vào gian Thái Lan – Thầu Chín sẽ gặp một ngôi nhà gỗ thấp, vách ván, mái lá, hiên trước có bậc thang gỗ. Bên trong là tấm phản để nằm, chiếc bàn viết với ngọn đèn dầu và tập giấy ghi chép, một chiếc bàn nhỏ cho lớp học buổi tối, một chiếc hòm gỗ. Ngoài hiên có chum nước, thùng gỗ múc nước. Góc sân là cái giếng; trong gian còn có chiếc mai đào đất. Ngôi nhà này là một bản tái hiện, dựng theo những mô tả về ngôi nhà ở bản Mạy, Nakhon Phanom, và nếp nhà của kiều bào vùng đông bắc Xiêm cuối những năm 1920. Các đồ vật trong nhà đều là vật minh họa, không phải hiện vật gốc. Nhưng chúng được chọn lựa để trả lời một câu hỏi: một nhà cách mạng đã sống ra sao khi tự nguyện trở thành “ông Thầu Chín” của một xóm nghèo nơi đất khách? Câu trả lời bắt đầu từ chính sự bình thường của mọi thứ trong ngôi nhà."},{"t":"Từ Paris đến một xóm nghèo. Trước khi đến Xiêm, Nguyễn Ái Quốc đã đi qua những trung tâm chính trị lớn của thế giới. Ở Paris, Người viết báo, tham gia thành lập Đảng Cộng sản Pháp. Ở Mátxcơva, Người học tập và làm việc trong Quốc tế Cộng sản. Ở Quảng Châu, Người mở lớp huấn luyện, sáng lập Hội Việt Nam Cách mạng Thanh niên năm 1925. Người quen với những cuộc hội nghị, những bài diễn thuyết, những trang báo in bằng nhiều thứ tiếng. Tháng 7/1928, tất cả những điều ấy được cất kín sau cái tên Thầu Chín. Người đội nón, đi dép, mặc như bà con lao động trong xóm. Người cùng kiều bào làm ruộng, đào giếng, dựng nhà, trồng rau, ăn uống đạm bạc. Không có chỗ ở riêng sang trọng, không có người phục dịch. Người tự làm mọi việc của mình như một người lao động. Sự chuyển đổi ấy không phải một màn hóa trang nhất thời. Suốt hơn một năm, qua Phichit, Udon Thani, Sakon Nakhon đến bản Mạy, ông Thầu Chín đều sống đúng như vậy, giữa những người mà Người gọi là đồng bào."},{"t":"Mái nhà của gia đình họ Võ. Ở bản Mạy, ký ức về ông Thầu Chín gắn với một gia đình cụ thể. Theo Báo Hà Tĩnh, cụ Võ Trọng Đại là người Việt kiều đã che chở Bác trong thời gian Người sống ở đây. Theo Báo Thanh Niên, gia đình họ Võ có gốc gác ở vùng Hưng Nguyên, Nghệ An, và đến nay con cháu vẫn trông nom ngôi nhà cùng khu lưu niệm. Người đang coi sóc di tích là ông Võ Trọng Minh, cháu nội cụ Võ Trọng Đại. Che chở một người như Nguyễn Ái Quốc lúc ấy không phải chuyện nhỏ. Mật thám Pháp đang truy lùng Người, và bất cứ gia đình nào cho Người ở nhờ cũng có thể gặp nguy hiểm. Vậy mà những gia đình Việt kiều nghèo vẫn mở cửa đón Người như đón một người thân. Lòng tin ấy không tự nhiên mà có. Nó được vun đắp từ những ngày ông Thầu Chín cùng bà con ra đồng, cùng gánh nước, cùng lo toan những việc thường ngày của một gia đình nông dân."},{"t":"Bạn có biết? Hưng Nguyên, quê gốc của gia đình họ Võ ở bản Mạy, là vùng đất giáp ranh Nam Đàn, quê hương của Nguyễn Ái Quốc. Giữa đất Xiêm, Người đã sống dưới mái nhà của những người gần như đồng hương."},{"t":"Một ngày dưới mái nhà ấy. Một ngày của ông Thầu Chín bắt đầu như ngày của mọi người trong xóm. Sáng sớm ra đồng, ra vườn, làm những việc nhà nông: cuốc đất, trồng rau, trồng chuối, đào giếng, góp sức dựng nhà cho bà con. Trưa về, bữa cơm đạm bạc như bao gia đình nghèo khác. Khi trời tối, ngôi nhà lại có một đời sống khác. Ngọn đèn dầu được thắp lên, lớp học chữ quốc ngữ cho trẻ em và người lớn bắt đầu. Câu chuyện về lớp học ấy và tờ báo Thân Ái được kể ở chuyên đề Lớp học đèn dầu và tờ báo Thân Ái. Đêm khuya, khi xóm đã ngủ, chiếc bàn viết vẫn sáng: Người dịch sách, soạn tài liệu, viết bài, viết thư liên lạc. Giường nằm chỉ là tấm phản gỗ hay chiếc giường tre. Những đêm đi đường xa, có khi Người phải ngủ lại trong rừng. Nếp sinh hoạt ấy không có gì đặc biệt với một người nông dân. Điều đặc biệt là người sống nếp ấy lại mang trong đầu kế hoạch cho cả một phong trào."},{"t":"Mái nhà bình thường, công việc không bình thường. Sự giản dị của ngôi nhà còn là một lớp áo bảo vệ. Xiêm là một vương quốc độc lập, nhưng mật thám Pháp vẫn có tai mắt trên đất Xiêm và luôn tìm cách lần theo dấu vết Nguyễn Ái Quốc. Ở Nakhon Phanom, chỉ cách một dòng sông, bờ bên kia là đất Lào thuộc quyền cai trị của Pháp. Tháng 10/1929, Người còn bị tòa án ở Vinh xử vắng mặt và kết án tử hình (xem chuyên đề Tin từ quê nhà và chuyến đi cuối năm 1929). Trong hoàn cảnh ấy, một ông Thầu Chín sống lẫn giữa bà con là người khó bị chú ý nhất. Nhà cửa, ăn mặc, công việc chẳng khác ai, lại thường xuyên di chuyển giữa các tỉnh. Chính dưới những mái nhà bình thường ấy, sách báo được dịch, bài được viết, người được liên lạc để nối các xóm Việt kiều với phong trào trong nước qua ngả Lào. Chiếc hòm gỗ trong gian trưng bày gợi lại công việc cất giữ tài liệu cẩn mật ấy."},{"t":"Vận động từ những việc nhỏ nhất. Sống giữa kiều bào, ông Thầu Chín không đứng trên bà con để giảng giải. Người lao động như họ, nghe họ kể chuyện làm ăn, chuyện quê nhà, rồi từ những việc thiết thực nhất mà vận động. Nhà ai sắp dựng thì cả xóm đến giúp. Xóm thiếu nước thì cùng nhau đào giếng. Ai ốm đau, hoạn nạn thì có hội tương tế đỡ đần. Con em không biết chữ thì mở lớp dạy chữ. Mỗi việc làm chung như thế là một lần bà con thấy rõ sức mạnh của sự đoàn kết. Và từ những việc nhỏ ấy, các tổ chức yêu nước trong kiều bào được củng cố từ gốc, bằng lòng tin chứ không bằng mệnh lệnh. Người cũng khuyên kiều bào sống hòa thuận với người dân sở tại, tôn trọng phong tục của nước Xiêm, để cộng đồng có thể yên ổn làm ăn lâu dài. Cách làm ấy về sau được Người đúc kết thành một phương pháp, mà hơn hai mươi năm sau Người gọi bằng một cái tên giản dị: dân vận."},{"t":"Hai mươi năm sau: bài báo Dân vận. Ngày 15/10/1949, giữa những năm kháng chiến chống thực dân Pháp, báo Sự thật đăng bài “Dân vận” của Hồ Chí Minh. Bài báo ngắn, lời lẽ mộc mạc, nhưng chứa đựng một quan niệm lớn. Mở đầu bài, Người viết: “Nước ta là nước dân chủ. Bao nhiêu lợi ích đều vì dân. Bao nhiêu quyền hạn đều của dân.” Bài báo giải thích dân vận là vận động tất cả lực lượng của mỗi người dân, không để sót một người nào, góp thành lực lượng toàn dân. Người phê phán lối làm việc quan liêu, chỉ ngồi bàn giấy ra lệnh. Theo Người, cán bộ phải đến tận nơi, sống gần dân, hiểu dân, giúp dân làm những việc thiết thực. Đọc những dòng ấy, khó mà không nghĩ tới ông Thầu Chín năm nào, người đã tự mình cầm cuốc, đào giếng cùng kiều bào trước khi nói với họ về Tổ quốc. Những gì Người viết năm 1949 là điều Người đã sống từ hai mươi năm trước."},{"t":"Những người phụ trách dân vận cần phải óc nghĩ, mắt trông, tai nghe, chân đi, miệng nói, tay làm. Chứ không phải chỉ nói suông, chỉ ngồi viết mệnh lệnh. — Hồ Chí Minh, bài “Dân vận”"},{"t":"Học dân trước khi dạy dân. Ở Xiêm, ông Thầu Chín vừa là người dạy, vừa là người học. Người dạy bà con chữ quốc ngữ, nhưng cũng học từ bà con biết bao điều: cách sinh sống nơi đất khách, tâm tư của người nông dân nghèo, những điều khiến họ lo, họ tin, họ hy vọng. Người còn chăm chỉ học tiếng Xiêm để trò chuyện được với người dân sở tại. Tinh thần học hỏi quần chúng ấy trở thành một nguyên tắc trong cách làm việc của Người. Trong tác phẩm “Sửa đổi lối làm việc” viết năm 1947, Người nhắc cán bộ phải học hỏi dân chúng, bởi dân chúng nhiều khi có cách giải quyết giản đơn mà thiết thực hơn những người tự cho mình là giỏi. Khi đã là Chủ tịch nước, trong những chuyến về thăm nông thôn, Người thường vào tận nhà dân, hỏi chuyện mùa màng, xem bữa ăn của bà con. Nhiều nhân chứng còn nhớ những lần Người mở vung nồi để xem nhà nông dân ăn gì. Cử chỉ ấy có gốc rễ từ những ngày sống dưới mái nhà nông dân ở Xiêm."},{"t":"Bạn có biết? Bài “Dân vận” đăng trên báo Sự thật ngày 15/10/1949 được ký bút danh X.Y.Z, một trong rất nhiều bút danh Người dùng khi viết báo. Tác phẩm “Sửa đổi lối làm việc” năm 1947 cũng ký tên X.Y.Z."},{"t":"Những đồ vật kể chuyện. Trong gian trưng bày, mỗi đồ vật quanh ngôi nhà đều mở ra một câu chuyện riêng. Tấm phản gỗ gợi chỗ nằm giản dị của ông Thầu Chín. Chiếc bàn viết và ngọn đèn dầu gợi những đêm dịch sách, viết báo. Chiếc bàn nhỏ bên cạnh là góc lớp học chữ quốc ngữ buổi tối. Tập giấy ghi chép nhắc chuyện Người học tiếng Xiêm. Chiếc hòm gỗ gợi công việc cất giữ tài liệu cẩn mật. Ngoài hiên, chum nước và thùng gỗ kể về nhịp sinh hoạt thường ngày, khi mỗi gia đình phải múc nước giếng về dùng. Chiếc mai đào đất và cái giếng gợi công việc lao động chung của cả xóm. Tất cả đều là vật minh họa, được đặt đúng vào vị trí mà chúng thường có trong một ngôi nhà Việt kiều thời ấy. Khách có thể bấm vào từng đồ vật để nghe câu chuyện gắn với nó. Ghép lại, chúng tạo thành bức chân dung của một nếp sống: giản dị, tự lực, gần gũi, và luôn hướng về Tổ quốc."},{"t":"Dấu tích hôm nay. Ngôi nhà ông Thầu Chín từng ở tại bản Mạy, tức bản Na Chok, cách trung tâm thành phố Nakhon Phanom chừng năm cây số, ngày nay đã được phục dựng và nằm trong một khu tưởng niệm mở rộng. Theo Báo Hà Tĩnh, trong nhà bày bộ bàn ghế được giới thiệu là nơi Bác ngồi làm việc, cùng những nông cụ, chum vại và tranh ảnh về Bác. Chuyện về kiến trúc ngôi nhà và việc dựng lại nó được kể ở chuyên đề Ngôi nhà Người từng ở tại Nakhon Phanom. Ở Udon Thani và Phichit, những nơi ông Thầu Chín từng qua, cũng có các khu di tích lưu giữ ký ức về Người. Những địa điểm ấy được kiều bào và bạn bè Thái Lan chăm sóc, đón khách từ hai nước. Còn trong bảo tàng này, ngôi nhà gỗ nhỏ là nơi để khách tự mình bước lên hiên, ngồi xuống bên bàn viết và hình dung một buổi tối năm 1929. Ngọn đèn dầu leo lét, tiếng trẻ đánh vần ngoài hiên, và một người đàn ông gầy gò đang lặng lẽ viết cho ngày mai của cả một dân tộc."}],"so_chu":2038},{"i":8,"tieu_de_bang":"Những chặng đường đi bộ","tieu_de":"Hàng trăm cây số bằng đôi chân: ông Thầu Chín đi khắp các xóm Việt kiều","sapo":"Từ Phichit bên sông Nan đến bờ Mê Kông ở Nakhon Phanom, riêng khoảng cách theo đường chim bay đã gần năm trăm cây số. Ông Thầu Chín đã nối các xóm Việt kiều rải rác trên quãng đường ấy phần lớn bằng chính đôi chân mình, có đêm phải ngủ lại giữa rừng. Những chặng đường đi bộ không chỉ là cách di chuyển: đó là cách một cộng đồng rời rạc được dệt thành một mạng lưới.","bia":{"src":"textures/bai/G10_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Rời Bản Đông","text":"Tháng 7/1928, chặng đầu tiên của ông Thầu Chín trên đất Xiêm là tỉnh Phichit, ở vùng đồng bằng phía bắc miền trung Xiêm, bên dòng sông Nan. Tại Bản Đông thuộc tỉnh này có một xóm Việt kiều, và ngày nay nơi đây có một khu di tích về Người. Nhưng Phichit chỉ là điểm khởi đầu. Phần đông kiều bào khi ấy sống ở vùng đông bắc, xứ Isan, dọc theo những con sông đổ về Mê Kông.\n\nMuốn đến với họ, phải vượt qua một khoảng cách rất xa. Từ Phichit đến Udon Thani, theo đường chim bay đã khoảng 280 cây số. Từ Udon Thani sang Sakon Nakhon thêm khoảng 150 cây số, rồi từ Sakon Nakhon ra Nakhon Phanom bên sông Mê Kông khoảng 75 cây số nữa. Cộng lại, gần năm trăm cây số đường chim bay. Đường đi thực tế còn dài hơn nhiều, vì phải vòng qua núi, men theo đồi, lội qua suối, chưa kể những lần đi đi về về giữa các xóm. Phần lớn quãng đường ấy, ông Thầu Chín đi bộ.","doc":1},{"loai":"anh","src":"textures/bang_w/G10_8_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Những chặng đường đi bộ”, nhìn từ xa."},{"loai":"doan","tieu_de":"Bức tường núi và cao nguyên Isan","text":"Giữa đồng bằng miền trung Xiêm và xứ Isan là dãy núi Phetchabun, chạy dài theo hướng bắc nam như một bức tường tự nhiên. Vượt qua dãy núi ấy là cao nguyên Khorat, một vùng đất rộng lớn, tương đối bằng phẳng nhưng khô cằn. Đất ở đây phần nhiều là đất cát pha, giữ nước kém. Mùa mưa ngắn, mùa khô dài. Những con sông lớn như Mun, Chi chảy chậm qua cao nguyên rồi đổ vào Mê Kông.\n\nNhững năm 1920, phần lớn xứ Isan còn phủ rừng thưa, loại rừng cây họ dầu rụng lá vào mùa khô. Làng mạc nằm rải rác, cách nhau hàng chục cây số. Người dân chủ yếu làm ruộng nhờ nước trời, sống đạm bạc. Đường sắt từ Bangkok đã lên tới Khorat từ đầu thế kỷ, nhưng phải tới đầu những năm 1940 mới vươn tới Udon Thani. Đường ô tô còn rất ít. Đi lại giữa các tỉnh, người ta chủ yếu dựa vào đôi chân, xe bò hoặc thuyền trên sông. Với một người muốn đi khắp các xóm Việt kiều, không có con đường nào khác ngoài con đường bộ.","doc":2},{"loai":"ban_co_biet","text":"Phần lớn cư dân Isan nói một thứ tiếng rất gần với tiếng Lào. Vì thế, học tiếng của người dân vùng này cũng là học thứ tiếng được nói ở bờ bên kia sông Mê Kông, nơi có con đường bí mật về Việt Nam.","nguon_ten":"Encyclopaedia Britannica, mục Thailand – Northeast (Isan); Isan – Wikipedia tiếng Anh (đối chiếu)","doc":3},{"loai":"doan","tieu_de":"Những chặng dừng chân","text":"Mỗi chặng dừng của ông Thầu Chín là một xóm Việt kiều. Udon Thani là nơi có đông kiều bào ở đông bắc Xiêm, và cũng là nơi có khu tưởng niệm về Người ngày nay. Sakon Nakhon nằm bên hồ Nong Han, hồ nước ngọt tự nhiên lớn nhất vùng đông bắc Thái Lan, nơi có những xóm người Việt làm ruộng, làm vườn. Nakhon Phanom nằm ngay bên bờ Mê Kông, nhìn sang đất Lào.\n\nỞ mỗi nơi, Người không chỉ nghỉ chân. Người ở lại với bà con, cùng họ làm ruộng, đào giếng, dựng nhà, mở lớp dạy chữ, củng cố tổ chức. Rồi khi công việc ở đó đã vào nếp, Người lại lên đường sang xóm khác. Suốt hơn một năm, Người di chuyển liên tục giữa Phichit, Udon Thani, Sakon Nakhon, Nakhon Phanom. Có những quãng đường Người đi một lần rồi thôi, có những quãng Người đi lại nhiều lần, mỗi lần mang theo tin tức, tài liệu và lời động viên từ xóm này sang xóm khác.","doc":4},{"loai":"doan","tieu_de":"Vì sao phải đi bộ?","text":"Đi bộ trước hết vì hoàn cảnh. Kiều bào nghèo, tổ chức không có kinh phí, phương tiện đi lại hiếm hoi. Một chuyến đi bằng tàu xe, nếu có, cũng tốn kém hơn nhiều so với túi tiền của một người nông dân.\n\nNhưng đi bộ còn là cách hoạt động kín đáo nhất. Nhà ga, bến xe, bến thuyền là nơi dễ bị để ý, dễ bị hỏi han giấy tờ. Một người đi đường đội nón, đi dép như mọi người lao động thì khó gây chú ý hơn nhiều. Dọc đường, Người ghé các xóm Việt kiều, gặp gỡ bà con, nắm tình hình từng nơi, rồi mới quyết định củng cố tổ chức ở đâu, mở lớp học ở đâu. Việc di chuyển liên tục giữa các tỉnh cũng giúp Người tránh được sự dò la của mật thám Pháp. Không ai có thể chắc chắn hôm nay ông Thầu Chín ở xóm nào, mai sẽ đi đâu. Đôi chân vì thế vừa là phương tiện, vừa là tấm lá chắn.","doc":5},{"loai":"anh","src":"textures/bai/G10_v1.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện xóm Việt kiều ở bản Mạy (Na Chok), Nakhon Phanom, những năm 1928 – 1929, nhìn từ trên cao.","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Đêm giữa rừng","text":"Trên những quãng đường dài giữa các tỉnh, không phải lúc nào cũng có xóm làng để nghỉ. Nhiều đêm, Người phải ngủ lại trong rừng. Rừng Isan những năm ấy còn rộng, có thú dữ, muỗi nhiều, sốt rét rừng là mối đe dọa thường trực với người đi đường. Mùa mưa, đường đất lầy lội, suối dâng nước. Mùa khô, nắng gắt, nhiều quãng khan hiếm nước uống.\n\nĐể đi được những chặng đường như thế, người đi phải có sức khỏe, sự bền bỉ và một tinh thần lạc quan. Năm ấy ông Thầu Chín đã ba mươi tám tuổi, sau nhiều năm bôn ba qua những xứ lạnh ở châu Âu và Liên Xô. Vậy mà Người vẫn giữ được nếp sống giản dị, tự làm mọi việc như một người lao động. Những đêm nằm giữa rừng, xa gia đình, xa quê hương, người đi đường ấy vẫn đau đáu một nỗi niềm. Đó là làm sao nối được kiều bào với phong trào trong nước, làm sao để những người cách mạng Việt Nam đoàn kết lại.","doc":6},{"loai":"doan","tieu_de":"Mỗi bước chân, một mắt xích","text":"Nhìn trên bản đồ, những chặng đường của ông Thầu Chín vẽ nên một đường nối từ vùng đồng bằng miền trung Xiêm lên tận bờ sông Mê Kông. Mỗi xóm Việt kiều Người ghé qua là một điểm trên đường nối ấy. Trước khi Người đến, các xóm sống khá riêng rẽ, mỗi nơi một hội, một cách làm. Người đi, và cùng với Người, tin tức, sách báo, kinh nghiệm cũng đi.\n\nDần dần, những cộng đồng cách nhau hàng trăm cây số bắt đầu biết đến nhau, đọc cùng một tờ báo, học cùng những bài học, hướng về cùng một mục tiêu. Ở đầu mút phía đông, Nakhon Phanom và các xóm ven sông là nơi tiếp giáp với đất Lào, nơi con đường liên lạc bí mật vượt sông, vượt Trường Sơn về Nghệ An, Hà Tĩnh. Như vậy, những bước chân của ông Thầu Chín không chỉ nối các xóm với nhau, mà còn nối cả mạng lưới kiều bào ở Xiêm với phong trào cách mạng trong nước. Về con đường vượt sông ấy, xem chuyên đề Sông Mê Kông.","doc":7},{"loai":"anh","src":"textures/bang_w/G10_8_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Những chặng đường đi bộ”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Đi đường mới biết gian lao","text":"Mười bốn năm sau những chặng đường ở Xiêm, Người lại phải đi bộ triền miên, nhưng lần này trong cảnh tù đày. Tháng 8/1942, trên đường sang Trung Quốc, Người bị chính quyền địa phương ở Quảng Tây bắt giữ. Hơn một năm sau đó, Người bị giải qua rất nhiều nhà lao, phần lớn quãng đường phải đi bộ, chân tay bị trói, cổ đeo xiềng.\n\nTrong tập thơ chữ Hán “Nhật ký trong tù” viết những năm ấy, có bài “Đi đường” chỉ bốn câu, được Nam Trân dịch ra tiếng Việt. Bài thơ nói về núi non trùng điệp, nhưng người đọc hiểu đó cũng là chuyện của con đường cách mạng. Cái gian lao của người đi đường không làm Người nản lòng, mà trở thành một phần của niềm vui khi lên tới đỉnh cao. Có lẽ những bước chân qua rừng núi đất Xiêm năm nào cũng là một phần trong trải nghiệm để Người viết nên những câu thơ ấy.","doc":8},{"loai":"trich","text":"Đi đường mới biết gian lao, / Núi cao rồi lại núi cao trập trùng; / Núi cao lên đến tận cùng, / Thu vào tầm mắt muôn trùng nước non.","nguoi":"Hồ Chí Minh, bài “Đi đường” trong “Nhật ký trong tù”, bản dịch của Nam Trân","nguon_ten":"Hồ Chí Minh Toàn tập, tập 3, NXB Chính trị quốc gia","doc":9},{"loai":"doan","tieu_de":"Một thói quen theo suốt cuộc đời","text":"Những chặng đường ở Xiêm không phải lần đầu và cũng không phải lần cuối Người đi bộ đường dài. Những năm hoạt động ở Việt Bắc, từ Pác Bó đến Tân Trào, Người vượt đèo, lội suối, đi bộ qua núi rừng như một người lính. Cuốn “Vừa đi đường vừa kể chuyện”, Người viết với bút danh T. Lan, mang ngay trong nhan đề hình ảnh những chuyến đi bằng đôi chân của vị Chủ tịch nước.\n\nĐi bộ với Người còn là một cách rèn luyện thân thể. Ngay sau Cách mạng Tháng Tám, năm 1946, Người ra Lời kêu gọi toàn dân tập thể dục, coi sức khỏe của mỗi người dân là sức mạnh của cả nước. Những người từng giúp việc Bác kể rằng, cả những năm cuối đời, Người vẫn tập leo dốc, mang vác nặng, với mong ước một ngày được vào thăm đồng bào miền Nam. Rèn luyện thân thể, chịu đựng gian khổ, gần gũi nhân dân trên từng chặng đường: thói quen ấy đã hiện rõ trong những bước chân của ông Thầu Chín năm nào.","doc":10},{"loai":"ban_co_biet","text":"Lời kêu gọi toàn dân tập thể dục của Chủ tịch Hồ Chí Minh ra ngày 27/3/1946 kết thúc bằng câu: “Tự tôi, ngày nào tôi cũng tập.” Ngày 27/3 hằng năm nay là Ngày Thể thao Việt Nam.","nguon_ten":"Hồ Chí Minh Toàn tập, tập 4, NXB Chính trị quốc gia; Bộ Văn hóa, Thể thao và Du lịch","doc":11},{"loai":"anh","src":"textures/bang_w/G10_8_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Những chặng đường đi bộ”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Gần một thế kỷ sau, những chặng đường ông Thầu Chín từng đi đã đổi khác hoàn toàn. Đường ô tô trải nhựa nối Phichit với Udon Thani, Sakon Nakhon, Nakhon Phanom. Quãng đường ngày xưa phải đi bộ nhiều ngày, nay chỉ mất vài giờ xe chạy. Rừng thưa đã nhường chỗ cho ruộng lúa, đồn điền và thị trấn.\n\nNhưng dọc con đường ấy vẫn còn những dấu mốc của ký ức. Ở Bản Đông, tỉnh Phichit, có khu di tích về Người. Ở Udon Thani có khu tưởng niệm. Ở bản Mạy, ngoại ô Nakhon Phanom, có ngôi nhà được phục dựng cùng khu lưu niệm mở rộng. Nhiều đoàn khách Việt Nam sang Thái Lan chọn cách đi qua lần lượt những địa điểm này, như một cách lần theo dấu chân của Người. Trong gian trưng bày của bảo tàng, những chặng đường ấy được gợi lại qua không gian xóm Việt kiều. Khách có thể hình dung một người đàn ông đội nón, đi dép, lặng lẽ băng qua cả một vùng đất rộng lớn vì một mục đích duy nhất: con đường về Tổ quốc.","doc":12}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","T. Lan, Vừa đi đường vừa kể chuyện, NXB Sự thật","Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia (Nhật ký trong tù; Lời kêu gọi toàn dân tập thể dục, 27/3/1946)","Ban Quản lý Lăng Chủ tịch Hồ Chí Minh, “Rớt nước mắt, Bác luyện vác nặng để vào miền Nam” (bqllang.gov.vn)","Bảo tàng Hồ Chí Minh","Encyclopaedia Britannica, mục Thailand"],"doc":[{"t":"Hàng trăm cây số bằng đôi chân: ông Thầu Chín đi khắp các xóm Việt kiều. Từ Phichit bên sông Nan đến bờ Mê Kông ở Nakhon Phanom, riêng khoảng cách theo đường chim bay đã gần năm trăm cây số. Ông Thầu Chín đã nối các xóm Việt kiều rải rác trên quãng đường ấy phần lớn bằng chính đôi chân mình, có đêm phải ngủ lại giữa rừng. Những chặng đường đi bộ không chỉ là cách di chuyển: đó là cách một cộng đồng rời rạc được dệt thành một mạng lưới."},{"t":"Rời Bản Đông. Tháng 7/1928, chặng đầu tiên của ông Thầu Chín trên đất Xiêm là tỉnh Phichit, ở vùng đồng bằng phía bắc miền trung Xiêm, bên dòng sông Nan. Tại Bản Đông thuộc tỉnh này có một xóm Việt kiều, và ngày nay nơi đây có một khu di tích về Người. Nhưng Phichit chỉ là điểm khởi đầu. Phần đông kiều bào khi ấy sống ở vùng đông bắc, xứ Isan, dọc theo những con sông đổ về Mê Kông. Muốn đến với họ, phải vượt qua một khoảng cách rất xa. Từ Phichit đến Udon Thani, theo đường chim bay đã khoảng 280 cây số. Từ Udon Thani sang Sakon Nakhon thêm khoảng 150 cây số, rồi từ Sakon Nakhon ra Nakhon Phanom bên sông Mê Kông khoảng 75 cây số nữa. Cộng lại, gần năm trăm cây số đường chim bay. Đường đi thực tế còn dài hơn nhiều, vì phải vòng qua núi, men theo đồi, lội qua suối, chưa kể những lần đi đi về về giữa các xóm. Phần lớn quãng đường ấy, ông Thầu Chín đi bộ."},{"t":"Bức tường núi và cao nguyên Isan. Giữa đồng bằng miền trung Xiêm và xứ Isan là dãy núi Phetchabun, chạy dài theo hướng bắc nam như một bức tường tự nhiên. Vượt qua dãy núi ấy là cao nguyên Khorat, một vùng đất rộng lớn, tương đối bằng phẳng nhưng khô cằn. Đất ở đây phần nhiều là đất cát pha, giữ nước kém. Mùa mưa ngắn, mùa khô dài. Những con sông lớn như Mun, Chi chảy chậm qua cao nguyên rồi đổ vào Mê Kông. Những năm 1920, phần lớn xứ Isan còn phủ rừng thưa, loại rừng cây họ dầu rụng lá vào mùa khô. Làng mạc nằm rải rác, cách nhau hàng chục cây số. Người dân chủ yếu làm ruộng nhờ nước trời, sống đạm bạc. Đường sắt từ Bangkok đã lên tới Khorat từ đầu thế kỷ, nhưng phải tới đầu những năm 1940 mới vươn tới Udon Thani. Đường ô tô còn rất ít. Đi lại giữa các tỉnh, người ta chủ yếu dựa vào đôi chân, xe bò hoặc thuyền trên sông. Với một người muốn đi khắp các xóm Việt kiều, không có con đường nào khác ngoài con đường bộ."},{"t":"Bạn có biết? Phần lớn cư dân Isan nói một thứ tiếng rất gần với tiếng Lào. Vì thế, học tiếng của người dân vùng này cũng là học thứ tiếng được nói ở bờ bên kia sông Mê Kông, nơi có con đường bí mật về Việt Nam."},{"t":"Những chặng dừng chân. Mỗi chặng dừng của ông Thầu Chín là một xóm Việt kiều. Udon Thani là nơi có đông kiều bào ở đông bắc Xiêm, và cũng là nơi có khu tưởng niệm về Người ngày nay. Sakon Nakhon nằm bên hồ Nong Han, hồ nước ngọt tự nhiên lớn nhất vùng đông bắc Thái Lan, nơi có những xóm người Việt làm ruộng, làm vườn. Nakhon Phanom nằm ngay bên bờ Mê Kông, nhìn sang đất Lào. Ở mỗi nơi, Người không chỉ nghỉ chân. Người ở lại với bà con, cùng họ làm ruộng, đào giếng, dựng nhà, mở lớp dạy chữ, củng cố tổ chức. Rồi khi công việc ở đó đã vào nếp, Người lại lên đường sang xóm khác. Suốt hơn một năm, Người di chuyển liên tục giữa Phichit, Udon Thani, Sakon Nakhon, Nakhon Phanom. Có những quãng đường Người đi một lần rồi thôi, có những quãng Người đi lại nhiều lần, mỗi lần mang theo tin tức, tài liệu và lời động viên từ xóm này sang xóm khác."},{"t":"Vì sao phải đi bộ?. Đi bộ trước hết vì hoàn cảnh. Kiều bào nghèo, tổ chức không có kinh phí, phương tiện đi lại hiếm hoi. Một chuyến đi bằng tàu xe, nếu có, cũng tốn kém hơn nhiều so với túi tiền của một người nông dân. Nhưng đi bộ còn là cách hoạt động kín đáo nhất. Nhà ga, bến xe, bến thuyền là nơi dễ bị để ý, dễ bị hỏi han giấy tờ. Một người đi đường đội nón, đi dép như mọi người lao động thì khó gây chú ý hơn nhiều. Dọc đường, Người ghé các xóm Việt kiều, gặp gỡ bà con, nắm tình hình từng nơi, rồi mới quyết định củng cố tổ chức ở đâu, mở lớp học ở đâu. Việc di chuyển liên tục giữa các tỉnh cũng giúp Người tránh được sự dò la của mật thám Pháp. Không ai có thể chắc chắn hôm nay ông Thầu Chín ở xóm nào, mai sẽ đi đâu. Đôi chân vì thế vừa là phương tiện, vừa là tấm lá chắn."},{"t":"Đêm giữa rừng. Trên những quãng đường dài giữa các tỉnh, không phải lúc nào cũng có xóm làng để nghỉ. Nhiều đêm, Người phải ngủ lại trong rừng. Rừng Isan những năm ấy còn rộng, có thú dữ, muỗi nhiều, sốt rét rừng là mối đe dọa thường trực với người đi đường. Mùa mưa, đường đất lầy lội, suối dâng nước. Mùa khô, nắng gắt, nhiều quãng khan hiếm nước uống. Để đi được những chặng đường như thế, người đi phải có sức khỏe, sự bền bỉ và một tinh thần lạc quan. Năm ấy ông Thầu Chín đã ba mươi tám tuổi, sau nhiều năm bôn ba qua những xứ lạnh ở châu Âu và Liên Xô. Vậy mà Người vẫn giữ được nếp sống giản dị, tự làm mọi việc như một người lao động. Những đêm nằm giữa rừng, xa gia đình, xa quê hương, người đi đường ấy vẫn đau đáu một nỗi niềm. Đó là làm sao nối được kiều bào với phong trào trong nước, làm sao để những người cách mạng Việt Nam đoàn kết lại."},{"t":"Mỗi bước chân, một mắt xích. Nhìn trên bản đồ, những chặng đường của ông Thầu Chín vẽ nên một đường nối từ vùng đồng bằng miền trung Xiêm lên tận bờ sông Mê Kông. Mỗi xóm Việt kiều Người ghé qua là một điểm trên đường nối ấy. Trước khi Người đến, các xóm sống khá riêng rẽ, mỗi nơi một hội, một cách làm. Người đi, và cùng với Người, tin tức, sách báo, kinh nghiệm cũng đi. Dần dần, những cộng đồng cách nhau hàng trăm cây số bắt đầu biết đến nhau, đọc cùng một tờ báo, học cùng những bài học, hướng về cùng một mục tiêu. Ở đầu mút phía đông, Nakhon Phanom và các xóm ven sông là nơi tiếp giáp với đất Lào, nơi con đường liên lạc bí mật vượt sông, vượt Trường Sơn về Nghệ An, Hà Tĩnh. Như vậy, những bước chân của ông Thầu Chín không chỉ nối các xóm với nhau, mà còn nối cả mạng lưới kiều bào ở Xiêm với phong trào cách mạng trong nước. Về con đường vượt sông ấy, xem chuyên đề Sông Mê Kông."},{"t":"Đi đường mới biết gian lao. Mười bốn năm sau những chặng đường ở Xiêm, Người lại phải đi bộ triền miên, nhưng lần này trong cảnh tù đày. Tháng 8/1942, trên đường sang Trung Quốc, Người bị chính quyền địa phương ở Quảng Tây bắt giữ. Hơn một năm sau đó, Người bị giải qua rất nhiều nhà lao, phần lớn quãng đường phải đi bộ, chân tay bị trói, cổ đeo xiềng. Trong tập thơ chữ Hán “Nhật ký trong tù” viết những năm ấy, có bài “Đi đường” chỉ bốn câu, được Nam Trân dịch ra tiếng Việt. Bài thơ nói về núi non trùng điệp, nhưng người đọc hiểu đó cũng là chuyện của con đường cách mạng. Cái gian lao của người đi đường không làm Người nản lòng, mà trở thành một phần của niềm vui khi lên tới đỉnh cao. Có lẽ những bước chân qua rừng núi đất Xiêm năm nào cũng là một phần trong trải nghiệm để Người viết nên những câu thơ ấy."},{"t":"Đi đường mới biết gian lao, / Núi cao rồi lại núi cao trập trùng; / Núi cao lên đến tận cùng, / Thu vào tầm mắt muôn trùng nước non. — Hồ Chí Minh, bài “Đi đường” trong “Nhật ký trong tù”, bản dịch của Nam Trân"},{"t":"Một thói quen theo suốt cuộc đời. Những chặng đường ở Xiêm không phải lần đầu và cũng không phải lần cuối Người đi bộ đường dài. Những năm hoạt động ở Việt Bắc, từ Pác Bó đến Tân Trào, Người vượt đèo, lội suối, đi bộ qua núi rừng như một người lính. Cuốn “Vừa đi đường vừa kể chuyện”, Người viết với bút danh T. Lan, mang ngay trong nhan đề hình ảnh những chuyến đi bằng đôi chân của vị Chủ tịch nước. Đi bộ với Người còn là một cách rèn luyện thân thể. Ngay sau Cách mạng Tháng Tám, năm 1946, Người ra Lời kêu gọi toàn dân tập thể dục, coi sức khỏe của mỗi người dân là sức mạnh của cả nước. Những người từng giúp việc Bác kể rằng, cả những năm cuối đời, Người vẫn tập leo dốc, mang vác nặng, với mong ước một ngày được vào thăm đồng bào miền Nam. Rèn luyện thân thể, chịu đựng gian khổ, gần gũi nhân dân trên từng chặng đường: thói quen ấy đã hiện rõ trong những bước chân của ông Thầu Chín năm nào."},{"t":"Bạn có biết? Lời kêu gọi toàn dân tập thể dục của Chủ tịch Hồ Chí Minh ra ngày 27/3/1946 kết thúc bằng câu: “Tự tôi, ngày nào tôi cũng tập.” Ngày 27/3 hằng năm nay là Ngày Thể thao Việt Nam."},{"t":"Dấu tích hôm nay. Gần một thế kỷ sau, những chặng đường ông Thầu Chín từng đi đã đổi khác hoàn toàn. Đường ô tô trải nhựa nối Phichit với Udon Thani, Sakon Nakhon, Nakhon Phanom. Quãng đường ngày xưa phải đi bộ nhiều ngày, nay chỉ mất vài giờ xe chạy. Rừng thưa đã nhường chỗ cho ruộng lúa, đồn điền và thị trấn. Nhưng dọc con đường ấy vẫn còn những dấu mốc của ký ức. Ở Bản Đông, tỉnh Phichit, có khu di tích về Người. Ở Udon Thani có khu tưởng niệm. Ở bản Mạy, ngoại ô Nakhon Phanom, có ngôi nhà được phục dựng cùng khu lưu niệm mở rộng. Nhiều đoàn khách Việt Nam sang Thái Lan chọn cách đi qua lần lượt những địa điểm này, như một cách lần theo dấu chân của Người. Trong gian trưng bày của bảo tàng, những chặng đường ấy được gợi lại qua không gian xóm Việt kiều. Khách có thể hình dung một người đàn ông đội nón, đi dép, lặng lẽ băng qua cả một vùng đất rộng lớn vì một mục đích duy nhất: con đường về Tổ quốc."}],"so_chu":1841},{"i":9,"tieu_de_bang":"Sông Mê Kông","tieu_de":"Sông Mê Kông ở Nakhon Phanom: một dòng sông, ba đất nước","sapo":"Chiều xuống ở Nakhon Phanom, mặt sông Mê Kông rộng mênh mông, bên kia là những dãy núi đá vôi của đất Lào. Gần một thế kỷ trước, ông Thầu Chín từng sống cách bờ sông này không xa, ban ngày làm vườn, tối đi đánh cá như bà con trong xóm. Với Người, dòng sông vừa là đường biên phải canh chừng, vừa là con đường bí mật dẫn về quê hương.","bia":{"src":"textures/bai/G10_v5.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Một buổi chiều bên bờ sông","text":"Ai từng đứng trên bờ sông ở thành phố Nakhon Phanom lúc hoàng hôn đều khó quên cảnh ấy. Dòng Mê Kông trải rộng, nước đục màu phù sa, chảy chậm về phương nam. Bên kia sông là thị xã Thà Khẹt của Lào, và xa hơn là những dãy núi đá vôi tỉnh Khăm Muộn nhô lên sừng sững, đổi màu theo ánh chiều.\n\nCuối những năm 1920, ông Thầu Chín sống ở bản Mạy, tức bản Na Chok, cách trung tâm thành phố chừng năm cây số. Theo lời kể mà gia đình họ Võ ở bản Mạy lưu giữ, được Báo Thanh Niên ghi lại, những ngày ấy Người sống như một người nông dân: ban ngày làm vườn, tối đi đánh cá. Với kiều bào ven sông, đánh cá là một phần của sinh kế, và cũng là cách hòa vào nhịp sống chung của cả xóm. Hẳn ít ai để ý đến một ông già đội nón trở về nhà lúc trời đã tối. Nhưng mỗi lần nhìn sang bờ bên kia, người ấy biết rằng chỉ cách một dòng sông, Tổ quốc đã ở rất gần.","doc":1},{"loai":"anh","src":"textures/bang_w/G10_9_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Sông Mê Kông”, nhìn từ xa."},{"loai":"doan","tieu_de":"Dòng sông của sáu quốc gia","text":"Mê Kông là một trong những con sông lớn nhất châu Á, dài hơn bốn nghìn cây số. Sông bắt nguồn từ cao nguyên Tây Tạng, chảy qua Trung Quốc, nơi nó được gọi là Lan Thương, rồi qua Myanmar, Lào, Thái Lan, Campuchia, trước khi đổ ra biển ở Việt Nam. Ở hạ lưu, người Việt gọi sông là Cửu Long, sông Chín Rồng, vì dòng chảy tỏa ra nhiều cửa trước khi vào biển.\n\nĐoạn sông chảy qua Nakhon Phanom là đường biên giới tự nhiên giữa Thái Lan và Lào. Mỗi năm, sông có hai gương mặt. Mùa mưa, nước dâng cao, cuồn cuộn phù sa, mặt sông rộng hẳn ra. Mùa khô, nước rút, lộ ra những bãi cát, dải đá giữa dòng. Đời sống của cư dân hai bờ, cả người Thái, người Lào lẫn người Việt, gắn chặt với nhịp lên xuống ấy: đánh cá, trồng rau trên bãi bồi, đi lại bằng thuyền. Tên Nakhon Phanom trong tiếng Thái có nghĩa là thành phố núi, nhưng những dãy núi đá vôi nổi bật nhìn thấy từ bờ sông lại thuộc về phía Lào.","doc":2},{"loai":"ban_co_biet","text":"Mê Kông là quê hương của cá tra dầu, một trong những loài cá nước ngọt lớn nhất thế giới. Có những con dài tới khoảng ba mét, nặng khoảng ba trăm ki lô gam. Loài cá này nay đang bị đe dọa nghiêm trọng.","nguon_ten":"Ủy hội sông Mê Kông quốc tế (MRC); Sách Đỏ IUCN","doc":3},{"loai":"doan","tieu_de":"Bờ bên kia: đất Lào dưới quyền Pháp","text":"Năm 1929, dòng Mê Kông ở Nakhon Phanom không chỉ ngăn cách hai vùng đất. Nó ngăn cách một vương quốc độc lập với một vùng thuộc địa. Sau cuộc xung đột Pháp – Xiêm năm 1893, Xiêm phải nhường cho Pháp vùng đất phía đông sông Mê Kông. Lào dần bị sáp nhập vào Liên bang Đông Dương thuộc Pháp, và dòng sông trở thành đường biên giữa Xiêm với thuộc địa Pháp.\n\nThà Khẹt, thị xã nằm ngay bờ bên kia, là một trung tâm hành chính và buôn bán của chính quyền thực dân ở miền trung Lào. Thời ấy, nhiều người Việt sinh sống ở Thà Khẹt, làm thợ, làm công chức, buôn bán. Đứng ở bờ Xiêm, ông Thầu Chín nhìn sang một vùng đất nằm dưới cùng bộ máy cai trị đang áp bức quê hương mình. Chính quyền và mật thám Pháp ở bên kia có thể dõi theo những gì diễn ra ở bờ bên này. Vì thế, sống bên sông vừa là cơ hội, vừa là thử thách: gần quê hương hơn bao giờ hết, nhưng cũng gần kẻ thù hơn bao giờ hết.","doc":4},{"loai":"doan","tieu_de":"Con đường bí mật về quê hương","text":"Chính vị trí ấy khiến các xóm Việt kiều ven Mê Kông có ý nghĩa đặc biệt. Từ Nakhon Phanom qua sông là đất Lào. Từ Thà Khẹt đi về phía đông, vượt dãy Trường Sơn, là tới các tỉnh miền Trung Việt Nam như Quảng Bình, Hà Tĩnh, Nghệ An. Đó là con đường ngắn nhất nối các xóm Việt kiều ở đông bắc Xiêm với quê hương.\n\nTheo con đường ấy, sách báo, tài liệu cách mạng được bí mật chuyển về trong nước. Cũng theo con đường ấy, những thanh niên yêu nước từ Nghệ An, Hà Tĩnh tìm sang Xiêm để học tập, được giác ngộ rồi trở về hoạt động. Mỗi chuyến đi đều nguy hiểm: phải qua sông, qua những trạm canh của Pháp, băng rừng, vượt núi. Trong hơn một năm ở Xiêm, ông Thầu Chín góp phần củng cố đường dây liên lạc này, biến những xóm nhỏ bên sông thành hậu cứ của phong trào. Những bước chân của Người qua các tỉnh Isan, kể ở chuyên đề Những chặng đường đi bộ, đều hướng về đầu mối quan trọng này.","doc":5},{"loai":"anh","src":"textures/bai/G10_v6.jpg","chu_thich":"Một góc không gian 3D tái hiện xóm Việt kiều ở bản Mạy (Na Chok), Nakhon Phanom, những năm 1928 – 1929.","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Bên dòng sông, chờ thời cơ","text":"Bên bờ Mê Kông, tin tức từ quê nhà đến với ông Thầu Chín qua những người đi lại trên con đường bí mật. Năm 1929, những tin ấy báo hiệu một bước ngoặt: trong nước đã xuất hiện ba tổ chức cộng sản hoạt động riêng rẽ, đòi hỏi phải sớm thống nhất. Cuối năm ấy, Người rời Xiêm sang Hồng Kông, để đầu năm 1930 chủ trì hội nghị hợp nhất ở Cửu Long. Câu chuyện này được kể kỹ ở chuyên đề Tin từ quê nhà và chuyến đi cuối năm 1929.\n\nĐiều đáng nói là dù đã ở rất gần, Người vẫn chưa thể về nước qua dòng sông này. Phải hơn mười một năm sau, ngày 28/1/1941, Người mới đặt chân trở lại Tổ quốc. Lần ấy, Người không vượt Mê Kông mà qua cột mốc 108 trên biên giới Việt – Trung ở Cao Bằng. Dòng sông ở Nakhon Phanom vì thế là nơi Người đứng gần quê hương nhất trong nhiều năm bôn ba, nhưng vẫn phải kiên nhẫn chờ đợi thời cơ.","doc":6},{"loai":"anh","src":"textures/bang_w/G10_9_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Sông Mê Kông”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Nghĩa tình bên kia sông","text":"Con đường qua Lào không chỉ là một tuyến liên lạc. Nó còn gắn với tình nghĩa giữa hai dân tộc Việt, Lào cùng chung cảnh bị thực dân Pháp đô hộ. Những năm sau này, trong cuộc kháng chiến chống Pháp rồi chống Mỹ, dãy Trường Sơn và các tỉnh miền trung Lào, trong đó có Khăm Muộn, trở thành nơi hai dân tộc sát cánh bên nhau.\n\nNgười luôn trân trọng mối tình ấy. Trong những lời thơ về tình đoàn kết Việt – Lào, Người đã nhắc tên hai dòng sông lớn: sông Hồng và chính dòng Mê Kông, mà người Việt gọi là Cửu Long. Đọc những câu thơ ấy bên bờ sông Nakhon Phanom, người ta có thể hình dung ông Thầu Chín năm nào, đứng nhìn sang bờ Lào, nơi con đường về quê hương đi qua những bản làng của người Lào. Tình cảm ấy không đến từ sách vở, mà từ chính những năm tháng Người sống gần gũi với hai bờ sông.","doc":7},{"loai":"trich","text":"Thương nhau mấy núi cũng trèo, / Mấy sông cũng lội, mấy đèo cũng qua. / Việt – Lào hai nước chúng ta, / Tình sâu hơn nước Hồng Hà, Cửu Long.","nguoi":"Chủ tịch Hồ Chí Minh","nguon_ten":"Lời thơ của Chủ tịch Hồ Chí Minh về tình đoàn kết Việt – Lào, được Bảo tàng Hồ Chí Minh và nhiều văn kiện hữu nghị hai nước dẫn lại","doc":8},{"loai":"ban_co_biet","text":"Rời xứ sở bên sông Mê Kông, con sông mà ở hạ lưu người Việt gọi là Cửu Long, ông Thầu Chín đi tới Cửu Long ở Hương Cảng để chủ trì hội nghị hợp nhất đầu năm 1930. Hai địa danh ấy đều viết bằng hai chữ Hán 九龍, nghĩa là chín con rồng.","nguon_ten":"Đào Duy Anh, Hán Việt từ điển","doc":9},{"loai":"doan","tieu_de":"Mùa lễ hội trên sông","text":"Ngày nay, dòng Mê Kông ở Nakhon Phanom vẫn là trung tâm của đời sống thành phố. Con đường ven sông là nơi người dân tập thể dục, đi dạo mỗi chiều. Hằng năm, vào dịp kết thúc mùa an cư của Phật giáo, thường rơi vào tháng Mười dương lịch, Nakhon Phanom tổ chức lễ hội thả thuyền lửa trên sông. Những con thuyền kết đèn rực rỡ trôi trên mặt nước đêm, thu hút du khách từ khắp nơi.\n\nNgười Việt ở Nakhon Phanom cũng góp phần vào nhịp sống ven sông ấy. Nhiều gia đình kiều bào mở quán ăn, cửa hàng, giữ những món ăn Việt được người Thái yêu thích. Họ vẫn nhớ rằng thế hệ ông bà mình từng sống bên con sông này trong những năm tháng khó khăn nhất, và từng che chở một người sau này trở thành Chủ tịch nước Việt Nam. Dòng sông chứng kiến tất cả, lặng lẽ chảy qua gần một thế kỷ, từ những chuyến vượt sông bí mật năm xưa đến những đoàn du khách thong thả ngắm hoàng hôn.","doc":10},{"loai":"anh","src":"textures/bang_w/G10_9_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Sông Mê Kông”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay: cây cầu và tháp đồng hồ","text":"Gần một thế kỷ sau những chuyến vượt sông bí mật, đoạn Mê Kông ở Nakhon Phanom đã có cầu Hữu nghị Thái – Lào thứ ba nối sang Thà Khẹt, khánh thành năm 2011. Từ Thà Khẹt, đường bộ đi về phía đông qua cặp cửa khẩu Na Phàu – Cha Lo để vào tỉnh Quảng Bình. Con đường năm xưa phải lặn lội nhiều ngày, nay du khách Việt Nam có thể đi chỉ trong một ngày đường để tới thăm nhà lưu niệm ở bản Mạy.\n\nNgay trung tâm thành phố Nakhon Phanom còn có tháp đồng hồ do cộng đồng người Việt dựng năm 1960. Năm 2020, lễ kỷ niệm sáu mươi năm công trình được tổ chức trang trọng. Tháp đồng hồ, ngôi nhà ở bản Mạy và cây cầu hữu nghị cùng kể một câu chuyện dài về người Việt bên dòng Mê Kông. Trong gian trưng bày của bảo tàng, dãy núi đá vôi Khăm Muộn phía xa và dòng sông được tái hiện để khách đứng ở nơi ông Thầu Chín từng đứng, nhìn về hướng quê hương.","doc":11}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","Báo Thanh Niên, “Nhà của Bác Hồ ở Thái Lan – di tích thú vị không phải ai cũng biết” – https://thanhnien.vn/nha-cua-bac-ho-o-thai-lan-di-tich-thu-vi-khong-phai-ai-cung-biet-1851505845.htm","Ủy hội sông Mê Kông quốc tế (Mekong River Commission) – thông tin lưu vực sông Mê Kông","Nakhon Phanom province – Wikipedia tiếng Anh (đối chiếu)","VietnamPlus, “Ceremony marks 60th anniversary of Vietnamese Memorial Clock Tower in Thailand” (2020)","Bảo tàng Hồ Chí Minh"],"doc":[{"t":"Sông Mê Kông ở Nakhon Phanom: một dòng sông, ba đất nước. Chiều xuống ở Nakhon Phanom, mặt sông Mê Kông rộng mênh mông, bên kia là những dãy núi đá vôi của đất Lào. Gần một thế kỷ trước, ông Thầu Chín từng sống cách bờ sông này không xa, ban ngày làm vườn, tối đi đánh cá như bà con trong xóm. Với Người, dòng sông vừa là đường biên phải canh chừng, vừa là con đường bí mật dẫn về quê hương."},{"t":"Một buổi chiều bên bờ sông. Ai từng đứng trên bờ sông ở thành phố Nakhon Phanom lúc hoàng hôn đều khó quên cảnh ấy. Dòng Mê Kông trải rộng, nước đục màu phù sa, chảy chậm về phương nam. Bên kia sông là thị xã Thà Khẹt của Lào, và xa hơn là những dãy núi đá vôi tỉnh Khăm Muộn nhô lên sừng sững, đổi màu theo ánh chiều. Cuối những năm 1920, ông Thầu Chín sống ở bản Mạy, tức bản Na Chok, cách trung tâm thành phố chừng năm cây số. Theo lời kể mà gia đình họ Võ ở bản Mạy lưu giữ, được Báo Thanh Niên ghi lại, những ngày ấy Người sống như một người nông dân: ban ngày làm vườn, tối đi đánh cá. Với kiều bào ven sông, đánh cá là một phần của sinh kế, và cũng là cách hòa vào nhịp sống chung của cả xóm. Hẳn ít ai để ý đến một ông già đội nón trở về nhà lúc trời đã tối. Nhưng mỗi lần nhìn sang bờ bên kia, người ấy biết rằng chỉ cách một dòng sông, Tổ quốc đã ở rất gần."},{"t":"Dòng sông của sáu quốc gia. Mê Kông là một trong những con sông lớn nhất châu Á, dài hơn bốn nghìn cây số. Sông bắt nguồn từ cao nguyên Tây Tạng, chảy qua Trung Quốc, nơi nó được gọi là Lan Thương, rồi qua Myanmar, Lào, Thái Lan, Campuchia, trước khi đổ ra biển ở Việt Nam. Ở hạ lưu, người Việt gọi sông là Cửu Long, sông Chín Rồng, vì dòng chảy tỏa ra nhiều cửa trước khi vào biển. Đoạn sông chảy qua Nakhon Phanom là đường biên giới tự nhiên giữa Thái Lan và Lào. Mỗi năm, sông có hai gương mặt. Mùa mưa, nước dâng cao, cuồn cuộn phù sa, mặt sông rộng hẳn ra. Mùa khô, nước rút, lộ ra những bãi cát, dải đá giữa dòng. Đời sống của cư dân hai bờ, cả người Thái, người Lào lẫn người Việt, gắn chặt với nhịp lên xuống ấy: đánh cá, trồng rau trên bãi bồi, đi lại bằng thuyền. Tên Nakhon Phanom trong tiếng Thái có nghĩa là thành phố núi, nhưng những dãy núi đá vôi nổi bật nhìn thấy từ bờ sông lại thuộc về phía Lào."},{"t":"Bạn có biết? Mê Kông là quê hương của cá tra dầu, một trong những loài cá nước ngọt lớn nhất thế giới. Có những con dài tới khoảng ba mét, nặng khoảng ba trăm ki lô gam. Loài cá này nay đang bị đe dọa nghiêm trọng."},{"t":"Bờ bên kia: đất Lào dưới quyền Pháp. Năm 1929, dòng Mê Kông ở Nakhon Phanom không chỉ ngăn cách hai vùng đất. Nó ngăn cách một vương quốc độc lập với một vùng thuộc địa. Sau cuộc xung đột Pháp – Xiêm năm 1893, Xiêm phải nhường cho Pháp vùng đất phía đông sông Mê Kông. Lào dần bị sáp nhập vào Liên bang Đông Dương thuộc Pháp, và dòng sông trở thành đường biên giữa Xiêm với thuộc địa Pháp. Thà Khẹt, thị xã nằm ngay bờ bên kia, là một trung tâm hành chính và buôn bán của chính quyền thực dân ở miền trung Lào. Thời ấy, nhiều người Việt sinh sống ở Thà Khẹt, làm thợ, làm công chức, buôn bán. Đứng ở bờ Xiêm, ông Thầu Chín nhìn sang một vùng đất nằm dưới cùng bộ máy cai trị đang áp bức quê hương mình. Chính quyền và mật thám Pháp ở bên kia có thể dõi theo những gì diễn ra ở bờ bên này. Vì thế, sống bên sông vừa là cơ hội, vừa là thử thách: gần quê hương hơn bao giờ hết, nhưng cũng gần kẻ thù hơn bao giờ hết."},{"t":"Con đường bí mật về quê hương. Chính vị trí ấy khiến các xóm Việt kiều ven Mê Kông có ý nghĩa đặc biệt. Từ Nakhon Phanom qua sông là đất Lào. Từ Thà Khẹt đi về phía đông, vượt dãy Trường Sơn, là tới các tỉnh miền Trung Việt Nam như Quảng Bình, Hà Tĩnh, Nghệ An. Đó là con đường ngắn nhất nối các xóm Việt kiều ở đông bắc Xiêm với quê hương. Theo con đường ấy, sách báo, tài liệu cách mạng được bí mật chuyển về trong nước. Cũng theo con đường ấy, những thanh niên yêu nước từ Nghệ An, Hà Tĩnh tìm sang Xiêm để học tập, được giác ngộ rồi trở về hoạt động. Mỗi chuyến đi đều nguy hiểm: phải qua sông, qua những trạm canh của Pháp, băng rừng, vượt núi. Trong hơn một năm ở Xiêm, ông Thầu Chín góp phần củng cố đường dây liên lạc này, biến những xóm nhỏ bên sông thành hậu cứ của phong trào. Những bước chân của Người qua các tỉnh Isan, kể ở chuyên đề Những chặng đường đi bộ, đều hướng về đầu mối quan trọng này."},{"t":"Bên dòng sông, chờ thời cơ. Bên bờ Mê Kông, tin tức từ quê nhà đến với ông Thầu Chín qua những người đi lại trên con đường bí mật. Năm 1929, những tin ấy báo hiệu một bước ngoặt: trong nước đã xuất hiện ba tổ chức cộng sản hoạt động riêng rẽ, đòi hỏi phải sớm thống nhất. Cuối năm ấy, Người rời Xiêm sang Hồng Kông, để đầu năm 1930 chủ trì hội nghị hợp nhất ở Cửu Long. Câu chuyện này được kể kỹ ở chuyên đề Tin từ quê nhà và chuyến đi cuối năm 1929. Điều đáng nói là dù đã ở rất gần, Người vẫn chưa thể về nước qua dòng sông này. Phải hơn mười một năm sau, ngày 28/1/1941, Người mới đặt chân trở lại Tổ quốc. Lần ấy, Người không vượt Mê Kông mà qua cột mốc 108 trên biên giới Việt – Trung ở Cao Bằng. Dòng sông ở Nakhon Phanom vì thế là nơi Người đứng gần quê hương nhất trong nhiều năm bôn ba, nhưng vẫn phải kiên nhẫn chờ đợi thời cơ."},{"t":"Nghĩa tình bên kia sông. Con đường qua Lào không chỉ là một tuyến liên lạc. Nó còn gắn với tình nghĩa giữa hai dân tộc Việt, Lào cùng chung cảnh bị thực dân Pháp đô hộ. Những năm sau này, trong cuộc kháng chiến chống Pháp rồi chống Mỹ, dãy Trường Sơn và các tỉnh miền trung Lào, trong đó có Khăm Muộn, trở thành nơi hai dân tộc sát cánh bên nhau. Người luôn trân trọng mối tình ấy. Trong những lời thơ về tình đoàn kết Việt – Lào, Người đã nhắc tên hai dòng sông lớn: sông Hồng và chính dòng Mê Kông, mà người Việt gọi là Cửu Long. Đọc những câu thơ ấy bên bờ sông Nakhon Phanom, người ta có thể hình dung ông Thầu Chín năm nào, đứng nhìn sang bờ Lào, nơi con đường về quê hương đi qua những bản làng của người Lào. Tình cảm ấy không đến từ sách vở, mà từ chính những năm tháng Người sống gần gũi với hai bờ sông."},{"t":"Thương nhau mấy núi cũng trèo, / Mấy sông cũng lội, mấy đèo cũng qua. / Việt – Lào hai nước chúng ta, / Tình sâu hơn nước Hồng Hà, Cửu Long. — Chủ tịch Hồ Chí Minh"},{"t":"Bạn có biết? Rời xứ sở bên sông Mê Kông, con sông mà ở hạ lưu người Việt gọi là Cửu Long, ông Thầu Chín đi tới Cửu Long ở Hương Cảng để chủ trì hội nghị hợp nhất đầu năm 1930. Hai địa danh ấy đều viết bằng hai chữ Hán 九龍, nghĩa là chín con rồng."},{"t":"Mùa lễ hội trên sông. Ngày nay, dòng Mê Kông ở Nakhon Phanom vẫn là trung tâm của đời sống thành phố. Con đường ven sông là nơi người dân tập thể dục, đi dạo mỗi chiều. Hằng năm, vào dịp kết thúc mùa an cư của Phật giáo, thường rơi vào tháng Mười dương lịch, Nakhon Phanom tổ chức lễ hội thả thuyền lửa trên sông. Những con thuyền kết đèn rực rỡ trôi trên mặt nước đêm, thu hút du khách từ khắp nơi. Người Việt ở Nakhon Phanom cũng góp phần vào nhịp sống ven sông ấy. Nhiều gia đình kiều bào mở quán ăn, cửa hàng, giữ những món ăn Việt được người Thái yêu thích. Họ vẫn nhớ rằng thế hệ ông bà mình từng sống bên con sông này trong những năm tháng khó khăn nhất, và từng che chở một người sau này trở thành Chủ tịch nước Việt Nam. Dòng sông chứng kiến tất cả, lặng lẽ chảy qua gần một thế kỷ, từ những chuyến vượt sông bí mật năm xưa đến những đoàn du khách thong thả ngắm hoàng hôn."},{"t":"Dấu tích hôm nay: cây cầu và tháp đồng hồ. Gần một thế kỷ sau những chuyến vượt sông bí mật, đoạn Mê Kông ở Nakhon Phanom đã có cầu Hữu nghị Thái – Lào thứ ba nối sang Thà Khẹt, khánh thành năm 2011. Từ Thà Khẹt, đường bộ đi về phía đông qua cặp cửa khẩu Na Phàu – Cha Lo để vào tỉnh Quảng Bình. Con đường năm xưa phải lặn lội nhiều ngày, nay du khách Việt Nam có thể đi chỉ trong một ngày đường để tới thăm nhà lưu niệm ở bản Mạy. Ngay trung tâm thành phố Nakhon Phanom còn có tháp đồng hồ do cộng đồng người Việt dựng năm 1960. Năm 2020, lễ kỷ niệm sáu mươi năm công trình được tổ chức trang trọng. Tháp đồng hồ, ngôi nhà ở bản Mạy và cây cầu hữu nghị cùng kể một câu chuyện dài về người Việt bên dòng Mê Kông. Trong gian trưng bày của bảo tàng, dãy núi đá vôi Khăm Muộn phía xa và dòng sông được tái hiện để khách đứng ở nơi ông Thầu Chín từng đứng, nhìn về hướng quê hương."}],"so_chu":1692}],"do_vat":[{"id":"well@9.0,6.0","x":9,"y":0.25,"z":6,"loai":"well","ten":"Giếng nước","tieu_de":"Chiếc giếng của xóm Việt kiều","text":"Giữa vùng đông bắc Xiêm La — nay là khu vực Isan của Thái Lan — khí hậu chia hai mùa rõ rệt: mùa mưa ngắn ngủi và mùa khô kéo dài suốt nhiều tháng, khi ruộng đồng nứt nẻ và nước sinh hoạt trở thành mối lo thường trực của mọi gia đình. Với những xóm Việt kiều nghèo sống rải rác quanh các tỉnh Phichit, Udon Thani, Sakon Nakhon, Nakhon Phanom, một chiếc giếng đào tay — miệng giếng be bằng đất nện hoặc xếp đá, thành giếng sâu vài mét tới mạch nước ngầm — là tài sản chung quý giá, nơi cả xóm ngày ngày ra gánh từng đôi nước về đổ vào chum, vại dự trữ dùng dần.\n\nTháng 7 năm 1928, Nguyễn Ái Quốc đặt chân tới Xiêm, lấy tên Thầu Chín, hoà mình vào đời sống của những xóm Việt kiều ấy. Ông không đứng ở vị trí một người khách được trọng vọng riêng, mà sống, ăn, làm hệt như một người trong xóm: đội nón lá, đi dép hoặc đi chân đất, cùng bà con ra đồng cày cấy, dựng nhà, và tham gia đào giếng lấy nước ngọt cho cả xóm dùng chung. Đào giếng là việc nặng nhọc, phải xắn từng lớp đất sâu dần, be thành cẩn thận để giếng khỏi sập, rồi chờ nước trong mới múc lên được — việc không phân biệt sang hèn, ai cũng phải góp sức.\n\nTrong khuôn viên nhà lưu niệm Hồ Chí Minh dựng tại bản Mạy (Na Chok), ngoại ô thành phố Nakhon Phanom ngày nay, vẫn còn một chiếc giếng nhỏ được gìn giữ đúng vị trí cũ. Theo lời kể được lưu truyền trong cộng đồng kiều bào và ghi nhận tại khu di tích, đây chính là chiếc giếng mà ông Thầu Chín cùng bà con đào để lấy nước dùng hằng ngày trong thời gian sống tại đây. Chiếc giếng dựng lại trong gian trưng bày của bảo tàng số hôm nay được đặt để gợi nhắc công việc cụ thể ấy, bên cạnh ngôi nhà tranh phục dựng theo đúng bố cục khu lưu niệm thật ở bản Mạy.\n\nMột chi tiết nhỏ như chiếc giếng lại nói lên nhiều điều về cách một nhà cách mạng gây dựng lòng tin nơi nhân dân xa xứ. Không phải bằng lời hô hào suông, ông Thầu Chín chọn cách chứng minh bằng chính đôi tay mình: cùng đổ mồ hôi, cùng chịu nắng mưa, cùng lo cái ăn cái uống hằng ngày với bà con trước khi nói tới chuyện lớn hơn — đoàn kết, dạy chữ, hướng về Tổ quốc. Từ những việc thiết thực như thế, kiều bào dần tin cậy và gắn bó với người đồng hương mang tên Thầu Chín, để những buổi ông nói chuyện về đất nước sau này được đón nhận một cách tự nhiên.\n\nNgày nay, nhà lưu niệm ở bản Mạy cùng khu tưởng niệm tại Udon Thani là hai địa chỉ được cộng đồng người Việt tại Thái Lan và chính quyền địa phương gìn giữ cẩn thận, đón khách trong và ngoài nước tới tham quan quanh năm. Chiếc giếng nhỏ nằm khiêm nhường trong sân vườn, cạnh ngôi nhà sàn mái lá, hàng dừa và luống rau, vẫn là một trong những chứng tích cụ thể và giàu sức gợi nhất về quãng thời gian Người sống giữa lòng dân trên đất Xiêm.","nguon":"Bảo tàng Hồ Chí Minh; Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","doc":[{"t":"Chiếc giếng của xóm Việt kiều. Giữa vùng đông bắc Xiêm La — nay là khu vực Isan của Thái Lan — khí hậu chia hai mùa rõ rệt: mùa mưa ngắn ngủi và mùa khô kéo dài suốt nhiều tháng, khi ruộng đồng nứt nẻ và nước sinh hoạt trở thành mối lo thường trực của mọi gia đình. Với những xóm Việt kiều nghèo sống rải rác quanh các tỉnh Phichit, Udon Thani, Sakon Nakhon, Nakhon Phanom, một chiếc giếng đào tay — miệng giếng be bằng đất nện hoặc xếp đá, thành giếng sâu vài mét tới mạch nước ngầm — là tài sản chung quý giá, nơi cả xóm ngày ngày ra gánh từng đôi nước về đổ vào chum, vại dự trữ dùng dần."},{"t":"Tháng 7 năm 1928, Nguyễn Ái Quốc đặt chân tới Xiêm, lấy tên Thầu Chín, hoà mình vào đời sống của những xóm Việt kiều ấy. Ông không đứng ở vị trí một người khách được trọng vọng riêng, mà sống, ăn, làm hệt như một người trong xóm: đội nón lá, đi dép hoặc đi chân đất, cùng bà con ra đồng cày cấy, dựng nhà, và tham gia đào giếng lấy nước ngọt cho cả xóm dùng chung. Đào giếng là việc nặng nhọc, phải xắn từng lớp đất sâu dần, be thành cẩn thận để giếng khỏi sập, rồi chờ nước trong mới múc lên được — việc không phân biệt sang hèn, ai cũng phải góp sức."},{"t":"Trong khuôn viên nhà lưu niệm Hồ Chí Minh dựng tại bản Mạy (Na Chok), ngoại ô thành phố Nakhon Phanom ngày nay, vẫn còn một chiếc giếng nhỏ được gìn giữ đúng vị trí cũ. Theo lời kể được lưu truyền trong cộng đồng kiều bào và ghi nhận tại khu di tích, đây chính là chiếc giếng mà ông Thầu Chín cùng bà con đào để lấy nước dùng hằng ngày trong thời gian sống tại đây. Chiếc giếng dựng lại trong gian trưng bày của bảo tàng số hôm nay được đặt để gợi nhắc công việc cụ thể ấy, bên cạnh ngôi nhà tranh phục dựng theo đúng bố cục khu lưu niệm thật ở bản Mạy."},{"t":"Một chi tiết nhỏ như chiếc giếng lại nói lên nhiều điều về cách một nhà cách mạng gây dựng lòng tin nơi nhân dân xa xứ. Không phải bằng lời hô hào suông, ông Thầu Chín chọn cách chứng minh bằng chính đôi tay mình: cùng đổ mồ hôi, cùng chịu nắng mưa, cùng lo cái ăn cái uống hằng ngày với bà con trước khi nói tới chuyện lớn hơn — đoàn kết, dạy chữ, hướng về Tổ quốc. Từ những việc thiết thực như thế, kiều bào dần tin cậy và gắn bó với người đồng hương mang tên Thầu Chín, để những buổi ông nói chuyện về đất nước sau này được đón nhận một cách tự nhiên."},{"t":"Ngày nay, nhà lưu niệm ở bản Mạy cùng khu tưởng niệm tại Udon Thani là hai địa chỉ được cộng đồng người Việt tại Thái Lan và chính quyền địa phương gìn giữ cẩn thận, đón khách trong và ngoài nước tới tham quan quanh năm. Chiếc giếng nhỏ nằm khiêm nhường trong sân vườn, cạnh ngôi nhà sàn mái lá, hàng dừa và luống rau, vẫn là một trong những chứng tích cụ thể và giàu sức gợi nhất về quãng thời gian Người sống giữa lòng dân trên đất Xiêm."},{"t":"Bạn có biết? Nhà lưu niệm Hồ Chí Minh ở bản Mạy (Nakhon Phanom) cùng khu tưởng niệm tại Udon Thani là hai di tích về Người được cộng đồng kiều bào và chính quyền Thái Lan gìn giữ nổi tiếng nhất ở nước ngoài (nguồn: Bảo tàng Hồ Chí Minh)."}],"ban_co_biet":"Nhà lưu niệm Hồ Chí Minh ở bản Mạy (Nakhon Phanom) cùng khu tưởng niệm tại Udon Thani là hai di tích về Người được cộng đồng kiều bào và chính quyền Thái Lan gìn giữ nổi tiếng nhất ở nước ngoài (nguồn: Bảo tàng Hồ Chí Minh)."},{"id":"rusted_spade_01@-2.4,-1.9","x":-2.4,"y":0.3,"z":-1.9,"loai":"rusted_spade_01","ten":"Chiếc mai đào đất","tieu_de":"Cầm mai cùng bà con","text":"Chiếc mai — lưỡi sắt bản rộng tra vào cán gỗ dài — là dụng cụ quen thuộc của nhà nông Việt Nam, dùng để xắn đất, đào mương, be bờ ruộng, đào giếng hay đắp nền nhà. Trong những xóm Việt kiều nghèo ở đông bắc Xiêm cuối thập niên 1920, khi máy móc còn xa lạ, chiếc mai cùng chiếc cuốc là hai vật bất ly thân, quyết định phần lớn công sức một gia đình bỏ ra để có ruộng cày, có nhà ở, có nước dùng.\n\nTừ tháng 7 năm 1928, ông Thầu Chín — tên gọi Nguyễn Ái Quốc dùng khi sống giữa kiều bào ở Xiêm — không đứng ngoài quan sát mà trực tiếp cầm mai lao động cùng mọi người: cùng cày cấy, đào giếng lấy nước, dựng nhà, vỡ đất trồng rau, trồng chuối quanh vườn. Ông làm việc này suốt hơn một năm, di chuyển qua nhiều tỉnh như Phichit, Udon Thani, Sakon Nakhon, Nakhon Phanom, ở đâu cũng hoà vào nhịp lao động của xóm giềng chứ không tách riêng thành một người khách.\n\nChiếc mai đặt trong gian trưng bày là vật minh họa cho công việc ấy — không phải hiện vật gốc còn giữ được, mà là hình ảnh tiêu biểu của một dụng cụ lao động phổ biến thời đó, được dựng lại để người xem hình dung cụ thể ông Thầu Chín đã làm gì mỗi ngày. Nó nhắc rằng trước khi vận động bà con hiểu về đoàn kết, về Tổ quốc, Người đã cùng họ đổ mồ hôi trên đồng ruộng, cùng chung một nhịp sống lam lũ như bất cứ người dân nào trong xóm.\n\nChính sự gần gũi ấy — sẵn sàng cầm mai, cầm cuốc như một người lao động thực thụ — đã làm nên lòng tin của kiều bào đối với người mang tên Thầu Chín. Nhiều người trong xóm khi ấy không biết ông từng là Nguyễn Ái Quốc, người đã bôn ba qua Pháp, Liên Xô, Trung Quốc; họ chỉ biết một ông già hiền lành, chăm chỉ, sống thật với mình. Nhờ vậy, những lời ông nói về việc giữ tiếng Việt, về tình cảnh đất nước, về đoàn kết giúp nhau, đều được bà con lắng nghe và tin theo một cách tự nhiên, không cần ép buộc.\n\nBài học từ chiếc mai giản dị ấy vượt ra ngoài phạm vi một xóm Việt kiều nhỏ ở Xiêm: một người làm cách mạng muốn được dân tin, trước hết phải sống cùng dân, làm cùng việc với dân. Đó cũng là nếp sống mà Người giữ suốt cuộc đời hoạt động sau này, từ những cánh đồng ở Xiêm cho tới khi đã là Chủ tịch nước, vẫn tự tay trồng rau, tát nước, thăm đồng cùng nông dân mỗi khi có dịp.\n\nNhiều năm sau, khi đã ở khu Phủ Chủ tịch tại Hà Nội, Người vẫn giữ thói quen lao động chân tay ấy: tự tay cuốc đất trồng rau quanh nhà sàn, chăm cây, cho cá ăn ở ao gần đó, coi đó là cách rèn luyện sức khoẻ và giữ mối liên hệ gần gũi với đời sống lao động bình dị. Chiếc mai cầm ở Xiêm năm 1928, vì thế, có thể xem là một trong những hình ảnh khởi đầu cho nếp sống \"cần, kiệm\" mà Người theo đuổi và răn dạy cán bộ suốt những năm về sau, khi đã trở thành người đứng đầu Nhà nước.","nguon":"Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia; Bảo tàng Hồ Chí Minh","doc":[{"t":"Cầm mai cùng bà con. Chiếc mai — lưỡi sắt bản rộng tra vào cán gỗ dài — là dụng cụ quen thuộc của nhà nông Việt Nam, dùng để xắn đất, đào mương, be bờ ruộng, đào giếng hay đắp nền nhà. Trong những xóm Việt kiều nghèo ở đông bắc Xiêm cuối thập niên 1920, khi máy móc còn xa lạ, chiếc mai cùng chiếc cuốc là hai vật bất ly thân, quyết định phần lớn công sức một gia đình bỏ ra để có ruộng cày, có nhà ở, có nước dùng."},{"t":"Từ tháng 7 năm 1928, ông Thầu Chín — tên gọi Nguyễn Ái Quốc dùng khi sống giữa kiều bào ở Xiêm — không đứng ngoài quan sát mà trực tiếp cầm mai lao động cùng mọi người: cùng cày cấy, đào giếng lấy nước, dựng nhà, vỡ đất trồng rau, trồng chuối quanh vườn. Ông làm việc này suốt hơn một năm, di chuyển qua nhiều tỉnh như Phichit, Udon Thani, Sakon Nakhon, Nakhon Phanom, ở đâu cũng hoà vào nhịp lao động của xóm giềng chứ không tách riêng thành một người khách."},{"t":"Chiếc mai đặt trong gian trưng bày là vật minh họa cho công việc ấy — không phải hiện vật gốc còn giữ được, mà là hình ảnh tiêu biểu của một dụng cụ lao động phổ biến thời đó, được dựng lại để người xem hình dung cụ thể ông Thầu Chín đã làm gì mỗi ngày. Nó nhắc rằng trước khi vận động bà con hiểu về đoàn kết, về Tổ quốc, Người đã cùng họ đổ mồ hôi trên đồng ruộng, cùng chung một nhịp sống lam lũ như bất cứ người dân nào trong xóm."},{"t":"Chính sự gần gũi ấy — sẵn sàng cầm mai, cầm cuốc như một người lao động thực thụ — đã làm nên lòng tin của kiều bào đối với người mang tên Thầu Chín. Nhiều người trong xóm khi ấy không biết ông từng là Nguyễn Ái Quốc, người đã bôn ba qua Pháp, Liên Xô, Trung Quốc; họ chỉ biết một ông già hiền lành, chăm chỉ, sống thật với mình. Nhờ vậy, những lời ông nói về việc giữ tiếng Việt, về tình cảnh đất nước, về đoàn kết giúp nhau, đều được bà con lắng nghe và tin theo một cách tự nhiên, không cần ép buộc."},{"t":"Bài học từ chiếc mai giản dị ấy vượt ra ngoài phạm vi một xóm Việt kiều nhỏ ở Xiêm: một người làm cách mạng muốn được dân tin, trước hết phải sống cùng dân, làm cùng việc với dân. Đó cũng là nếp sống mà Người giữ suốt cuộc đời hoạt động sau này, từ những cánh đồng ở Xiêm cho tới khi đã là Chủ tịch nước, vẫn tự tay trồng rau, tát nước, thăm đồng cùng nông dân mỗi khi có dịp."},{"t":"Nhiều năm sau, khi đã ở khu Phủ Chủ tịch tại Hà Nội, Người vẫn giữ thói quen lao động chân tay ấy: tự tay cuốc đất trồng rau quanh nhà sàn, chăm cây, cho cá ăn ở ao gần đó, coi đó là cách rèn luyện sức khoẻ và giữ mối liên hệ gần gũi với đời sống lao động bình dị. Chiếc mai cầm ở Xiêm năm 1928, vì thế, có thể xem là một trong những hình ảnh khởi đầu cho nếp sống \"cần, kiệm\" mà Người theo đuổi và răn dạy cán bộ suốt những năm về sau, khi đã trở thành người đứng đầu Nhà nước."},{"t":"Bạn có biết? Suốt hơn một năm ở Xiêm, ông Thầu Chín di chuyển liên tục qua bốn tỉnh Phichit, Udon Thani, Sakon Nakhon, Nakhon Phanom để gây dựng cơ sở trong kiều bào (nguồn: Hồ Chí Minh – Biên niên tiểu sử, tập 1)."}],"ban_co_biet":"Suốt hơn một năm ở Xiêm, ông Thầu Chín di chuyển liên tục qua bốn tỉnh Phichit, Udon Thani, Sakon Nakhon, Nakhon Phanom để gây dựng cơ sở trong kiều bào (nguồn: Hồ Chí Minh – Biên niên tiểu sử, tập 1)."},{"id":"wooden_bucket_02@3.6,2.6","x":3.6,"y":0.3,"z":2.6,"loai":"wooden_bucket_02","ten":"Thùng gỗ múc nước","tieu_de":"Những gánh nước trong xóm","text":"Trước khi có nước máy, hầu như mọi gia đình ở nông thôn Việt Nam lẫn các xóm Việt kiều bên Xiêm đều dùng thùng gỗ hoặc thùng tôn buộc quang gánh để múc và chuyển nước từ giếng về nhà. Thùng gỗ ghép từ các thanh ván nhỏ, đóng đai bằng vòng tre hoặc kim loại, tuy nặng hơn thùng nhựa hiện đại nhưng bền, chịu được va đập khi kéo lên kéo xuống lòng giếng sâu mỗi ngày.\n\nỞ các xóm Việt kiều vùng đông bắc Xiêm cuối những năm 1920, mỗi sáng và mỗi chiều đều đặn có người ra giếng chung múc nước, gánh về đổ đầy chum, vại trong nhà để dùng nấu ăn, tắm giặt suốt cả ngày. Đây là công việc lặp đi lặp lại, tưởng nhỏ nhặt nhưng chiếm không ít thời gian và sức lực của mỗi gia đình, nhất là trong mùa khô khi mực nước giếng xuống thấp.\n\nChiếc thùng gỗ trong gian trưng bày là vật minh họa cho nhịp sống thường nhật ấy — nhịp sống mà ông Thầu Chín chia sẻ trọn vẹn khi sống giữa bà con. Nhiều nguồn tư liệu về Người trong giai đoạn này đều nhấn mạnh một điểm chung: ông không nhận sự phục dịch riêng, không để bà con gánh nước, nấu cơm hộ mình như với một vị khách quý, mà tự tay làm lấy mọi việc sinh hoạt như bất kỳ ai trong xóm.\n\nNếp sống tự phục vụ, không đòi hỏi đặc quyền ấy không phải ngẫu nhiên mà có. Nó bắt nguồn từ chính những năm tháng bôn ba khắp nơi trước đó — làm đủ nghề để tự nuôi thân, từ phụ bếp trên tàu biển đến làm thợ ảnh, cạo tuyết — nên khi tới sống giữa kiều bào ở Xiêm, việc tự gánh nước, tự lo bữa ăn với ông là điều hết sức bình thường, không có gì phải bận tâm.\n\nKể từ khi rời bến cảng Nhà Rồng năm 1911 làm phụ bếp trên một con tàu buôn của Pháp, Nguyễn Ái Quốc đã trải qua đủ loại công việc chân tay nặng nhọc ở nhiều nước: cào tuyết và đốt lò ở nước Anh, làm vườn, rửa bát trong các khách sạn, phụ giúp một hiệu ảnh tại Paris để có tiền trang trải trong lúc hoạt động cách mạng. Chuỗi năm tháng lao động ấy hun đúc nên một con người không phân biệt việc gì là hèn kém, sẵn sàng xắn tay làm bất cứ việc gì cần thiết trước mắt, kể cả việc nhỏ như xách một thùng nước từ giếng về nhà.\n\nChi tiết giản dị này, cùng với chiếc chum đựng nước và chiếc giếng đặt gần đó trong gian trưng bày, ghép lại thành một bức tranh trọn vẹn về sinh hoạt hằng ngày của một xóm Việt kiều nghèo bên đất Xiêm — nơi một nhà cách mạng đã chọn sống không khác gì người dân thường, để rồi từ chính cuộc sống chung ấy, gây dựng được niềm tin cho những việc lớn lao hơn về sau.\n\nBa đồ vật ấy — giếng, chum, thùng gánh nước — vì vậy nên được nhìn như một chuỗi liền mạch của cùng một công việc thường nhật, chứ không phải những vật dụng rời rạc: nước được đào lên từ giếng, gánh về bằng thùng, rồi trữ lại trong chum để dùng dần. Với một xóm nghèo chưa có nước máy, chuỗi công việc lặp lại mỗi ngày ấy chiếm không ít công sức, và việc ông Thầu Chín cùng gánh vác phần việc đó với bà con, không nề hà, là một trong những hình ảnh giản dị nhưng chân thực nhất về Người trong giai đoạn sống ở Xiêm.","nguon":"Bảo tàng Hồ Chí Minh; Hồ Chí Minh – Biên niên tiểu sử, tập 1","doc":[{"t":"Những gánh nước trong xóm. Trước khi có nước máy, hầu như mọi gia đình ở nông thôn Việt Nam lẫn các xóm Việt kiều bên Xiêm đều dùng thùng gỗ hoặc thùng tôn buộc quang gánh để múc và chuyển nước từ giếng về nhà. Thùng gỗ ghép từ các thanh ván nhỏ, đóng đai bằng vòng tre hoặc kim loại, tuy nặng hơn thùng nhựa hiện đại nhưng bền, chịu được va đập khi kéo lên kéo xuống lòng giếng sâu mỗi ngày."},{"t":"Ở các xóm Việt kiều vùng đông bắc Xiêm cuối những năm 1920, mỗi sáng và mỗi chiều đều đặn có người ra giếng chung múc nước, gánh về đổ đầy chum, vại trong nhà để dùng nấu ăn, tắm giặt suốt cả ngày. Đây là công việc lặp đi lặp lại, tưởng nhỏ nhặt nhưng chiếm không ít thời gian và sức lực của mỗi gia đình, nhất là trong mùa khô khi mực nước giếng xuống thấp."},{"t":"Chiếc thùng gỗ trong gian trưng bày là vật minh họa cho nhịp sống thường nhật ấy — nhịp sống mà ông Thầu Chín chia sẻ trọn vẹn khi sống giữa bà con. Nhiều nguồn tư liệu về Người trong giai đoạn này đều nhấn mạnh một điểm chung: ông không nhận sự phục dịch riêng, không để bà con gánh nước, nấu cơm hộ mình như với một vị khách quý, mà tự tay làm lấy mọi việc sinh hoạt như bất kỳ ai trong xóm."},{"t":"Nếp sống tự phục vụ, không đòi hỏi đặc quyền ấy không phải ngẫu nhiên mà có. Nó bắt nguồn từ chính những năm tháng bôn ba khắp nơi trước đó — làm đủ nghề để tự nuôi thân, từ phụ bếp trên tàu biển đến làm thợ ảnh, cạo tuyết — nên khi tới sống giữa kiều bào ở Xiêm, việc tự gánh nước, tự lo bữa ăn với ông là điều hết sức bình thường, không có gì phải bận tâm."},{"t":"Kể từ khi rời bến cảng Nhà Rồng năm 1911 làm phụ bếp trên một con tàu buôn của Pháp, Nguyễn Ái Quốc đã trải qua đủ loại công việc chân tay nặng nhọc ở nhiều nước: cào tuyết và đốt lò ở nước Anh, làm vườn, rửa bát trong các khách sạn, phụ giúp một hiệu ảnh tại Paris để có tiền trang trải trong lúc hoạt động cách mạng. Chuỗi năm tháng lao động ấy hun đúc nên một con người không phân biệt việc gì là hèn kém, sẵn sàng xắn tay làm bất cứ việc gì cần thiết trước mắt, kể cả việc nhỏ như xách một thùng nước từ giếng về nhà."},{"t":"Chi tiết giản dị này, cùng với chiếc chum đựng nước và chiếc giếng đặt gần đó trong gian trưng bày, ghép lại thành một bức tranh trọn vẹn về sinh hoạt hằng ngày của một xóm Việt kiều nghèo bên đất Xiêm — nơi một nhà cách mạng đã chọn sống không khác gì người dân thường, để rồi từ chính cuộc sống chung ấy, gây dựng được niềm tin cho những việc lớn lao hơn về sau."},{"t":"Ba đồ vật ấy — giếng, chum, thùng gánh nước — vì vậy nên được nhìn như một chuỗi liền mạch của cùng một công việc thường nhật, chứ không phải những vật dụng rời rạc: nước được đào lên từ giếng, gánh về bằng thùng, rồi trữ lại trong chum để dùng dần. Với một xóm nghèo chưa có nước máy, chuỗi công việc lặp lại mỗi ngày ấy chiếm không ít công sức, và việc ông Thầu Chín cùng gánh vác phần việc đó với bà con, không nề hà, là một trong những hình ảnh giản dị nhưng chân thực nhất về Người trong giai đoạn sống ở Xiêm."}]},{"id":"jar@3.8,1.8","x":3.8,"y":0.3,"z":1.8,"loai":"jar","ten":"Chum đựng nước","tieu_de":"Chum nước bên hiên nhà","text":"Chiếc chum sành cao ngang thắt lưng, miệng loe, thân tròn, đặt ngay bên hiên hay góc sân là hình ảnh quen thuộc của cả nhà người Việt lẫn nhà người Thái vùng Isan suốt nhiều thế hệ. Ở một vùng đất mùa khô kéo dài tới sáu, bảy tháng mỗi năm, một chiếc chum lớn đựng đầy nước mưa hoặc nước giếng dự trữ gần như là vật dụng bắt buộc phải có trong mỗi gia đình, để không bị động khi nguồn nước tự nhiên cạn dần.\n\nTrong những xóm Việt kiều ở đông bắc Xiêm cuối thập niên 1920 — nơi ông Thầu Chín sống và lao động cùng bà con — chum nước còn có thêm một vai trò khác: nó là nơi lọc bớt cặn, để nước lắng trong trước khi dùng nấu ăn, một kinh nghiệm dân gian đơn giản nhưng thiết thực trong điều kiện chưa có hệ thống lọc nước hiện đại. Mỗi lần gánh nước từ giếng về, người ta đổ vào chum, đậy nắp lá hoặc tấm ván mỏng để giữ nước sạch, tránh côn trùng, lá cây rơi vào.\n\nChiếc chum trong gian trưng bày là vật minh họa, được đặt cạnh ngôi nhà gỗ phục dựng để tái hiện nếp sinh hoạt của một gia đình Việt kiều điển hình cuối những năm 1920 tại vùng này. Nó không tách rời khỏi câu chuyện về chiếc giếng gần đó — nơi tương truyền chính ông Thầu Chín đã cùng bà con đào để lấy nguồn nước cho cả xóm — mà là mắt xích tiếp theo trong chuỗi công việc hằng ngày: đào giếng, gánh nước, trữ vào chum, rồi mới có nước sạch để dùng.\n\nVới một người từng đi khắp năm châu bốn biển như Nguyễn Ái Quốc, việc trở về sống giữa một xóm nghèo, quen với những vật dụng giản đơn như chiếc chum sành, không phải là một sự hạ mình miễn cưỡng mà là lựa chọn có chủ đích. Chỉ khi hiểu tường tận đời sống vật chất nhỏ nhặt nhất của người dân — từ nguồn nước, bữa ăn, tới chỗ ở — người làm cách mạng mới có thể nói những điều thiết thực, đúng với nỗi lo và mong mỏi thực sự của họ, thay vì những khẩu hiệu xa rời cuộc sống.\n\nNgày nay, trong khuôn viên nhà lưu niệm ở bản Mạy, khung cảnh một nếp nhà Việt kiều xưa — với giếng nước, chum sành, hàng dừa, vườn rau — vẫn được giữ gìn để du khách hình dung được không gian sống giản dị mà ông Thầu Chín đã gắn bó trong hơn một năm trên đất Xiêm.\n\nVùng Isan nằm trên một cao nguyên khô, xa biển, chịu kiểu khí hậu nhiệt đới gió mùa với mùa mưa ngắn và mùa khô kéo dài, đất đai phần lớn là đất cát pha, giữ nước kém hơn nhiều vùng đồng bằng khác của Đông Nam Á. Vì vậy, việc trữ nước qua chum, vại không chỉ là thói quen mà gần như là điều kiện sống còn với cả cộng đồng cư dân nơi đây, không riêng gì các xóm Việt kiều. Chiếc chum đặt cạnh ngôi nhà phục dựng trong gian trưng bày, vì thế, cũng là một chi tiết gắn liền với không gian ngôi nhà của ông Thầu Chín được giới thiệu ở bảng riêng trong gian này (xem chuyên đề Ngôi nhà của \"Thầu Chín\").","nguon":"Bảo tàng Hồ Chí Minh","doc":[{"t":"Chum nước bên hiên nhà. Chiếc chum sành cao ngang thắt lưng, miệng loe, thân tròn, đặt ngay bên hiên hay góc sân là hình ảnh quen thuộc của cả nhà người Việt lẫn nhà người Thái vùng Isan suốt nhiều thế hệ. Ở một vùng đất mùa khô kéo dài tới sáu, bảy tháng mỗi năm, một chiếc chum lớn đựng đầy nước mưa hoặc nước giếng dự trữ gần như là vật dụng bắt buộc phải có trong mỗi gia đình, để không bị động khi nguồn nước tự nhiên cạn dần."},{"t":"Trong những xóm Việt kiều ở đông bắc Xiêm cuối thập niên 1920 — nơi ông Thầu Chín sống và lao động cùng bà con — chum nước còn có thêm một vai trò khác: nó là nơi lọc bớt cặn, để nước lắng trong trước khi dùng nấu ăn, một kinh nghiệm dân gian đơn giản nhưng thiết thực trong điều kiện chưa có hệ thống lọc nước hiện đại. Mỗi lần gánh nước từ giếng về, người ta đổ vào chum, đậy nắp lá hoặc tấm ván mỏng để giữ nước sạch, tránh côn trùng, lá cây rơi vào."},{"t":"Chiếc chum trong gian trưng bày là vật minh họa, được đặt cạnh ngôi nhà gỗ phục dựng để tái hiện nếp sinh hoạt của một gia đình Việt kiều điển hình cuối những năm 1920 tại vùng này. Nó không tách rời khỏi câu chuyện về chiếc giếng gần đó — nơi tương truyền chính ông Thầu Chín đã cùng bà con đào để lấy nguồn nước cho cả xóm — mà là mắt xích tiếp theo trong chuỗi công việc hằng ngày: đào giếng, gánh nước, trữ vào chum, rồi mới có nước sạch để dùng."},{"t":"Với một người từng đi khắp năm châu bốn biển như Nguyễn Ái Quốc, việc trở về sống giữa một xóm nghèo, quen với những vật dụng giản đơn như chiếc chum sành, không phải là một sự hạ mình miễn cưỡng mà là lựa chọn có chủ đích. Chỉ khi hiểu tường tận đời sống vật chất nhỏ nhặt nhất của người dân — từ nguồn nước, bữa ăn, tới chỗ ở — người làm cách mạng mới có thể nói những điều thiết thực, đúng với nỗi lo và mong mỏi thực sự của họ, thay vì những khẩu hiệu xa rời cuộc sống."},{"t":"Ngày nay, trong khuôn viên nhà lưu niệm ở bản Mạy, khung cảnh một nếp nhà Việt kiều xưa — với giếng nước, chum sành, hàng dừa, vườn rau — vẫn được giữ gìn để du khách hình dung được không gian sống giản dị mà ông Thầu Chín đã gắn bó trong hơn một năm trên đất Xiêm."},{"t":"Vùng Isan nằm trên một cao nguyên khô, xa biển, chịu kiểu khí hậu nhiệt đới gió mùa với mùa mưa ngắn và mùa khô kéo dài, đất đai phần lớn là đất cát pha, giữ nước kém hơn nhiều vùng đồng bằng khác của Đông Nam Á. Vì vậy, việc trữ nước qua chum, vại không chỉ là thói quen mà gần như là điều kiện sống còn với cả cộng đồng cư dân nơi đây, không riêng gì các xóm Việt kiều. Chiếc chum đặt cạnh ngôi nhà phục dựng trong gian trưng bày, vì thế, cũng là một chi tiết gắn liền với không gian ngôi nhà của ông Thầu Chín được giới thiệu ở bảng riêng trong gian này (xem chuyên đề Ngôi nhà của \"Thầu Chín\")."}]},{"id":"phan@-1.6,-0.9","x":-1.6,"y":1.2,"z":-0.9,"loai":"phan","ten":"Chiếc phản gỗ","tieu_de":"Chỗ nằm của ông Thầu Chín","text":"Phản là tấm ván gỗ dày, bốn chân thấp, vừa dùng để ngồi tiếp khách ban ngày, vừa trải chiếu làm chỗ ngủ ban đêm — một vật dụng đa năng phổ biến trong những ngôi nhà nông thôn Việt Nam và cả nhà của kiều bào nơi đất khách, khi giường tủ kiểu thành thị còn là thứ xa xỉ. Một tấm phản mộc, không sơn son thếp vàng, chỉ cần đủ chắc chắn và phẳng phiu, đã là chỗ nghỉ ngơi tươm tất nhất trong nhiều gia đình.\n\nNhững nơi ông Thầu Chín từng ở trong hơn một năm sống tại Xiêm — từ Phichit, Udon Thani, Sakon Nakhon đến Nakhon Phanom — đều là những ngôi nhà giản dị như nhà của bà con trong xóm: vài gian gỗ, mái lá, không có phòng riêng biệt tách khỏi sinh hoạt chung. Chỗ nằm khi thì trên giường tre, khi thì trên một tấm phản gỗ mộc mạc, tùy theo điều kiện của gia đình cưu mang ông tại mỗi nơi ông dừng chân.\n\nChiếc phản trong gian trưng bày là vật minh họa, tái hiện nếp sống ấy. Việc không có đồ đạc riêng quý giá, không có chỗ ở tách biệt hẳn khỏi bà con, vừa xuất phát từ điều kiện sống chung khó khăn của cả xóm, vừa là một lựa chọn có tính toán: sống lẫn giữa kiều bào giúp Người hiểu sâu hơn đời sống, tâm tư của họ, đồng thời tránh gây sự chú ý cho mạng lưới mật thám Pháp vốn có tai mắt cả trên đất Xiêm, nơi vẫn thường xuyên theo dõi các cộng đồng người Việt hải ngoại có biểu hiện hoạt động yêu nước.\n\nKhông phải đêm nào ông cũng có một chỗ ngủ ổn định như vậy. Trong những chuyến đi liên tỉnh nối các cơ sở kiều bào rải rác, nhiều lúc trời tối giữa đường, không kịp tới nơi trú chân, Người còn phải nghỉ tạm trong rừng hoặc bên đường, rồi sáng hôm sau tiếp tục hành trình. So với những đêm như thế, một tấm phản gỗ trong ngôi nhà quen thuộc ở bản Mạy hay Udon Thani đã là một sự ấm áp, yên ổn đáng quý.\n\nChi tiết nhỏ về chỗ nằm này, đặt cạnh những đồ vật khác trong gian — bàn viết, đèn dầu, chum nước — góp phần dựng lại đầy đủ hơn bức tranh về cuộc sống thường nhật kham khổ mà giàu nghị lực của một nhà cách mạng đang tìm đường trở về gần Tổ quốc.\n\nViệc đổi tên, đổi chỗ ở liên tục trong suốt hành trình bôn ba — từ Nguyễn Ái Quốc, sang Lý Thụy khi hoạt động tại Quảng Châu, rồi Thầu Chín ở Xiêm, và sau này còn mang tên Tống Văn Sơn khi bị bắt giữ tại Hồng Kông năm 1931 — không phải ngẫu nhiên, mà là cách đối phó với mạng lưới mật thám của chính quyền Pháp vốn đã theo dõi Người từ những năm còn ở Paris. Một chỗ ngủ đơn sơ, không cố định, không gắn với một danh tính duy nhất, chính là một phần của chiến thuật giữ an toàn cho bản thân và cho cả những cơ sở cách mạng mà Người đang gây dựng giữa lòng kiều bào.","nguon":"Bảo tàng Hồ Chí Minh; Hồ Chí Minh – Biên niên tiểu sử, tập 1","doc":[{"t":"Chỗ nằm của ông Thầu Chín. Phản là tấm ván gỗ dày, bốn chân thấp, vừa dùng để ngồi tiếp khách ban ngày, vừa trải chiếu làm chỗ ngủ ban đêm — một vật dụng đa năng phổ biến trong những ngôi nhà nông thôn Việt Nam và cả nhà của kiều bào nơi đất khách, khi giường tủ kiểu thành thị còn là thứ xa xỉ. Một tấm phản mộc, không sơn son thếp vàng, chỉ cần đủ chắc chắn và phẳng phiu, đã là chỗ nghỉ ngơi tươm tất nhất trong nhiều gia đình."},{"t":"Những nơi ông Thầu Chín từng ở trong hơn một năm sống tại Xiêm — từ Phichit, Udon Thani, Sakon Nakhon đến Nakhon Phanom — đều là những ngôi nhà giản dị như nhà của bà con trong xóm: vài gian gỗ, mái lá, không có phòng riêng biệt tách khỏi sinh hoạt chung. Chỗ nằm khi thì trên giường tre, khi thì trên một tấm phản gỗ mộc mạc, tùy theo điều kiện của gia đình cưu mang ông tại mỗi nơi ông dừng chân."},{"t":"Chiếc phản trong gian trưng bày là vật minh họa, tái hiện nếp sống ấy. Việc không có đồ đạc riêng quý giá, không có chỗ ở tách biệt hẳn khỏi bà con, vừa xuất phát từ điều kiện sống chung khó khăn của cả xóm, vừa là một lựa chọn có tính toán: sống lẫn giữa kiều bào giúp Người hiểu sâu hơn đời sống, tâm tư của họ, đồng thời tránh gây sự chú ý cho mạng lưới mật thám Pháp vốn có tai mắt cả trên đất Xiêm, nơi vẫn thường xuyên theo dõi các cộng đồng người Việt hải ngoại có biểu hiện hoạt động yêu nước."},{"t":"Không phải đêm nào ông cũng có một chỗ ngủ ổn định như vậy. Trong những chuyến đi liên tỉnh nối các cơ sở kiều bào rải rác, nhiều lúc trời tối giữa đường, không kịp tới nơi trú chân, Người còn phải nghỉ tạm trong rừng hoặc bên đường, rồi sáng hôm sau tiếp tục hành trình. So với những đêm như thế, một tấm phản gỗ trong ngôi nhà quen thuộc ở bản Mạy hay Udon Thani đã là một sự ấm áp, yên ổn đáng quý."},{"t":"Chi tiết nhỏ về chỗ nằm này, đặt cạnh những đồ vật khác trong gian — bàn viết, đèn dầu, chum nước — góp phần dựng lại đầy đủ hơn bức tranh về cuộc sống thường nhật kham khổ mà giàu nghị lực của một nhà cách mạng đang tìm đường trở về gần Tổ quốc."},{"t":"Việc đổi tên, đổi chỗ ở liên tục trong suốt hành trình bôn ba — từ Nguyễn Ái Quốc, sang Lý Thụy khi hoạt động tại Quảng Châu, rồi Thầu Chín ở Xiêm, và sau này còn mang tên Tống Văn Sơn khi bị bắt giữ tại Hồng Kông năm 1931 — không phải ngẫu nhiên, mà là cách đối phó với mạng lưới mật thám của chính quyền Pháp vốn đã theo dõi Người từ những năm còn ở Paris. Một chỗ ngủ đơn sơ, không cố định, không gắn với một danh tính duy nhất, chính là một phần của chiến thuật giữ an toàn cho bản thân và cho cả những cơ sở cách mạng mà Người đang gây dựng giữa lòng kiều bào."}]},{"id":"table@1.8,-1.3","x":1.8,"y":1.2,"z":-1.3,"loai":"table","ten":"Bàn viết","tieu_de":"Nơi những trang báo Thân Ái được viết","text":"Một chiếc bàn gỗ mộc, bốn chân đơn giản, mặt bàn có thể đã sờn màu vì mưa nắng — đó là hình dung về nơi làm việc ban đêm của ông Thầu Chín sau một ngày lao động ngoài đồng cùng bà con Việt kiều ở đông bắc Xiêm. Không có phòng làm việc riêng, không có tủ sách đồ sộ, chỉ một góc nhà đủ ánh đèn dầu để đặt bút xuống trang giấy.\n\nBan ngày ra đồng, tối về ông Thầu Chín ngồi vào chiếc bàn ấy để làm những công việc trí óc quan trọng: viết bài cho tờ báo Thân Ái — tờ báo do chính ông cùng những người cùng chí hướng gây dựng để gắn kết kiều bào đang sống rải rác ở nhiều tỉnh vùng Isan — dịch sách sang tiếng Việt cho bà con học tập, soạn tài liệu tuyên truyền, và viết thư từ liên lạc với các cơ sở cách mạng trong nước qua ngả Lào.\n\nBáo Thân Ái ra đời trong hoàn cảnh đặc biệt: kiều bào ở Xiêm phần lớn là nông dân nghèo, trình độ chữ nghĩa hạn chế, sống tản mát nên thiếu thông tin về tình hình quê nhà. Một tờ báo nhỏ, viết bằng ngôn ngữ giản dị, dễ đọc, đã trở thành sợi dây gắn kết tinh thần giữa các xóm Việt kiều, đồng thời là kênh để những tư tưởng yêu nước, đoàn kết được truyền đi một cách kín đáo mà hiệu quả, khó bị mật thám Pháp phát hiện ngay.\n\nLời văn ông viết cho kiều bào, theo nhiều tư liệu về giai đoạn này, luôn được chọn lọc sao cho giản dị, gần gũi, để cả những người vừa biết đọc, biết viết cũng hiểu được. Đây là một nguyên tắc ông giữ xuyên suốt sự nghiệp viết báo, làm văn của mình về sau: viết cho đúng đối tượng đọc, không cầu kỳ, hoa mỹ mà xa rời người lao động bình thường — nguyên tắc bắt đầu được rèn giũa ngay từ những trang báo Thân Ái viết trên chiếc bàn gỗ nhỏ này.\n\nChiếc bàn trong gian trưng bày là vật minh họa, đặt gần chiếc đèn dầu và tập giấy ghi chép, tái hiện lại góc làm việc ban đêm giản dị ấy. Nó nhắc người xem rằng, giữa những ngày tháng lao động chân tay vất vả nơi đất khách, ông Thầu Chín vẫn không ngừng những công việc trí óc bền bỉ — viết, dịch, liên lạc — để chuẩn bị cho những bước đi lớn hơn của cách mạng Việt Nam ngay sau đó.\n\nBáo Thân Ái không phải là tờ báo đầu tiên ông đứng ra gây dựng. Trước đó, tại Paris, ông từng cùng một số nhà cách mạng thuộc địa tham gia sáng lập tờ Le Paria (Người cùng khổ) năm 1922; rồi khi sang Quảng Châu huấn luyện cán bộ cho Việt Nam Thanh niên Cách mạng Đồng chí Hội giữa những năm 1920, ông cho ra đời tờ báo Thanh Niên. Chiếc bàn viết nhỏ ở Xiêm, vì vậy, là một mắt xích tiếp theo trong cả một chặng đường làm báo cách mạng bền bỉ của Người, mỗi tờ báo gắn với một chặng bôn ba, một đối tượng độc giả khác nhau, nhưng cùng chung một mục đích: thức tỉnh và tập hợp lòng yêu nước.","nguon":"Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","doc":[{"t":"Nơi những trang báo Thân Ái được viết. Một chiếc bàn gỗ mộc, bốn chân đơn giản, mặt bàn có thể đã sờn màu vì mưa nắng — đó là hình dung về nơi làm việc ban đêm của ông Thầu Chín sau một ngày lao động ngoài đồng cùng bà con Việt kiều ở đông bắc Xiêm. Không có phòng làm việc riêng, không có tủ sách đồ sộ, chỉ một góc nhà đủ ánh đèn dầu để đặt bút xuống trang giấy."},{"t":"Ban ngày ra đồng, tối về ông Thầu Chín ngồi vào chiếc bàn ấy để làm những công việc trí óc quan trọng: viết bài cho tờ báo Thân Ái — tờ báo do chính ông cùng những người cùng chí hướng gây dựng để gắn kết kiều bào đang sống rải rác ở nhiều tỉnh vùng Isan — dịch sách sang tiếng Việt cho bà con học tập, soạn tài liệu tuyên truyền, và viết thư từ liên lạc với các cơ sở cách mạng trong nước qua ngả Lào."},{"t":"Báo Thân Ái ra đời trong hoàn cảnh đặc biệt: kiều bào ở Xiêm phần lớn là nông dân nghèo, trình độ chữ nghĩa hạn chế, sống tản mát nên thiếu thông tin về tình hình quê nhà. Một tờ báo nhỏ, viết bằng ngôn ngữ giản dị, dễ đọc, đã trở thành sợi dây gắn kết tinh thần giữa các xóm Việt kiều, đồng thời là kênh để những tư tưởng yêu nước, đoàn kết được truyền đi một cách kín đáo mà hiệu quả, khó bị mật thám Pháp phát hiện ngay."},{"t":"Lời văn ông viết cho kiều bào, theo nhiều tư liệu về giai đoạn này, luôn được chọn lọc sao cho giản dị, gần gũi, để cả những người vừa biết đọc, biết viết cũng hiểu được. Đây là một nguyên tắc ông giữ xuyên suốt sự nghiệp viết báo, làm văn của mình về sau: viết cho đúng đối tượng đọc, không cầu kỳ, hoa mỹ mà xa rời người lao động bình thường — nguyên tắc bắt đầu được rèn giũa ngay từ những trang báo Thân Ái viết trên chiếc bàn gỗ nhỏ này."},{"t":"Chiếc bàn trong gian trưng bày là vật minh họa, đặt gần chiếc đèn dầu và tập giấy ghi chép, tái hiện lại góc làm việc ban đêm giản dị ấy. Nó nhắc người xem rằng, giữa những ngày tháng lao động chân tay vất vả nơi đất khách, ông Thầu Chín vẫn không ngừng những công việc trí óc bền bỉ — viết, dịch, liên lạc — để chuẩn bị cho những bước đi lớn hơn của cách mạng Việt Nam ngay sau đó."},{"t":"Báo Thân Ái không phải là tờ báo đầu tiên ông đứng ra gây dựng. Trước đó, tại Paris, ông từng cùng một số nhà cách mạng thuộc địa tham gia sáng lập tờ Le Paria (Người cùng khổ) năm 1922; rồi khi sang Quảng Châu huấn luyện cán bộ cho Việt Nam Thanh niên Cách mạng Đồng chí Hội giữa những năm 1920, ông cho ra đời tờ báo Thanh Niên. Chiếc bàn viết nhỏ ở Xiêm, vì vậy, là một mắt xích tiếp theo trong cả một chặng đường làm báo cách mạng bền bỉ của Người, mỗi tờ báo gắn với một chặng bôn ba, một đối tượng độc giả khác nhau, nhưng cùng chung một mục đích: thức tỉnh và tập hợp lòng yêu nước."},{"t":"Bạn có biết? Báo Thân Ái do ông Thầu Chín cùng những người cùng chí hướng lập ra là một trong những kênh gắn kết kiều bào Việt Nam rải rác khắp vùng đông bắc Xiêm trong những năm 1928–1929 (nguồn: Hồ Chí Minh – Biên niên tiểu sử, tập 1)."}],"ban_co_biet":"Báo Thân Ái do ông Thầu Chín cùng những người cùng chí hướng lập ra là một trong những kênh gắn kết kiều bào Việt Nam rải rác khắp vùng đông bắc Xiêm trong những năm 1928–1929 (nguồn: Hồ Chí Minh – Biên niên tiểu sử, tập 1)."},{"id":"table@1.8,-0.8","x":1.8,"y":1.2,"z":-0.75,"loai":"table","ten":"Bàn học của lớp chữ quốc ngữ","tieu_de":"Lớp học buổi tối","text":"Sau một ngày làm đồng, khi ánh nắng đã tắt và bữa cơm tối đã xong, nhiều xóm Việt kiều ở đông bắc Xiêm lại sáng đèn cho một việc khác: lớp học chữ quốc ngữ. Bàn ghế mượn tạm từ nhà dân, có khi chỉ là những tấm ván kê tạm trên hai chiếc ghế đẩu, nhưng đó là nơi trẻ nhỏ, và cả không ít người lớn, được học đọc, học viết tiếng mẹ đẻ.\n\nNhiều kiều bào sinh sống lâu năm ở Xiêm khi ấy không biết chữ, trong khi thế hệ con cháu sinh ra và lớn lên trên đất khách lại có nguy cơ quên dần tiếng Việt, hoà lẫn vào ngôn ngữ và phong tục nơi họ đang sống. Nhận thấy điều đó, ông Thầu Chín đã đứng ra mở lớp dạy chữ quốc ngữ ngay tại nơi mình ở, tổ chức học vào buổi tối để không ảnh hưởng tới giờ lao động ban ngày của bà con.\n\nViệc dạy chữ với ông không đơn thuần là chuyện xóa mù, mà mang một ý nghĩa sâu xa hơn: biết chữ, bà con mới đọc được báo Thân Ái, mới hiểu được tin tức về quê nhà và những tài liệu mang tinh thần yêu nước được truyền tay nhau trong xóm. Ngọn lửa yêu nước, vì thế, ở nhiều người đã được nhen lên từ chính những buổi tối ngồi đánh vần bên ngọn đèn dầu, chứ không phải từ những lời hô hào to tát.\n\nChiếc bàn học trong gian trưng bày là vật minh họa cho không gian lớp học giản dị ấy — không bảng đen, không phấn trắng như trường lớp chính quy, chỉ có vài trang giấy, cây bút và lòng kiên trì của cả thầy lẫn trò. Đặt gần chiếc bàn viết nơi ông soạn báo, tài liệu, hai chiếc bàn học và bàn viết cùng gợi lên hình ảnh một con người vừa miệt mài với công việc trí óc riêng, vừa dành thời gian truyền dạy cho cộng đồng.\n\nCách làm này — gắn việc học chữ với việc giữ gìn bản sắc và khơi dậy tinh thần dân tộc — không phải là điều mới mẻ ông nghĩ ra riêng ở Xiêm, mà tiếp nối tinh thần khai dân trí từng được các nhà yêu nước Việt Nam đầu thế kỷ XX theo đuổi. Nhưng đặt trong hoàn cảnh cụ thể của một xóm Việt kiều nghèo, xa Tổ quốc hàng nghìn cây số, lớp học buổi tối bên chiếc bàn mộc ấy vẫn là một việc làm thiết thực và giàu ý nghĩa bậc nhất mà ông đã kiên trì thực hiện.\n\nNhiều năm sau, khi đã trở thành Chủ tịch nước Việt Nam Dân chủ Cộng hoà, một trong những việc đầu tiên Người phát động ngay sau ngày Tuyên ngôn Độc lập là phong trào Bình dân học vụ, dốc sức xoá nạn mù chữ cho toàn dân, coi \"giặc dốt\" là một trong ba thứ giặc cần diệt cùng giặc đói và giặc ngoại xâm. Lớp học buổi tối bên chiếc bàn mộc ở một xóm Việt kiều nhỏ tại Xiêm năm nào, vì thế, có thể xem là một trong những trải nghiệm thực tế đầu tiên nuôi dưỡng mối quan tâm bền bỉ suốt đời của Người đối với việc học chữ, học hành của nhân dân.","nguon":"Bảo tàng Hồ Chí Minh","doc":[{"t":"Lớp học buổi tối. Sau một ngày làm đồng, khi ánh nắng đã tắt và bữa cơm tối đã xong, nhiều xóm Việt kiều ở đông bắc Xiêm lại sáng đèn cho một việc khác: lớp học chữ quốc ngữ. Bàn ghế mượn tạm từ nhà dân, có khi chỉ là những tấm ván kê tạm trên hai chiếc ghế đẩu, nhưng đó là nơi trẻ nhỏ, và cả không ít người lớn, được học đọc, học viết tiếng mẹ đẻ."},{"t":"Nhiều kiều bào sinh sống lâu năm ở Xiêm khi ấy không biết chữ, trong khi thế hệ con cháu sinh ra và lớn lên trên đất khách lại có nguy cơ quên dần tiếng Việt, hoà lẫn vào ngôn ngữ và phong tục nơi họ đang sống. Nhận thấy điều đó, ông Thầu Chín đã đứng ra mở lớp dạy chữ quốc ngữ ngay tại nơi mình ở, tổ chức học vào buổi tối để không ảnh hưởng tới giờ lao động ban ngày của bà con."},{"t":"Việc dạy chữ với ông không đơn thuần là chuyện xóa mù, mà mang một ý nghĩa sâu xa hơn: biết chữ, bà con mới đọc được báo Thân Ái, mới hiểu được tin tức về quê nhà và những tài liệu mang tinh thần yêu nước được truyền tay nhau trong xóm. Ngọn lửa yêu nước, vì thế, ở nhiều người đã được nhen lên từ chính những buổi tối ngồi đánh vần bên ngọn đèn dầu, chứ không phải từ những lời hô hào to tát."},{"t":"Chiếc bàn học trong gian trưng bày là vật minh họa cho không gian lớp học giản dị ấy — không bảng đen, không phấn trắng như trường lớp chính quy, chỉ có vài trang giấy, cây bút và lòng kiên trì của cả thầy lẫn trò. Đặt gần chiếc bàn viết nơi ông soạn báo, tài liệu, hai chiếc bàn học và bàn viết cùng gợi lên hình ảnh một con người vừa miệt mài với công việc trí óc riêng, vừa dành thời gian truyền dạy cho cộng đồng."},{"t":"Cách làm này — gắn việc học chữ với việc giữ gìn bản sắc và khơi dậy tinh thần dân tộc — không phải là điều mới mẻ ông nghĩ ra riêng ở Xiêm, mà tiếp nối tinh thần khai dân trí từng được các nhà yêu nước Việt Nam đầu thế kỷ XX theo đuổi. Nhưng đặt trong hoàn cảnh cụ thể của một xóm Việt kiều nghèo, xa Tổ quốc hàng nghìn cây số, lớp học buổi tối bên chiếc bàn mộc ấy vẫn là một việc làm thiết thực và giàu ý nghĩa bậc nhất mà ông đã kiên trì thực hiện."},{"t":"Nhiều năm sau, khi đã trở thành Chủ tịch nước Việt Nam Dân chủ Cộng hoà, một trong những việc đầu tiên Người phát động ngay sau ngày Tuyên ngôn Độc lập là phong trào Bình dân học vụ, dốc sức xoá nạn mù chữ cho toàn dân, coi \"giặc dốt\" là một trong ba thứ giặc cần diệt cùng giặc đói và giặc ngoại xâm. Lớp học buổi tối bên chiếc bàn mộc ở một xóm Việt kiều nhỏ tại Xiêm năm nào, vì thế, có thể xem là một trong những trải nghiệm thực tế đầu tiên nuôi dưỡng mối quan tâm bền bỉ suốt đời của Người đối với việc học chữ, học hành của nhân dân."}]},{"id":"vintage_oil_lamp@2.1,-1.4","x":2.15,"y":1.92,"z":-1.4,"loai":"vintage_oil_lamp","ten":"Đèn dầu","tieu_de":"Ngọn đèn của những đêm dạy chữ","text":"Cuối những năm 1920, điện lưới còn là điều xa lạ với hầu hết vùng nông thôn Đông Nam Á, và các xóm Việt kiều ở đông bắc Xiêm cũng không ngoại lệ. Mọi sinh hoạt buổi tối — nấu nướng, khâu vá, học hành, hội họp — đều trông vào ánh sáng nhỏ nhoi, ấm vàng của những ngọn đèn dầu: một bầu thủy tinh hoặc sắt tây đựng dầu hỏa, bấc vải xe nhỏ xuyên qua nắp, ánh lửa chỉ đủ soi rõ một góc bàn.\n\nDưới ánh đèn dầu như thế, ông Thầu Chín đã thực hiện phần lớn những công việc trí óc quan trọng nhất trong hơn một năm sống ở Xiêm: dạy chữ quốc ngữ cho trẻ nhỏ và người lớn trong xóm vào buổi tối, dịch sách sang tiếng Việt, soạn bài cho báo Thân Ái, viết thư liên lạc với các cơ sở cách mạng trong nước. Ánh sáng yếu ớt, hay bị gió lùa tắt phụt giữa chừng, không ngăn được nhịp làm việc bền bỉ, đều đặn của ông sau mỗi ngày lao động chân tay vất vả.\n\nChiếc đèn dầu đặt trong gian trưng bày, ngay trên chiếc bàn viết, là vật minh họa mang tính biểu tượng nhiều hơn là một hiện vật cụ thể còn giữ lại được. Nó đại diện cho vô số buổi tối thầm lặng như vậy — nơi một con người từng đi khắp các châu lục, tiếp xúc với văn minh phương Tây hiện đại, vẫn ngồi bên ngọn đèn dầu bình dị để làm công việc khai trí, gây dựng phong trào cho một cộng đồng nhỏ bé nơi đất khách.\n\nCó một sự đối lập đáng suy ngẫm ở đây: cùng thời điểm ấy, tại các đô thị lớn của Pháp hay Liên Xô — những nơi ông từng sống và hoạt động trước khi tới Xiêm — điện đã thắp sáng khắp phố phường. Nhưng ông chọn trở về, chấp nhận sống trong điều kiện thiếu thốn như những người dân nghèo nhất, bởi mục tiêu của ông không phải là sự tiện nghi cho riêng mình, mà là gây dựng lực lượng ngay giữa lòng những cộng đồng còn khó khăn nhất.\n\nNgọn đèn dầu nhỏ bé ấy, vì thế, trở thành một hình ảnh giàu sức gợi trong câu chuyện về giai đoạn Thầu Chín: ánh sáng của tri thức, của tinh thần yêu nước, được thắp lên không phải từ những điều kiện đầy đủ, mà từ sự kiên trì bền bỉ trong hoàn cảnh thiếu thốn nhất.\n\nLoại đèn dầu hoả thân sắt tây hoặc thân thuỷ tinh, có bầu chứa dầu, bấc vải và ống khói bảo vệ ngọn lửa khỏi gió, là kiểu đèn phổ biến khắp Đông Dương và Xiêm La từ cuối thế kỷ 19 sang đầu thế kỷ 20, khi dầu hoả nhập khẩu bắt đầu thay thế dần dầu lạc, dầu dừa thắp sáng truyền thống. Với một xóm nghèo chưa có điện, mỗi lít dầu hoả đều phải cân nhắc chi tiêu, nên những buổi tối ngồi bên đèn dạy chữ, viết báo của ông Thầu Chín cũng đồng thời là những buổi tối cả xóm cùng san sẻ phần dầu ít ỏi ấy cho một việc chung mà ai cũng thấy cần thiết.","nguon":"Bảo tàng Hồ Chí Minh; Hồ Chí Minh – Biên niên tiểu sử, tập 1","doc":[{"t":"Ngọn đèn của những đêm dạy chữ. Cuối những năm 1920, điện lưới còn là điều xa lạ với hầu hết vùng nông thôn Đông Nam Á, và các xóm Việt kiều ở đông bắc Xiêm cũng không ngoại lệ. Mọi sinh hoạt buổi tối — nấu nướng, khâu vá, học hành, hội họp — đều trông vào ánh sáng nhỏ nhoi, ấm vàng của những ngọn đèn dầu: một bầu thủy tinh hoặc sắt tây đựng dầu hỏa, bấc vải xe nhỏ xuyên qua nắp, ánh lửa chỉ đủ soi rõ một góc bàn."},{"t":"Dưới ánh đèn dầu như thế, ông Thầu Chín đã thực hiện phần lớn những công việc trí óc quan trọng nhất trong hơn một năm sống ở Xiêm: dạy chữ quốc ngữ cho trẻ nhỏ và người lớn trong xóm vào buổi tối, dịch sách sang tiếng Việt, soạn bài cho báo Thân Ái, viết thư liên lạc với các cơ sở cách mạng trong nước. Ánh sáng yếu ớt, hay bị gió lùa tắt phụt giữa chừng, không ngăn được nhịp làm việc bền bỉ, đều đặn của ông sau mỗi ngày lao động chân tay vất vả."},{"t":"Chiếc đèn dầu đặt trong gian trưng bày, ngay trên chiếc bàn viết, là vật minh họa mang tính biểu tượng nhiều hơn là một hiện vật cụ thể còn giữ lại được. Nó đại diện cho vô số buổi tối thầm lặng như vậy — nơi một con người từng đi khắp các châu lục, tiếp xúc với văn minh phương Tây hiện đại, vẫn ngồi bên ngọn đèn dầu bình dị để làm công việc khai trí, gây dựng phong trào cho một cộng đồng nhỏ bé nơi đất khách."},{"t":"Có một sự đối lập đáng suy ngẫm ở đây: cùng thời điểm ấy, tại các đô thị lớn của Pháp hay Liên Xô — những nơi ông từng sống và hoạt động trước khi tới Xiêm — điện đã thắp sáng khắp phố phường. Nhưng ông chọn trở về, chấp nhận sống trong điều kiện thiếu thốn như những người dân nghèo nhất, bởi mục tiêu của ông không phải là sự tiện nghi cho riêng mình, mà là gây dựng lực lượng ngay giữa lòng những cộng đồng còn khó khăn nhất."},{"t":"Ngọn đèn dầu nhỏ bé ấy, vì thế, trở thành một hình ảnh giàu sức gợi trong câu chuyện về giai đoạn Thầu Chín: ánh sáng của tri thức, của tinh thần yêu nước, được thắp lên không phải từ những điều kiện đầy đủ, mà từ sự kiên trì bền bỉ trong hoàn cảnh thiếu thốn nhất."},{"t":"Loại đèn dầu hoả thân sắt tây hoặc thân thuỷ tinh, có bầu chứa dầu, bấc vải và ống khói bảo vệ ngọn lửa khỏi gió, là kiểu đèn phổ biến khắp Đông Dương và Xiêm La từ cuối thế kỷ 19 sang đầu thế kỷ 20, khi dầu hoả nhập khẩu bắt đầu thay thế dần dầu lạc, dầu dừa thắp sáng truyền thống. Với một xóm nghèo chưa có điện, mỗi lít dầu hoả đều phải cân nhắc chi tiêu, nên những buổi tối ngồi bên đèn dạy chữ, viết báo của ông Thầu Chín cũng đồng thời là những buổi tối cả xóm cùng san sẻ phần dầu ít ỏi ấy cho một việc chung mà ai cũng thấy cần thiết."}]},{"id":"binder_notebook@1.6,-1.3","x":1.6,"y":1.92,"z":-1.3,"loai":"binder_notebook","ten":"Tập giấy ghi chép","tieu_de":"Học tiếng Xiêm, dịch sách","text":"Một tập giấy mỏng, gấp đôi hoặc khâu tạm bằng chỉ, đủ để ghi chép chữ viết, từ vựng hay những dòng dịch thuật dở dang — đó là vật dụng học tập, làm việc giản đơn nhưng thiết yếu của bất kỳ ai theo đuổi việc tự học vào cuối thập niên 1920, khi giấy vở còn là thứ không phải gia đình nào cũng sẵn có, nhất là trong những xóm Việt kiều nghèo nơi đất khách.\n\nTheo cuốn \"Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch\" của Trần Dân Tiên, trong thời gian sống ở Xiêm, ông Thầu Chín đã chăm chỉ học tiếng Xiêm để có thể trực tiếp trò chuyện, tìm hiểu đời sống và giao thiệp với người dân bản xứ, thay vì chỉ quanh quẩn trong phạm vi cộng đồng người Việt. Song song đó, ông dịch sách sang tiếng Việt để kiều bào — nhất là những người vừa học xong lớp chữ quốc ngữ buổi tối — có thêm tài liệu học tập, mở mang hiểu biết.\n\nTập giấy ghi chép đặt trên bàn viết trong gian trưng bày là vật minh họa cho những công việc âm thầm ấy: những dòng từ vựng tiếng Xiêm mới học, những đoạn dịch thuật viết tay, những ghi chú chuẩn bị cho bài giảng tối hôm sau. Không có nhiều tư liệu mô tả chi tiết nội dung từng trang ghi chép cụ thể của ông trong giai đoạn này, nhưng việc ông kiên trì tự học ngôn ngữ địa phương mỗi khi đặt chân tới một vùng đất mới là điều được nhiều nguồn tư liệu về cuộc đời ông ghi nhận nhất quán.\n\nThói quen học ngoại ngữ ở mỗi nơi dừng chân — từ tiếng Pháp, tiếng Anh thời trẻ bôn ba trên tàu biển, đến tiếng Nga khi ở Liên Xô, tiếng Trung khi hoạt động tại Quảng Châu, và nay là tiếng Xiêm — không chỉ là một kỹ năng cá nhân, mà là công cụ để ông hiểu và gần gũi với nhân dân bản địa ở bất cứ đâu ông tới, từ đó dễ dàng hoà nhập, vận động và tổ chức phong trào cách mạng một cách hiệu quả hơn.\n\nChi tiết nhỏ về tập giấy ghi chép này, vì vậy, không chỉ nói về việc học một ngôn ngữ, mà còn phản ánh một phần cốt cách của Người: luôn coi việc tự học, tự trau dồi là công việc không thể ngơi nghỉ, dù đang sống giữa hoàn cảnh khó khăn, thiếu thốn nhất của một xóm Việt kiều nghèo bên đất Xiêm.\n\nXiêm La thời ấy là vương quốc độc lập duy nhất trong khu vực, không bị đặt dưới ách cai trị trực tiếp của bất kỳ cường quốc phương Tây nào, nên việc học tiếng Xiêm còn giúp ông Thầu Chín giao thiệp thuận lợi hơn với chính quyền và người dân sở tại — những người vốn có cảm tình với hoàn cảnh mất nước của Việt Nam. Vốn ngôn ngữ tích luỹ dần qua từng trang ghi chép như vậy, cộng với tiếng Pháp, tiếng Anh, tiếng Nga, tiếng Trung học được ở những chặng đường trước, đã góp phần tạo nên một nhà cách mạng có thể hoạt động, gây dựng cơ sở ở nhiều quốc gia khác nhau mà không bị rào cản ngôn ngữ ngăn trở.","nguon":"Trần Dân Tiên, Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch","doc":[{"t":"Học tiếng Xiêm, dịch sách. Một tập giấy mỏng, gấp đôi hoặc khâu tạm bằng chỉ, đủ để ghi chép chữ viết, từ vựng hay những dòng dịch thuật dở dang — đó là vật dụng học tập, làm việc giản đơn nhưng thiết yếu của bất kỳ ai theo đuổi việc tự học vào cuối thập niên 1920, khi giấy vở còn là thứ không phải gia đình nào cũng sẵn có, nhất là trong những xóm Việt kiều nghèo nơi đất khách."},{"t":"Theo cuốn \"Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch\" của Trần Dân Tiên, trong thời gian sống ở Xiêm, ông Thầu Chín đã chăm chỉ học tiếng Xiêm để có thể trực tiếp trò chuyện, tìm hiểu đời sống và giao thiệp với người dân bản xứ, thay vì chỉ quanh quẩn trong phạm vi cộng đồng người Việt. Song song đó, ông dịch sách sang tiếng Việt để kiều bào — nhất là những người vừa học xong lớp chữ quốc ngữ buổi tối — có thêm tài liệu học tập, mở mang hiểu biết."},{"t":"Tập giấy ghi chép đặt trên bàn viết trong gian trưng bày là vật minh họa cho những công việc âm thầm ấy: những dòng từ vựng tiếng Xiêm mới học, những đoạn dịch thuật viết tay, những ghi chú chuẩn bị cho bài giảng tối hôm sau. Không có nhiều tư liệu mô tả chi tiết nội dung từng trang ghi chép cụ thể của ông trong giai đoạn này, nhưng việc ông kiên trì tự học ngôn ngữ địa phương mỗi khi đặt chân tới một vùng đất mới là điều được nhiều nguồn tư liệu về cuộc đời ông ghi nhận nhất quán."},{"t":"Thói quen học ngoại ngữ ở mỗi nơi dừng chân — từ tiếng Pháp, tiếng Anh thời trẻ bôn ba trên tàu biển, đến tiếng Nga khi ở Liên Xô, tiếng Trung khi hoạt động tại Quảng Châu, và nay là tiếng Xiêm — không chỉ là một kỹ năng cá nhân, mà là công cụ để ông hiểu và gần gũi với nhân dân bản địa ở bất cứ đâu ông tới, từ đó dễ dàng hoà nhập, vận động và tổ chức phong trào cách mạng một cách hiệu quả hơn."},{"t":"Chi tiết nhỏ về tập giấy ghi chép này, vì vậy, không chỉ nói về việc học một ngôn ngữ, mà còn phản ánh một phần cốt cách của Người: luôn coi việc tự học, tự trau dồi là công việc không thể ngơi nghỉ, dù đang sống giữa hoàn cảnh khó khăn, thiếu thốn nhất của một xóm Việt kiều nghèo bên đất Xiêm."},{"t":"Xiêm La thời ấy là vương quốc độc lập duy nhất trong khu vực, không bị đặt dưới ách cai trị trực tiếp của bất kỳ cường quốc phương Tây nào, nên việc học tiếng Xiêm còn giúp ông Thầu Chín giao thiệp thuận lợi hơn với chính quyền và người dân sở tại — những người vốn có cảm tình với hoàn cảnh mất nước của Việt Nam. Vốn ngôn ngữ tích luỹ dần qua từng trang ghi chép như vậy, cộng với tiếng Pháp, tiếng Anh, tiếng Nga, tiếng Trung học được ở những chặng đường trước, đã góp phần tạo nên một nhà cách mạng có thể hoạt động, gây dựng cơ sở ở nhiều quốc gia khác nhau mà không bị rào cản ngôn ngữ ngăn trở."}]},{"id":"treasure_chest@2.3,0.6","x":2.3,"y":1.2,"z":0.6,"loai":"treasure_chest","ten":"Hòm gỗ","tieu_de":"Chiếc hòm cất sách báo","text":"Hòm gỗ đóng bằng ván dày, có nắp đậy và móc khóa đơn giản, là vật dụng quen thuộc trong hầu hết các gia đình Việt Nam thời trước, dùng để cất quần áo tốt, giấy tờ quan trọng, tiền bạc hay những vật có giá trị khác — thứ không thể để hớ hênh trong nhà tranh vách đất, nơi trộm cắp hay ẩm mốc đều có thể gây hư hại.\n\nVới những gia đình Việt kiều tham gia hoạt động cách mạng ở đông bắc Xiêm cuối những năm 1920, chiếc hòm gỗ còn mang thêm một chức năng đặc biệt: nơi cất giữ sách báo, tài liệu tuyên truyền, đôi khi cả những lá thư liên lạc. Việc bảo quản những thứ này đòi hỏi hết sức cẩn trọng, bởi mật thám Pháp vẫn có tai mắt cả trên đất Xiêm — vương quốc độc lập duy nhất trong khu vực, nhưng không vì thế mà nằm ngoài tầm theo dõi của thực dân Pháp đối với các cộng đồng người Việt bị coi là có biểu hiện yêu nước.\n\nTừ các xóm Việt kiều ven những vùng ông Thầu Chín từng sống — Phichit, Udon Thani, Sakon Nakhon, Nakhon Phanom — sách báo, tài liệu cách mạng được bí mật chuyển qua ngả Lào, vượt sông Mê Kông, rồi tìm đường về tới Nghệ An, Hà Tĩnh trong nước. Đây là một mắt xích quan trọng trong mạng lưới liên lạc giữa những người hoạt động cách mạng Việt Nam ở nước ngoài với phong trào yêu nước trong nước, và những chiếc hòm gỗ cất giấu tài liệu tại từng chặng dừng chân chính là nơi khởi đầu âm thầm của hành trình ấy.\n\nChiếc hòm trong gian trưng bày là vật minh họa, tái hiện một vật dụng thường ngày rất đỗi bình thường của nếp nhà Việt kiều, nhưng gợi lại công việc thầm lặng và không kém phần nguy hiểm phía sau vẻ ngoài giản dị đó. Không có ghi chép chi tiết nào còn lưu lại về những tài liệu cụ thể từng được cất trong một chiếc hòm nào đó tại Xiêm, nhưng việc tồn tại một đường dây chuyển tài liệu bí mật qua Lào về Nghệ Tĩnh trong giai đoạn này là điều đã được nhiều nguồn tư liệu về hoạt động cách mạng của Người xác nhận.\n\nCuối năm 1929, khi ông Thầu Chín rời Xiêm sang Hồng Kông chuẩn bị cho việc hợp nhất các tổ chức cộng sản, những cơ sở, đường dây liên lạc mà ông cùng bà con kiều bào dày công gây dựng suốt hơn một năm — trong đó có công việc cất giữ, vận chuyển tài liệu qua từng chiếc hòm gỗ như thế này — vẫn tiếp tục hoạt động, góp phần nối liền phong trào cách mạng trong và ngoài nước trong giai đoạn quan trọng ngay trước khi Đảng Cộng sản Việt Nam ra đời.\n\nViệc chọn Nghệ An, Hà Tĩnh làm điểm đến của những chuyến hàng bí mật ấy không phải ngẫu nhiên: đây chính là quê hương của ông Thầu Chín, vùng đất giàu truyền thống yêu nước, nơi chỉ ít năm sau, phong trào Xô viết Nghệ Tĩnh 1930–1931 sẽ bùng lên mạnh mẽ. Con đường tài liệu đi qua sông Mê Kông rồi vòng qua đất Lào trước khi về tới Nghệ Tĩnh (xem thêm chuyên đề Sông Mê Kông trong gian này) cho thấy một mạng lưới liên lạc xuyên biên giới đã được tổ chức khá bài bản, dù phương tiện chỉ là những chiếc hòm gỗ giản đơn như chiếc hòm được dựng lại nơi đây.","nguon":"Bảo tàng Hồ Chí Minh","doc":[{"t":"Chiếc hòm cất sách báo. Hòm gỗ đóng bằng ván dày, có nắp đậy và móc khóa đơn giản, là vật dụng quen thuộc trong hầu hết các gia đình Việt Nam thời trước, dùng để cất quần áo tốt, giấy tờ quan trọng, tiền bạc hay những vật có giá trị khác — thứ không thể để hớ hênh trong nhà tranh vách đất, nơi trộm cắp hay ẩm mốc đều có thể gây hư hại."},{"t":"Với những gia đình Việt kiều tham gia hoạt động cách mạng ở đông bắc Xiêm cuối những năm 1920, chiếc hòm gỗ còn mang thêm một chức năng đặc biệt: nơi cất giữ sách báo, tài liệu tuyên truyền, đôi khi cả những lá thư liên lạc. Việc bảo quản những thứ này đòi hỏi hết sức cẩn trọng, bởi mật thám Pháp vẫn có tai mắt cả trên đất Xiêm — vương quốc độc lập duy nhất trong khu vực, nhưng không vì thế mà nằm ngoài tầm theo dõi của thực dân Pháp đối với các cộng đồng người Việt bị coi là có biểu hiện yêu nước."},{"t":"Từ các xóm Việt kiều ven những vùng ông Thầu Chín từng sống — Phichit, Udon Thani, Sakon Nakhon, Nakhon Phanom — sách báo, tài liệu cách mạng được bí mật chuyển qua ngả Lào, vượt sông Mê Kông, rồi tìm đường về tới Nghệ An, Hà Tĩnh trong nước. Đây là một mắt xích quan trọng trong mạng lưới liên lạc giữa những người hoạt động cách mạng Việt Nam ở nước ngoài với phong trào yêu nước trong nước, và những chiếc hòm gỗ cất giấu tài liệu tại từng chặng dừng chân chính là nơi khởi đầu âm thầm của hành trình ấy."},{"t":"Chiếc hòm trong gian trưng bày là vật minh họa, tái hiện một vật dụng thường ngày rất đỗi bình thường của nếp nhà Việt kiều, nhưng gợi lại công việc thầm lặng và không kém phần nguy hiểm phía sau vẻ ngoài giản dị đó. Không có ghi chép chi tiết nào còn lưu lại về những tài liệu cụ thể từng được cất trong một chiếc hòm nào đó tại Xiêm, nhưng việc tồn tại một đường dây chuyển tài liệu bí mật qua Lào về Nghệ Tĩnh trong giai đoạn này là điều đã được nhiều nguồn tư liệu về hoạt động cách mạng của Người xác nhận."},{"t":"Cuối năm 1929, khi ông Thầu Chín rời Xiêm sang Hồng Kông chuẩn bị cho việc hợp nhất các tổ chức cộng sản, những cơ sở, đường dây liên lạc mà ông cùng bà con kiều bào dày công gây dựng suốt hơn một năm — trong đó có công việc cất giữ, vận chuyển tài liệu qua từng chiếc hòm gỗ như thế này — vẫn tiếp tục hoạt động, góp phần nối liền phong trào cách mạng trong và ngoài nước trong giai đoạn quan trọng ngay trước khi Đảng Cộng sản Việt Nam ra đời."},{"t":"Việc chọn Nghệ An, Hà Tĩnh làm điểm đến của những chuyến hàng bí mật ấy không phải ngẫu nhiên: đây chính là quê hương của ông Thầu Chín, vùng đất giàu truyền thống yêu nước, nơi chỉ ít năm sau, phong trào Xô viết Nghệ Tĩnh 1930–1931 sẽ bùng lên mạnh mẽ. Con đường tài liệu đi qua sông Mê Kông rồi vòng qua đất Lào trước khi về tới Nghệ Tĩnh (xem thêm chuyên đề Sông Mê Kông trong gian này) cho thấy một mạng lưới liên lạc xuyên biên giới đã được tổ chức khá bài bản, dù phương tiện chỉ là những chiếc hòm gỗ giản đơn như chiếc hòm được dựng lại nơi đây."},{"t":"Bạn có biết? Từ các xóm Việt kiều ở đông bắc Xiêm, tài liệu cách mạng được bí mật chuyển qua ngả Lào, vượt sông Mê Kông về Nghệ An, Hà Tĩnh, tạo thành một mắt xích liên lạc quan trọng giữa phong trào yêu nước trong và ngoài nước (nguồn: Bảo tàng Hồ Chí Minh)."}],"ban_co_biet":"Từ các xóm Việt kiều ở đông bắc Xiêm, tài liệu cách mạng được bí mật chuyển qua ngả Lào, vượt sông Mê Kông về Nghệ An, Hà Tĩnh, tạo thành một mắt xích liên lạc quan trọng giữa phong trào yêu nước trong và ngoài nước (nguồn: Bảo tàng Hồ Chí Minh)."}]};
